return $input.all().map(inputItem => {
  const item = inputItem.json;

  const html = item.data || "";
  const errorMessage =
    item.error?.message ||
    item.error ||
    item.message ||
    "";

  item.full_fetch_status = "ok";
  item.full_fetch_error = "";

  if (!html || html.length < 500) {
    item.full_fetch_status = "failed";
    item.full_fetch_error = "empty_or_short_html";
  }

  if (
    String(errorMessage).includes("403") ||
    String(errorMessage).includes("Forbidden") ||
    String(errorMessage).includes("Access Denied") ||
    html.includes("Access Denied") ||
    html.includes("Forbidden") ||
    html.includes("permission to access")
  ) {
    item.full_fetch_status = "failed";
    item.full_fetch_error = "access_denied";
  }

  return { json: item };
});

