parameters.jsCode:
return $input.all().map(inputItem => {
  const item = inputItem.json;

  let fullText =
    item.article_text ||
    item.full_text ||
    item.text ||
    item.description ||
    "";

  fullText = String(fullText)
    .replace(/\s+/g, " ")
    .trim();

  const sourceUrl = item.url || item.original_url || "";

  // sport.de: Anfang auf echten Artikelbeginn kürzen
  if (sourceUrl.includes("sport.de")) {
    const startPatterns = [
      "Er wurde als Backup",
      "Bleibt Nicolas Dzeko",
      "Eine DFB-Ikone",
      "S04-Coach"
    ];

    let bestIndex = -1;

    for (const pattern of startPatterns) {
      const index = fullText.indexOf(pattern);
      if (index >= 0 && (bestIndex === -1 || index < bestIndex)) {
        bestIndex = index;
      }
    }

    if (bestIndex > 0) {
      fullText = fullText.slice(bestIndex).trim();
    }

    const stopPatterns = [
      "Person Nicolas Dzeko",
      "Videos Opta",
      "34. Spieltag",
      "# Mannschaft",
      "Newsticker",
      "Torjäger",
      "Livekalender",
      "Impressum Datenschutz"
    ];

    for (const pattern of stopPatterns) {
      const index = fullText.indexOf(pattern);
      if (index > 500) {
        fullText = fullText.slice(0, index).trim();
        break;
      }
    }
  }

  // Allgemeine Müll- und CTA-Bereinigung
  const removePhrases = [
    "Drucken",
    "Teilen",
    "Kommentare",
    "Auch interessant",
    "Uns auf Google folgen",
    "Cookie-Einstellungen",
    "Datenschutz-Einstellungen ändern",
    "Absolut S04 - der Newsletter!",
    "Jetzt abonnieren und Teil der FCB-Community werden.",
    "Hier geht es nach einer kurzen Registrierung direkt zur Newsletter-Anmeldung.",
    "Fotostrecke ansehen"
  ];

  for (const phrase of removePhrases) {
    fullText = fullText.replaceAll(phrase, " ");
  }

  fullText = fullText
    .replace(/Anzeige/gi, " ")
    .replace(/Werbung/gi, " ")
    .replace(/Mehr zum Thema/gi, " ")
    .replace(/\s+([,.!?;:])/g, "$1")
    .replace(/\s+/g, " ")
    .trim();

  item.full_text = fullText;
  item.full_text_length = fullText.length;

  if (fullText.length > 800) {
    item.content_status = "full_text_ok";
  } else if (fullText.length > 0) {
    item.content_status = "full_text_too_short";
  } else {
    item.content_status = "full_text_missing";
  }

  return { json: item };
});

