parameters.jsCode:
// Parse Generated WP Content
// Parst OpenAI- und Claude-Output aus der Content-Generation.
// Holt die ursprünglichen Artikel-/Trello-Daten aus "Merge Article Input + Style Rules".

const aiItems = $input.all();

let sourceItems = [];

try {
  sourceItems = $items("Merge Article Input + Style Rules");
} catch (error) {
  try {
    sourceItems = $("Merge Article Input + Style Rules").all();
  } catch (secondError) {
    try {
      sourceItems = $items("Prepare WP Generation Payload");
    } catch (thirdError) {
      try {
        sourceItems = $("Prepare WP Generation Payload").all();
      } catch (fourthError) {
        sourceItems = [];
      }
    }
  }
}

function normalizeTags(value) {
  if (!value) return [];

  let tags = [];

  if (Array.isArray(value)) {
    tags = value;
  } else if (typeof value === "string") {
    tags = value.split(",").map(tag => tag.trim());
  }

  const forbidden = [
    "schalke",
    "schalke",
    "schalke",
    "transfer",
    "transfers",
    "bundesliga",
    "news",
    "gerücht",
    "gerüchte",
    "verletzung",
    "vertrag"
  ];

  return [...new Set(
    tags
      .map(tag => String(tag || "").trim())
      .filter(Boolean)
      .filter(tag => !forbidden.includes(tag.toLowerCase()))
  )].slice(0, 6);
}

function extractRawText(aiItem) {
  let raw = "";

  // OpenAI Responses API Format
  if (Array.isArray(aiItem.output)) {
    raw = aiItem.output
      .flatMap(outputItem => outputItem.content || [])
      .map(contentItem => contentItem.text || "")
      .join("\n")
      .trim();
  }

  // Claude / Anthropic Format: content[0].text
  if (!raw && Array.isArray(aiItem.content)) {
    raw = aiItem.content
      .map(part => part.text || part.content || "")
      .join("\n")
      .trim();
  }

  // Weitere Fallbacks
  if (!raw) {
    raw =
      aiItem.text ||
      aiItem.message?.content ||
      aiItem.choices?.[0]?.message?.content ||
      aiItem.response?.body?.choices?.[0]?.message?.content ||
      aiItem.data?.choices?.[0]?.message?.content ||
      "";
  }

  if (Array.isArray(raw)) {
    raw = raw
      .map(part => part.text || part.content || "")
      .join("\n");
  }

  if (typeof raw !== "string") {
    raw = JSON.stringify(raw || "");
  }

  return raw
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();
}

function extractJsonString(raw) {
  const firstBrace = raw.indexOf("{");
  const lastBrace = raw.lastIndexOf("}");

  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return raw.slice(firstBrace, lastBrace + 1);
  }

  return raw;
}

// Build lookup map from sourceItems by workflow_item_id for reliable matching
const sourceByWorkflowId = new Map();
for (const si of sourceItems) {
  const wid = String(si.json?.workflow_item_id || '').trim();
  if (wid) sourceByWorkflowId.set(wid, si.json);
}

return aiItems.map((inputItem, index) => {
  const aiItem = inputItem.json;

  // Prefer workflow_item_id match; fall back to pairedItem index; then positional index
  const pairedIdx = typeof inputItem.pairedItem === 'number'
    ? inputItem.pairedItem
    : (inputItem.pairedItem?.item ?? index);
  const pairedSource = sourceItems[pairedIdx]?.json || {};
  const wid = String(pairedSource.workflow_item_id || '').trim();
  const sourceItem = (wid && sourceByWorkflowId.has(wid))
    ? sourceByWorkflowId.get(wid)
    : (pairedSource.workflow_item_id ? pairedSource : (sourceItems[index]?.json || {}));

  const raw = extractRawText(aiItem);
  const jsonString = extractJsonString(raw);

  let parsed = {};

  try {
    parsed = JSON.parse(jsonString);
  } catch (error) {
    parsed = {
      generated_article: "",
      generated_meta: "",
      focus_keyphrase: "",
      wp_tags: [],
      draft_status: "parse_failed",
      draft_note: "KI-Ausgabe konnte nicht als valides JSON gelesen werden."
    };
  }

  const draftStatus = parsed.draft_status || "parse_failed";
  const generatedArticle = parsed.generated_article || "";
  const generatedMeta = parsed.generated_meta || "";
  const focusKeyphrase = parsed.focus_keyphrase || "";
  const wpTags = normalizeTags(parsed.wp_tags);

  const aiProvider = Array.isArray(aiItem.output)
    ? "openai"
    : Array.isArray(aiItem.content)
      ? "claude"
      : "unknown";

  return {
    json: {
      ...sourceItem,

      ai_provider: aiProvider,
      ai_response_id: aiItem.id || "",
      ai_model: aiItem.model || "",
      ai_status: aiItem.status || "",
      ai_created_at: aiItem.created_at || "",
      ai_usage: aiItem.usage || {},

      generated_article: generatedArticle,
      generated_meta: generatedMeta,
      focus_keyphrase: focusKeyphrase,
      wp_tags: draftStatus === "ready" ? wpTags : [],

      draft_status: draftStatus,
      draft_note: parsed.draft_note || "",
      raw_ai_output: raw,

      generated_article_length: generatedArticle.length,
      generated_article_word_count: generatedArticle
        .replace(/<[^>]*>/g, " ")
        .split(/\s+/)
        .filter(Boolean).length,

      generated_meta_length: generatedMeta.length,
      wp_tags_count: draftStatus === "ready" ? wpTags.length : 0,

      wp_generation_status:
        draftStatus === "ready" && generatedArticle.length > 500
          ? "generated"
          : "not_ready",

      dynamic_style_rules_title_used: sourceItem.dynamic_style_rules_title_used || "",
      dynamic_style_rules_title_count: sourceItem.dynamic_style_rules_title_count || 0,

      dynamic_style_rules_article_used: sourceItem.dynamic_style_rules_article_used || "",
      dynamic_style_rules_article_count: sourceItem.dynamic_style_rules_article_count || 0,

      style_rules_applied_at: sourceItem.style_rules_applied_at || ""
    }
  };
});

