parameters.jsCode:
// Extract Trello Card Data
// Sammelt Trello-Karten aus beiden Eingangslisten sauber ein:
//
// 1. Automation Artikelentwurf erstellen
// 2. Manuelle Artikelanlage
//
// Wichtig:
// - wp_approval_list wird anhand der Trello idList gesetzt
// - manuelle Artikelkarten brauchen keine URL
// - normale Workflow-Karten laufen wie bisher
// - Trello Card ID und List ID bleiben erhalten

const LISTS = {
  WP_DRAFT: {
    id: "6a3565aad9087a607f896265",
    name: "Automation Artikelentwurf erstellen",
  },
  MANUAL_ARTICLE: {
    id: "6a3565ae883da31cb298c6d0",
    name: "Manuelle Artikelanlage",
  },
};

function clean(value) {
  return String(value ?? "").trim();
}

function cleanUrl(raw) {
  let url = clean(raw);

  // Markdown-Link: [https://x.de/artikel](https://x.de/artikel "smartCard-inline")
  const md = url.match(/\[?(https?:\/\/[^\]\s)"]+)/);
  if (md) url = md[1];

  url = url.split("](")[0];
  url = url.split("#")[0];
  url = url.split("?")[0];
  url = url.replace(/[)"']+$/g, "");

  return url.trim();
}

function extractArticleUrl(desc, fallbackUrl) {
  const text = clean(desc);

  // Erst Link nach "🔗 Link:" suchen
  const linkSection = text.match(/🔗\s*Link:\s*([\s\S]*?)(?:\n\s*\n|⚡|---|$)/);

  if (linkSection) {
    const found = linkSection[1].match(/https?:\/\/[^\s\]\)"]+/);
    if (found) return cleanUrl(found[0]);
  }

  // Falls kein Link-Block erkannt wird: erste URL aus Description
  const anyUrl = text.match(/https?:\/\/[^\s\]\)"]+/);
  if (anyUrl) return cleanUrl(anyUrl[0]);

  // Fallback nur, wenn es KEINE Trello-URL ist
  const fallback = cleanUrl(fallbackUrl);
  if (fallback && !fallback.includes("trello.com/c/")) return fallback;

  return "";
}

function extractBetween(text, startLabel, endLabels = []) {
  const source = clean(text);
  const start = source.indexOf(startLabel);
  if (start === -1) return "";

  const after = source.slice(start + startLabel.length);

  let endIndex = after.length;

  for (const label of endLabels) {
    const idx = after.indexOf(label);
    if (idx !== -1 && idx < endIndex) endIndex = idx;
  }

  return after.slice(0, endIndex).trim();
}

function stripMarkdown(value) {
  return clean(value)
    .replace(/\*\*(.*?)\*\*/g, "$1")
    .replace(/__(.*?)__/g, "$1")
    .replace(/_(.*?)_/g, "$1")
    .replace(/\[(.*?)\]\((.*?)\)/g, "$1")
    .replace(/^#+\s*/gm, "")
    .replace(/\s+/g, " ")
    .trim();
}

function stripHtml(value) {
  return clean(value)
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#8222;/g, "„")
    .replace(/&#8220;/g, "“")
    .replace(/&#8221;/g, "“")
    .replace(/&#8211;/g, "–")
    .replace(/&#8212;/g, "—")
    .replace(/&#8217;/g, "’")
    .replace(/\s+/g, " ")
    .trim();
}

function getListName(idList) {
  const id = clean(idList);

  if (id === LISTS.WP_DRAFT.id) {
    return LISTS.WP_DRAFT.name;
  }

  if (id === LISTS.MANUAL_ARTICLE.id) {
    return LISTS.MANUAL_ARTICLE.name;
  }

  return "";
}

function isManualArticleCard(j, desc) {
  const idList = clean(j.idList);
  const listName = getListName(idList);

  if (listName === LISTS.MANUAL_ARTICLE.name) return true;

  // Fallback, falls idList irgendwann fehlt:
  // Manuelle Artikel sind oft lange fertige Texte ohne Workflow-Vorlage.
  const text = clean(desc);

  if (
    text.length > 1200 &&
    !text.includes("🤖 KI-/System-Output") &&
    !text.includes("📅 Datum:") &&
    !text.includes("⚡ Priorität:")
  ) {
    return true;
  }

  // HTML-Variante
  if (
    text.includes("<h1>") &&
    text.includes("</h1>")
  ) {
    return true;
  }

  return false;
}

function extractH1(desc) {
  const match = clean(desc).match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);

  if (match && clean(match[1])) {
    return stripHtml(match[1]);
  }

  return "";
}

function extractManualTitle(desc, cardName) {
  const h1 = extractH1(desc);
  if (h1) return h1;

  return clean(cardName);
}

function extractNormalGeneratedTitle(desc, cardName) {
  return (
    extractBetween(desc, "Generated Title:", ["Generated Social:", "Original Title:", "---"]) ||
    cardName
  );
}

function extractNormalGeneratedSocial(desc) {
  return extractBetween(desc, "Generated Social:", ["Original Title:", "---"]);
}

function extractNormalOriginalTitle(desc, cardName) {
  return (
    extractBetween(desc, "Original Title:", ["---", "✍️"]) ||
    cardName
  );
}

function extractPriority(desc) {
  const priorityMatch = clean(desc).match(/⚡\s*Priorität:\s*([0-9]+)/);
  return priorityMatch ? priorityMatch[1] : "";
}

function looksLikeDraftCreated(cardName, desc) {
  return (
    clean(desc).includes("✅ WP Draft erstellt") ||
    clean(cardName).includes("✅ WP Draft erstellt") ||
    clean(desc).includes("WP Post ID:") ||
    clean(desc).includes("WP Draft Link:")
  );
}

return $input.all().map((item, index) => {
  const j = item.json || {};

  const desc = clean(j.desc);
  const cardId = clean(j.id || j.trello_card_id);
  const idList = clean(j.idList);
  const cardName = clean(j.name || j.title);
  const cardUrl = clean(j.shortUrl || j.url);

  const wpApprovalList =
    getListName(idList) ||
    clean(j.wp_approval_list) ||
    LISTS.WP_DRAFT.name;

  const manualArticleMode = isManualArticleCard(j, desc);

  const articleUrl = manualArticleMode
    ? extractArticleUrl(desc, j.article_url || j.original_url)
    : extractArticleUrl(desc, j.article_url || j.original_url);

  const generatedTitle = manualArticleMode
    ? extractManualTitle(desc, cardName)
    : extractNormalGeneratedTitle(desc, cardName);

  const generatedSocial = manualArticleMode
    ? ""
    : extractNormalGeneratedSocial(desc);

  const originalTitle = manualArticleMode
    ? generatedTitle
    : extractNormalOriginalTitle(desc, cardName);

  const priority = manualArticleMode
    ? ""
    : extractPriority(desc);

  const draftAlreadyCreated = looksLikeDraftCreated(cardName, desc);

  return {
    json: {
      workflow_item_id: cardId || articleUrl || String(index),

      trello_card_id: cardId,
      trello_card_name: cardName,
      trello_card_url: cardUrl,
      trello_card_list_id: idList,
      idList,

      title: cardName || generatedTitle,
      generated_title: generatedTitle,
      generated_social: generatedSocial,
      original_title: originalTitle,

      source_name: "Trello",
      source_type: "trello_approved",
      priority,

      original_url: articleUrl,
      original_text: desc,

      wp_approval_status: "approved_from_trello",
      wp_approval_list: wpApprovalList,

      manual_article_mode: manualArticleMode,
      content_origin: manualArticleMode ? "manual_editor_input" : "automation_input",

      draft_already_created: draftAlreadyCreated,

      // Normale Workflow-Karten brauchen URL.
      // Manuelle Karten dürfen auch ohne URL weiterlaufen.
      has_url: manualArticleMode ? true : Boolean(articleUrl),

      original_source_name: "Trello",
      original_source_type: "trello_approved",
      original_priority: priority,
      original_s04_relevance: "",

      extract_trello_debug: {
        idList,
        resolved_wp_approval_list: wpApprovalList,
        manual_article_mode: manualArticleMode,
        article_url_found: Boolean(articleUrl),
        desc_length: desc.length,
        card_closed: Boolean(j.closed),
      },
    },
  };
});

return $input.all().map(inputItem => {
  const item = inputItem.json;

  // Unterstützt normalen HTTP Fetch UND Apify-Fallback
  let html = String(
    item.data ||
    item.html ||
    item.text ||
    item.markdown ||
    item.content ||
    item.articleText ||
    item.article_text ||
    ""
  );

  function decodeEntities(value) {
    return String(value)
      .replace(/&nbsp;/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/&quot;/g, "\"")
      .replace(/&#34;/g, "\"")
      .replace(/&#39;/g, "'")
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&auml;/g, "ä")
      .replace(/&ouml;/g, "ö")
      .replace(/&uuml;/g, "ü")
      .replace(/&Auml;/g, "Ä")
      .replace(/&Ouml;/g, "Ö")
      .replace(/&Uuml;/g, "Ü")
      .replace(/&szlig;/g, "ß")
      .replace(/&copy;/g, "©");
  }

  function stripTags(value) {
    return decodeEntities(value)
      .replace(/<script[\s\S]*?<\/script>/gi, " ")
      .replace(/<style[\s\S]*?<\/style>/gi, " ")
      .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
      .replace(/<iframe[\s\S]*?<\/iframe>/gi, " ")
      .replace(/<svg[\s\S]*?<\/svg>/gi, " ")
      .replace(/<figure[\s\S]*?<\/figure>/gi, " ")
      .replace(/<aside[\s\S]*?<\/aside>/gi, " ")
      .replace(/<nav[\s\S]*?<\/nav>/gi, " ")
      .replace(/<footer[\s\S]*?<\/footer>/gi, " ")
      .replace(/<header[\s\S]*?<\/header>/gi, " ")
      .replace(/<[^>]+>/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  function cleanPlainText(value) {
    return decodeEntities(value)
      .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1") // Markdown Links
      .replace(/!\[[^\]]*\]\([^)]+\)/g, " ") // Markdown Images
      .replace(/#{1,6}\s*/g, "") // Markdown Headlines
      .replace(/\*\*/g, "")
      .replace(/\*/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }

  function extractIppenStoryElementsInOrder() {
    const regex = /<(p|h2)[^>]*class=(?:"[^"]*(id-StoryElement-leadText|id-StoryElement-paragraph|id-StoryElement-crosshead)[^"]*"|'[^']*(id-StoryElement-leadText|id-StoryElement-paragraph|id-StoryElement-crosshead)[^']*'|[^\s>]*(id-StoryElement-leadText|id-StoryElement-paragraph|id-StoryElement-crosshead)[^\s>]*)[^>]*>([\s\S]*?)<\/\1>/gi;

    const parts = [];
    let match;

    while ((match = regex.exec(html)) !== null) {
      const text = stripTags(match[5]);
      if (text.length > 20) {
        parts.push(text);
      }
    }

    return parts;
  }

  let articleText = "";

  // 1. Spezialfall tz / merkur / Ippen
  const ippenParts = extractIppenStoryElementsInOrder();

  if (ippenParts.length >= 2) {
    articleText = ippenParts.join("\n\n");
    item.article_extract_method = "ippen_story_elements";
  }

  // 2. Falls Apify bereits sauberen Markdown/Text liefert
  if ((!articleText || articleText.length < 500) && (item.markdown || item.text || item.content || item.articleText)) {
    const plainText = cleanPlainText(
      item.markdown ||
      item.text ||
      item.content ||
      item.articleText ||
      ""
    );

    if (plainText.length >= 500) {
      articleText = plainText;
      item.article_extract_method = item.markdown ? "apify_markdown" : "apify_text";
    }
  }

  // 3. HTML article-Tag
  if (!articleText || articleText.length < 500) {
    const articleMatch = html.match(/<article\b[^>]*>([\s\S]*?)<\/article>/i);
    if (articleMatch) {
      articleText = stripTags(articleMatch[1]);
      item.article_extract_method = "html_article_tag";
    }
  }

  // 4. HTML body fallback
  if (!articleText || articleText.length < 500) {
    const bodyMatch = html.match(/<body\b[^>]*>([\s\S]*?)<\/body>/i);
    articleText = bodyMatch ? stripTags(bodyMatch[1]) : stripTags(html);
    item.article_extract_method = "html_fallback";
  }

  articleText = String(articleText)
    .replace(/\s+([,.!?;:])/g, "$1")
    .replace(/\s+/g, " ")
    .trim();

  item.article_text = articleText;
  item.article_text_length = articleText.length;

  // Große Rohfelder nach Extraktion entfernen
  delete item.data;
  delete item.html;
  delete item.markdown;
  delete item.content;
  delete item.articleText;

  return { json: item };
});

return $input.all().map(inputItem => {
  const item = inputItem.json || {};

  const clean = (value) => String(value ?? "").trim();

  const fullText = clean(
