const aiItems = $input.all();

function normalizeTags(value) {
  let tags = [];

  if (Array.isArray(value)) {
    tags = value;
  } else if (typeof value === "string") {
    tags = value.split(",").map(tag => tag.trim());
  }

  const forbidden = [
    "schalke",
    "schalke",
    "schalke",
    "transfer",
    "transfers",
    "bundesliga",
    "news",
    "gerücht",
    "gerüchte",
    "verletzung",
    "vertrag"
  ];

  return [...new Set(
    tags
      .map(tag => String(tag || "").trim())
      .filter(Boolean)
      .filter(tag => !forbidden.includes(tag.toLowerCase()))
  )].slice(0, 6);
}

function extractRawText(aiItem) {
  if (Array.isArray(aiItem.content)) {
    return aiItem.content
      .map(part => part.text || "")
      .join("\n")
      .replace(/```json/gi, "")
      .replace(/```/g, "")
      .trim();
  }

  if (Array.isArray(aiItem.output)) {
    return aiItem.output
      .flatMap(outputItem => outputItem.content || [])
      .map(contentItem => contentItem.text || "")
      .join("\n")
      .replace(/```json/gi, "")
      .replace(/```/g, "")
      .trim();
  }

  return String(
    aiItem.text ||
    aiItem.message?.content ||
    aiItem.choices?.[0]?.message?.content ||
    ""
  )
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();
}

function extractJsonString(raw) {
  const firstBrace = raw.indexOf("{");
  const lastBrace = raw.lastIndexOf("}");

  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return raw.slice(firstBrace, lastBrace + 1);
  }

  return raw;
}

function cleanArticleHtml(value) {
  return String(value || "")
    .replace(/&nbsp;/gi, "")
    .replace(/\u00a0/g, "")
    .replace(/^\s+|\s+$/g, "")
    .replace(/^(<p>\s*<\/p>|<br\s*\/?>)+/gi, "")
    .replace(/(<p>\s*<\/p>|<br\s*\/?>)+$/gi, "")
    .trim();
}

return aiItems.map((inputItem, index) => {
  const aiItem = inputItem.json || {};

  let sourceItem = {};
  try {
    const sourceItems = $items("Rewrite Already Tried?", 1);
    sourceItem = sourceItems[index]?.json || {};
  } catch (error) {}

  const raw = extractRawText(aiItem);
  const jsonString = extractJsonString(raw);

  let parsed = {};
  try {
    parsed = JSON.parse(jsonString);
  } catch (error) {
    parsed = {};
  }

  const rewrittenArticle = cleanArticleHtml(parsed.generated_article);
  const rewrittenMeta = String(parsed.generated_meta || "").trim();
  const rewrittenFocusKeyphrase = String(parsed.focus_keyphrase || "").trim();
  const draftStatus = String(parsed.draft_status || "parse_failed").trim();

  const rewrittenWpTags = normalizeTags(parsed.wp_tags);
  const wordCount = rewrittenArticle
    .replace(/<[^>]*>/g, " ")
    .split(/\s+/)
    .filter(Boolean).length;

  const h2Count = (rewrittenArticle.match(/<h2>/gi) || []).length;

  const hasStrongIntro =
    /^<p>\s*<strong>[\s\S]*?<\/strong>\s*<\/p>/i.test(rewrittenArticle);

  const wpTitle = String(
    sourceItem.wp_title ||
    sourceItem.generated_title ||
    sourceItem.generated_trello_title ||
    sourceItem.title ||
    ""
  ).trim();

  return {
    json: {
      workflow_item_id: sourceItem.workflow_item_id || sourceItem.trello_card_id || "",
      trello_card_id: sourceItem.trello_card_id || "",
      trello_card_url: sourceItem.trello_card_url || "",
      source_url: sourceItem.source_url || sourceItem.original_url || sourceItem.url || "",

      generated_title: sourceItem.generated_title || sourceItem.title || "",
      generated_article: sourceItem.generated_article || "",
      generated_meta: sourceItem.generated_meta || "",
      generated_social: sourceItem.generated_social || "",

      rewritten_article: rewrittenArticle,
      rewritten_meta: rewrittenMeta,
      rewritten_focus_keyphrase: rewrittenFocusKeyphrase,
      rewritten_wp_tags: rewrittenWpTags,

      wp_create_title: wpTitle,
      wp_create_content: rewrittenArticle,
      wp_create_meta: rewrittenMeta,
      wp_create_focus_keyphrase: rewrittenFocusKeyphrase,
      wp_create_tags: rewrittenWpTags,

      draft_status: draftStatus,
      draft_note: String(parsed.draft_note || "").trim(),

      raw_ai_output: raw,
      rewrite_attempted: true,

      rewritten_article_length: rewrittenArticle.length,
      rewritten_article_word_count: wordCount,
      rewritten_meta_length: rewrittenMeta.length,
      article_h2_count: h2Count,
      article_has_strong_intro: hasStrongIntro,

      wp_generation_status:
        draftStatus === "ready" &&
        rewrittenArticle.length >= 1200 &&
        wordCount >= 220 &&
        h2Count >= 1 &&
        h2Count <= 2 &&
        hasStrongIntro
          ? "ready_for_wp"
          : "not_ready",

      parse_rewrite_debug: {
        parsed_article_found: Boolean(rewrittenArticle),
        parsed_article_length: rewrittenArticle.length,
        raw_starts_with: raw.slice(0, 80),
        source_item_found: Object.keys(sourceItem).length > 0
      }
    }
  };
});

