// Restore Original Data After WP
// Stabiler Merge nach wp_article_key / Trello Card ID / Source URL,
// Fallback nach bereinigtem Titel.
// Zusätzlich: leere/kaputte WP-Responses werden nicht als echte Artikel behandelt.
// Ergänzt: technische Felder für Yoast Meta, Haupt-Fokus-Keyphrase,
// relevante Yoast-Keyphrases und XPoster vorbereiten.
// Update: Yoast-Keyphrases priorisieren Personennamen (Namen zuerst, Sachbegriffe dahinter),
// volle "Vorname Nachname"-Paare werden auf den Nachnamen reduziert.

function clean(value) {
  return String(value ?? '').trim();
}

function normalize(value) {
  return clean(value)
    .toLowerCase()
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .replace(/[„“"]/g, '"')
    .trim();
}

function cleanTitleForMatch(value) {
  return normalize(value)
    .replace(/\[originalbeschreibung gekürzt\]/gi, '')
    .replace(/\[kontextprüfung gekürzt[^\]]*\]/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeUrl(value) {
  return clean(value)
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .replace(/\/$/, '')
    .trim()
    .toLowerCase();
}

function makeArticleKey(value) {
  return clean(value);
}

function makeArticleKeyFromOriginal(original) {
  return makeArticleKey(
    original.wp_article_key ||
    original.wp_trello_card_id ||
    original.trello_update_card_id_backup ||
    original.trello_update_card_id ||
    original.trello_card_id ||
    original.wp_source_url ||
    original.original_url ||
    original.source_url
  );
}

function makeUrlKeyFromOriginal(original) {
  return normalizeUrl(
    original.wp_source_url ||
    original.original_url ||
    original.source_url ||
    original.url
  );
}

function makeArticleKeyFromWp(wp) {
  return makeArticleKey(
    wp.wp_article_key ||
    wp.meta?.wp_article_key ||
    wp.meta?.trello_card_id ||
    wp.meta?.wp_trello_card_id ||
    ''
  );
}

function dedupe(values) {
  const output = [];
  const seen = new Set();

  for (const value of values) {
    const cleanValue = clean(value);
    if (!cleanValue) continue;

    const key = cleanValue.toLowerCase();
    if (seen.has(key)) continue;

    seen.add(key);
    output.push(cleanValue);
  }

  return output;
}

function extractYoastKeyphrases(value) {
  const raw = clean(value);

  if (!raw) {
    return {
      primary: '',
      related: [],
      relatedJson: '[]',
    };
  }

  // Reine Funktions-/Füllwörter, die nie als Keyphrase taugen.
  const fillerWords = new Set([
    'fc', 's04', 'schalke', 'und', 'oder', 'über', 'ueber', 'gegen', 'beim',
    'vom', 'zum', 'zur', 'mit', 'ohne', 'nach', 'vor', 'für', 'fuer',
    'der', 'die', 'das', 'ein', 'eine', 'einer', 'eines', 'im', 'in', 'am', 'an',
  ]);

  // Sachbegriffe: gültige Keyphrases, aber KEINE Personennamen.
  // Werden hinter die Namen sortiert.
  const topicWords = new Set([
    'schalke', 'gelsenkirchen', 'munchen', 'deutschland', 'dfb', 'vfb',
    'league', 'champions', 'bundesliga', 'pokalfinale', 'pokal',
    'transfer', 'wechsel', 'leihe', 'vertrag', 'verlängerung', 'verlaengerung',
    'verletzung', 'comeback', 'zukunft', 'saison', 'trainer', 'spieler',
    'torjäger', 'torjaeger', 'stürmer', 'stuermer', 'star', 'boss', 'coach',
    'elfmeter', 'kritik', 'debatte', 'diskussion', 'aussage', 'interview',
    'reaktion', 'analyse', 'gerücht', 'geruecht', 'angebot', 'ablöse', 'abloese',
    'wm', 'em', 'tor', 'tore', 'rekord', 'startelf', 'aufstellung', 'kader',
    'durchbruch', 'einigung', 'medizincheck',
  ]);

  // Bekannte Vornamen -> nur damit wird ein "Vorname Nachname"-Paar erkannt
  // und auf den Nachnamen reduziert. Liste bei Bedarf erweitern.
  const firstNames = new Set([
    'harry', 'jamal', 'leroy', 'serge', 'kingsley', 'alphonso', 'dayot',
    'joshua', 'leon', 'manuel', 'thomas', 'aleksandar', 'konrad', 'mathys',
    'michael', 'raphael', 'sacha', 'josip', 'hiroki', 'min', 'min-jae', 'eric',
    'daniel', 'sven', 'nathaniel', 'adam', 'paul', 'vincent', 'max', 'christoph',
    'jan', 'karl-heinz', 'herbert', 'deniz', 'kevin', 'kevin-prince', 'jonathan',
    'dominik', 'tom', 'tim', 'felix', 'lukas', 'niklas', 'florian', 'jonas',
    'nico', 'niko', 'robert', 'lars', 'ole', 'carsten', 'patrick', 'fabrizio',
    'julian', 'marcel', 'marco', 'mario', 'david', 'kim', 'pascal',
  ]);

  function isFiller(word) {
    return fillerWords.has(clean(word).toLowerCase());
  }

  function isTopic(word) {
    return topicWords.has(clean(word).toLowerCase());
  }

  function isFirstName(word) {
    return firstNames.has(clean(word).toLowerCase());
  }

  // Heuristik: Personenname = großgeschrieben, kein Füllwort, kein Sachbegriff.
  function looksLikeName(word) {
    const w = clean(word);
    if (!w) return false;
    if (isFiller(w) || isTopic(w)) return false;
    return /^[A-ZÄÖÜ]/.test(w);
  }

  // Letztes sinnvolles Wort einer Phrase (= Nachname).
  function surnameFromPhrase(phrase) {
    const words = clean(phrase)
      .split(/\s+/)
      .map(clean)
      .filter(Boolean)
      .filter(word => !isFiller(word));

    if (!words.length) return '';
    return words[words.length - 1];
  }

  // Eine zusammenhängende Namens-Kette reduzieren:
  // "Vorname Nachname" (erstes Wort ist bekannter Vorname) -> nur Nachname.
  // Sonst Wort einzeln behalten (z. B. "Schallenberg", "Kalas").
  function reduceNameRun(run) {
    const out = [];
    let k = 0;
    while (k < run.length) {
      const cur = run[k];
      const next = run[k + 1];
      if (next && isFirstName(cur)) {
        out.push(next); // Vorname + Nachname -> Nachname
        k += 2;
      } else {
        out.push(cur);
        k += 1;
      }
    }
    return out;
  }

  const names = [];
  const topics = [];

  // Fall 1: explizit getrennte Phrasen (Komma/Semikolon/Slash/Pipe)
  // -> pro Phrase den Nachnamen ziehen, Reihenfolge beibehalten.
  const separated = raw
    .split(/[,;|/]+/)
    .map(clean)
    .filter(Boolean);

  if (separated.length > 1) {
    for (const phrase of separated) {
      const surname = surnameFromPhrase(phrase);
      if (!surname) continue;
      if (isTopic(surname)) topics.push(surname);
      else names.push(surname);
    }
  } else {
    // Fall 2: eine Phrase ohne Trennzeichen -> Wörter durchgehen,
    // zusammenhängende Namens-Ketten als Gruppe reduzieren.
    const words = raw
      .split(/\s+/)
      .map(clean)
      .filter(Boolean)
      .filter(word => !isFiller(word));

    let i = 0;
    while (i < words.length) {
      if (looksLikeName(words[i])) {
        const run = [];
        while (i < words.length && looksLikeName(words[i])) {
          run.push(words[i]);
          i += 1;
        }
        for (const name of reduceNameRun(run)) names.push(name);
      } else {
        topics.push(words[i]);
        i += 1;
      }
    }
  }

  // Namen zuerst, danach Sachbegriffe. Dedupliziert.
  const ordered = dedupe([...names, ...topics]);

  const primary = ordered[0] || '';
  const related = ordered.slice(1);

  return {
    primary,
    related,
    relatedJson: JSON.stringify(
      related.map(keyword => ({
        keyword,
        score: 'na',
      }))
    ),
  };
}

function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function getSurname(name) {
  const parts = clean(name)
    .split(/\s+/)
    .map(clean)
    .filter(Boolean);

  return parts.length > 1 ? parts[parts.length - 1] : parts[0] || '';
}

function buildXPosterText(title, tags = []) {
  let text = clean(title);

  if (!text) {
    return '#schalke #url#';
  }

  text = text
    .replace(/\bFC\s+S04\b/gi, '#FCS04')
    .replace(/\bFCS04\b/gi, '#FCS04')
    .replace(/\bS04\b/gi, '#FCS04');

  const protectedHashtags = new Set();

  for (const match of text.matchAll(/#[A-Za-zÄÖÜäöüß0-9_]+/g)) {
    protectedHashtags.add(match[0].toLowerCase());
  }

  const blockWords = new Set([
    'fc',
    's04',
    'schalke',
    'schalke',
    'gelsenkirchen',
    'munchen',
    'vfb',
    'stuttgart',
    'dfb',
    'sky',
    'bild',
    'tz',
    'kicker',
  ]);

  const candidateNames = [];

  if (Array.isArray(tags)) {
    for (const tag of tags) {
      const cleanTag = clean(tag);
      if (!cleanTag) continue;

      const surname = getSurname(cleanTag);
      if (!surname) continue;

      const key = surname.toLowerCase();
      if (blockWords.has(key)) continue;

      candidateNames.push(surname);
    }
  }

  const extraCandidates = [
    'Karius',
    'Kalas',
    'Katić',
    'Kurucay',
    'Ayhan',
    'Becker',
    'Schallenberg',
    'Bachmann',
    'Ljubičić',
    'Aouchiche',
    'Porath',
    'Karaman',
    'Sylla',
    'Džeko',
    'Lasme',
    'Muslić',
    'Tillmann',
    'Baumann',
    'Hefer',
  ];

  candidateNames.push(...extraCandidates);

  const uniqueNames = dedupe(candidateNames)
    .sort((a, b) => b.length - a.length);

  for (const name of uniqueNames) {
    const key = `#${name}`.toLowerCase();

    if (protectedHashtags.has(key)) continue;

    const regex = new RegExp(`(?<![#\\p{L}\\p{N}])${escapeRegExp(name)}(?![\\p{L}\\p{N}])`, 'giu');

    text = text.replace(regex, match => {
      if (match.startsWith('#')) return match;
      return `#${match}`;
    });
  }

  text = text
    .replace(/##+/g, '#')
    .replace(/#FCS04-#Stars?/g, '#FCS04-Stars')
    .replace(/#FCS04-#Star/g, '#FCS04-Star')
    .replace(/\s+/g, ' ')
    .trim();

  if (!/#schalke\b/i.test(text)) {
    text = `${text} #schalke`;
  }

  text = text.replace(/\s*#url#\s*$/i, '').trim();
  text = `${text} #url#`;

