  const wpWorkflowItemId = String(wp.workflow_item_id || '').trim();
  if (wpWorkflowItemId && originalsByWorkflowId.has(wpWorkflowItemId)) {
    original = originalsByWorkflowId.get(wpWorkflowItemId);
