  }

  // Extra-Fallback:
  // Falls WordPress den bereinigten Titel anders speichert,
  // versuchen wir einen contains-Match über bereinigte Titel.
  if (!original && wpTitleKey) {
    for (const [titleKey, candidate] of originalsByTitle.entries()) {
