  const wantedName = original.wp_tag_name;
  const wantedSlug = original.wp_tag_slug || normalizeSlug(wantedName);

  const wantedNameNorm = normalizeName(wantedName);
  const wantedSlugNorm = normalizeSlug(wantedSlug);

