    if (tagName.includes(',')) return false;

    const tagNameNorm = normalizeName(tagName);
    const tagSlugNorm = normalizeSlug(tagSlug);

    return (
      tagNameNorm === wantedNameNorm ||
      tagSlugNorm === wantedSlugNorm
    );
  });

  output.push({
    json: {
