        wp_vgwort_ready: false,
        wp_vgwort_error: 'Verify VG Wort Counter returned a list instead of one post. Fix the URL to include wp_post_id.',
        wp_vgwort_raw_response: j,
      },
    });
    continue;
  }

  const postId = j.id || j.wp_post_id || '';
  const postStatus = clean(j.status);

  const worthyCounter = firstValue(j.meta?.worthy_counter);

  const worthyPixelUrl =
    clean(j['wp-worthy-pixel']?.url) ||
    clean(j.wp_worthy_pixel_url);

  const worthyPixelPublic =
    clean(j['wp-worthy-pixel']?.public);

  const worthyPixelServer =
    clean(j['wp-worthy-pixel']?.server);

  const hasCounter = Boolean(worthyCounter);
  const hasPixel = Boolean(worthyPixelUrl || worthyPixelPublic);

  let status = 'missing';
  let note = 'No VG Wort/Worthy counter found.';

  if (hasCounter && hasPixel) {
    status = 'ready';
    note = 'VG Wort/Worthy counter and pixel are assigned.';
  } else if (hasCounter && !hasPixel) {
    status = 'counter_only';
    note = 'Worthy counter exists, but VG Wort pixel URL is not visible yet.';
  }

  output.push({
    json: {
      ...j,

      wp_vgwort_post_id: postId,
      wp_vgwort_post_status: postStatus,

      wp_vgwort_counter: worthyCounter,
      wp_vgwort_pixel_url: worthyPixelUrl,
      wp_vgwort_pixel_public: worthyPixelPublic,
      wp_vgwort_pixel_server: worthyPixelServer,

      wp_vgwort_ready: status === 'ready',
      wp_vgwort_status: status,
      wp_vgwort_note: note,
    },
  });
}

return output;

// Prepare Trello Draft Created Update
// Baut das Trello-Update nach WP-Draft-Erstellung.
//
// Regeln:
// - Nicht-externer Pfad bleibt wie bisher:
//   WP Draft Block + Kontext falls vorhanden + alte Originalbeschreibung, solange Platz ist.
// - Google/externer Pfad:
//   WP Draft Block + Kontext direkt darunter + kompakter Original-/Quellenblock.
//   Keine komplette alte Trello-Beschreibung.
//   SmartCard-Markdown-Links werden bereinigt.
//   Description wird für normalen Trello-Node sicher begrenzt.
// - Kein Kontext-Mixing per Index.

function clean(value) {
  return String(value ?? '').trim();
}

function getNested(obj, path) {
  return path.split('.').reduce((acc, key) => {
    if (acc && Object.prototype.hasOwnProperty.call(acc, key)) {
      return acc[key];
    }
    return undefined;
  }, obj);
}

function pickFirstFromObjects(objects, paths) {
  for (const obj of objects) {
    if (!obj || typeof obj !== 'object') continue;

    for (const path of paths) {
      const value = path.includes('.') ? getNested(obj, path) : obj[path];
      const cleaned = clean(value);
      if (cleaned) return cleaned;
    }
  }

  return '';
}

function cleanCardTitle(value) {
  return clean(value)
    .replace(/\[Originalbeschreibung gekürzt\]/gi, '')
    .replace(/\[Kontextprüfung gekürzt[^\]]*\]/gi, '')
    .replace(/\n+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function pickBestTitle(objects, paths) {
  const candidates = [];

  for (const obj of objects) {
    if (!obj || typeof obj !== 'object') continue;

    for (const path of paths) {
      const value = path.includes('.') ? getNested(obj, path) : obj[path];
      const cleaned = cleanCardTitle(value);

      if (!cleaned) continue;

      const looksBroken =
        cleaned.includes('[Originalbeschreibung gekürzt]') ||
        cleaned.includes('[Kontextprüfung gekürzt') ||
        cleaned.length < 18 ||
        /^Generate$/i.test(cleaned) ||
        /^Generated Title:?$/i.test(cleaned);

      if (!looksBroken) candidates.push(cleaned);
    }
  }

  return candidates[0] || '';
}

function getAllNodeItems(nodeName) {
  try {
    return $(nodeName).all().map(item => item.json || {});
  } catch (error) {
    return [];
  }
}

function isLikelyTrelloCardId(value) {
  return /^[a-f0-9]{24}$/i.test(clean(value));
}

function normalizeUrl(value) {
  return clean(value)
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .replace(/\/$/, '')
    .trim();
}

function separator() {
  return '────────────────────';
}

function formatDateGerman() {
  return new Intl.DateTimeFormat('de-DE', {
    timeZone: 'Europe/Berlin',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(new Date()) + ' Uhr';
}

function cleanBooleanLabel(value) {
  if (value === true || value === 'true') return 'ja';
  if (value === false || value === 'false') return 'nein';
  return clean(value);
}

function contextModeLabel(mode) {
  const value = clean(mode);

  if (value === 'internal_only') return 'SCHALKETOTAL-Kontext';
  if (value === 'external_only') return 'Externer Web-Kontext';
  if (value === 'external_only_pending_unified') return 'Externer Web-Kontext';
  if (value === 'internal_and_external') return 'SCHALKETOTAL + externer Web-Kontext';

  return value;
}

function buildText(parts) {
  return parts
    .filter(part => part !== null && part !== undefined && part !== '')
    .join('\n')
    .replace(/\n{4,}/g, '\n\n\n')
    .trim();
}

function stripSmartCardMarkdown(value) {
  const text = clean(value);

  // Trello SmartCard:
  // [https://example.com](https://example.com "smartCard-inline")
  const markdownMatch = text.match(/\[([^\]]+)\]\(([^)\s]+)(?:\s+"[^"]*")?\)/);

  if (markdownMatch && markdownMatch[2]) {
    return markdownMatch[2].trim();
  }

  return text;
}

function limitText(text, maxLength, suffix) {
  const value = clean(text);

  if (!value) return '';
  if (maxLength <= 0) return '';
  if (value.length <= maxLength) return value;

  return value.slice(0, Math.max(0, maxLength)).trim() + suffix;
}

function limitOriginalDesc(originalDesc, maxLength) {
  return limitText(
    originalDesc,
    maxLength,
    '\n\n[Originalbeschreibung gekürzt, weil WP-Daten + Kontext bereits sehr lang sind.]'
  );
}

function limitExternalContext(contextText, maxLength) {
  return limitText(
    contextText,
    maxLength,
    '\n\n[Externer Kontext in Trello gekürzt, damit der normale Trello-Node nicht mit CloudFront 414 abbricht.]'
  );
}

function extractBetween(text, startLabel, endLabels = []) {
  const source = String(text || '');
  const startIndex = source.indexOf(startLabel);

  if (startIndex === -1) return '';

  const afterStart = source.slice(startIndex + startLabel.length);
  let endIndex = afterStart.length;

  for (const label of endLabels) {
    const idx = afterStart.indexOf(label);
    if (idx !== -1 && idx < endIndex) endIndex = idx;
  }

  return afterStart.slice(0, endIndex).trim();
}

function removeMarkdownLink(value) {
  return stripSmartCardMarkdown(value);
}

function getOriginalLinkFromDesc(originalDesc) {
  const linkBlock = extractBetween(originalDesc, '🔗 Link:', [
    '⚡ Priorität:',
    '---',
    '🤖 KI-/System-Output',
  ]);

  return removeMarkdownLink(linkBlock);
}

function getOriginalSocialFromDesc(originalDesc) {
  return extractBetween(originalDesc, '💬 Social:', [
    '---',
    '🔗 Link:',
  ]);
}

function getGeneratedTitleFromDesc(originalDesc) {
  return cleanCardTitle(
    extractBetween(originalDesc, 'Generated Title:', [
      'Generated Social:',
      'Original Title:',
      '---',
      '✍️ Redaktionelles Feedback',
    ])
  );
}

function getGeneratedSocialFromDesc(originalDesc) {
  return extractBetween(originalDesc, 'Generated Social:', [
    'Original Title:',
    '---',
    '✍️ Redaktionelles Feedback',
  ]);
}

function getOriginalTitleFromDesc(originalDesc) {
  return cleanCardTitle(
    extractBetween(originalDesc, 'Original Title:', [
      '---',
      '✍️ Redaktionelles Feedback',
    ])
  );
}

function getPriorityFromDesc(originalDesc) {
  return extractBetween(originalDesc, '⚡ Priorität:', [
    '---',
    '🤖 KI-/System-Output',
  ]);
}

function buildCompactOriginalBlock({
  sourceName,
  sourceUrl,
  originalDesc,
  generatedTitle,
  generatedSocial,
  originalTitle,
  priority,
}) {
  const finalSourceUrl =
    stripSmartCardMarkdown(sourceUrl) ||
    getOriginalLinkFromDesc(originalDesc);

  const finalPriority =
    clean(priority) ||
    getPriorityFromDesc(originalDesc);

  const finalGeneratedTitle =
    cleanCardTitle(generatedTitle) ||
    getGeneratedTitleFromDesc(originalDesc);

  const finalGeneratedSocial =
    clean(generatedSocial) ||
    getGeneratedSocialFromDesc(originalDesc) ||
    getOriginalSocialFromDesc(originalDesc);

  const finalOriginalTitle =
    cleanCardTitle(originalTitle) ||
    getOriginalTitleFromDesc(originalDesc);

  return buildText([
    '📌 Original / Quelle',
    '',
    sourceName ? `Quelle: ${sourceName}` : '',
    finalSourceUrl ? `Link: ${finalSourceUrl}` : '',
    finalPriority ? `Priorität: ${finalPriority}` : '',
    '',
    finalGeneratedTitle ? 'Generated Title:' : '',
    finalGeneratedTitle,
    '',
    finalGeneratedSocial ? 'Generated Social:' : '',
    finalGeneratedSocial,
    '',
    finalOriginalTitle ? 'Original Title:' : '',
    finalOriginalTitle,
  ]);
}

function getIdentity(obj) {
  const trelloCardId = pickFirstFromObjects([obj], [
    'trello_update_card_id',
    'trello_update_card_id_backup',
    'wp_trello_card_id',
    'trello_card_id',
    'card_id',
    'idTrello',
    'trello.id',
    'card.id',
    'wp_post_raw_response.wp_trello_card_id',
    'wp_post_raw_response.trello_update_card_id_backup',
  ]);

  const sourceUrl = pickFirstFromObjects([obj], [
    'wp_source_url',
    'source_url',
    'original_url',
    'url',
    'link',
    'article_url',
    'context_source_url',
    'external_context_source_url',
    'wp_post_raw_response.wp_source_url',
    'wp_post_raw_response.original_url',
  ]);

  return {
    trelloCardId: clean(trelloCardId),
    sourceUrl: normalizeUrl(sourceUrl),
  };
}

function contextItemMatchesBase(contextItem, baseIdentity) {
  const contextIdentity = getIdentity(contextItem);

  const baseTrello = clean(baseIdentity.trelloCardId);
  const contextTrello = clean(contextIdentity.trelloCardId);

  if (
    baseTrello &&
    contextTrello &&
    isLikelyTrelloCardId(baseTrello) &&
    isLikelyTrelloCardId(contextTrello) &&
    baseTrello === contextTrello
  ) {
    return true;
  }

  const baseUrl = normalizeUrl(baseIdentity.sourceUrl);
  const contextUrl = normalizeUrl(contextIdentity.sourceUrl);

  if (baseUrl && contextUrl && baseUrl === contextUrl) return true;

  return false;
}

function getMatchedContextItems(nodeNames, baseIdentity) {
  const matched = [];

  for (const nodeName of nodeNames) {
    const items = getAllNodeItems(nodeName);

    for (const item of items) {
      if (contextItemMatchesBase(item, baseIdentity)) {
        matched.push(item);
      }
    }
  }

  return matched;
}

// Nicht-externe Pfade bleiben großzügig wie bisher.
const MAX_TRELLO_DESC_LENGTH_INTERNAL = 12000;

// Externer Google-Pfad muss für den normalen Trello-Node deutlich kleiner bleiben.
// Sonst CloudFront 414.
const MAX_TRELLO_DESC_LENGTH_EXTERNAL_SAFE = 3900;

const currentItems = $input.all();

const merge5Items = getAllNodeItems('Merge5');
const restoreItems = getAllNodeItems('Restore Original Data After WP');

const contextNodeNames = [
  'Prepare Context Review Links',
  'Normalize Editorial Context Facts',
  'Build SCHALKETOTAL Context Block',
  'Prepare External Context Review Links',
  'Normalize External Editorial Context Facts',
  'Normalize External Context Results',
  'Prepare Unified Context For Article',
];

const output = [];

for (let i = 0; i < currentItems.length; i++) {
  const current = currentItems[i].json || {};
  const restore = restoreItems[i] || {};
  const merge5 = merge5Items[i] || {};

  const baseSources = [current, restore, merge5];

  const rawTrelloCardId = pickFirstFromObjects(baseSources, [
    'trello_update_card_id',
    'trello_update_card_id_backup',
    'wp_trello_card_id',
    'trello_card_id',
    'card_id',
    'idTrello',
    'trello.id',
    'card.id',
    'wp_post_raw_response.wp_trello_card_id',
    'wp_post_raw_response.trello_update_card_id_backup',
  ]);

  const trelloCardId = isLikelyTrelloCardId(rawTrelloCardId)
    ? rawTrelloCardId
    : '';

  const wpPostId = pickFirstFromObjects(baseSources, [
    'wp_post_id',
    'wp_vgwort_post_id',
    'post_id',
    'wp_post_raw_response.id',
    'id',
  ]);

  const wpPostLink = pickFirstFromObjects(baseSources, [
    'wp_post_link',
    'wp_post_raw_response.link',
    'wp_post_raw_response.guid.raw',
    'wp_post_raw_response.guid.rendered',
    'link',
    'guid.raw',
    'guid.rendered',
  ]);

  const trelloCardNameRaw = pickFirstFromObjects(baseSources, ['trello_card_name']);
  const trelloCardName = cleanCardTitle(trelloCardNameRaw);

  const title = trelloCardName || pickBestTitle(baseSources, [
    'wp_post_title',
    'wp_create_title',
    'wp_post_raw_response.wp_create_title',
    'wp_post_raw_response.wp_title',
    'wp_post_raw_response.title.raw',
    'wp_post_raw_response.title.rendered',
    'title.raw',
    'title.rendered',
    'generated_title',
    'wp_title',
    'original_title',
    'final_title',
  ]);

  const originalDescRaw = pickFirstFromObjects(baseSources, [
    'wp_post_raw_response.original_text',
    'original_text',
    'wp_post_raw_response.trello_update_desc_backup',
    'trello_update_desc_backup',
    'trello_original_desc',
    'original_trello_desc',
    'desc',
    'description',
  ]);

  const originalDesc = clean(originalDescRaw);

  const sourceUrlRaw = pickFirstFromObjects(baseSources, [
    'wp_source_url',
    'source_url',
    'original_url',
    'article_url',
    'url',
    'wp_post_raw_response.wp_source_url',
    'wp_post_raw_response.original_url',
  ]);

  const sourceName = pickFirstFromObjects(baseSources, [
    'wp_source_name',
    'source_name',
    'original_source_name',
    'wp_post_raw_response.wp_source_name',
    'wp_post_raw_response.original_source_name',
  ]);

  const sourceUrl = sourceUrlRaw || getOriginalLinkFromDesc(originalDesc);

  const generatedTitle = pickFirstFromObjects(baseSources, [
    'generated_title',
    'wp_create_title',
    'wp_title',
    'wp_post_raw_response.generated_title',
    'wp_post_raw_response.wp_create_title',
    'wp_post_raw_response.wp_title',
  ]);

  const generatedSocial = pickFirstFromObjects(baseSources, [
    'generated_social',
    'wp_social',
    'wp_post_raw_response.generated_social',
    'wp_post_raw_response.wp_social',
  ]);

  const originalTitle = pickFirstFromObjects(baseSources, [
    'original_title',
    'wp_post_raw_response.original_title',
  ]);

  const priority = pickFirstFromObjects(baseSources, [
    'priority',
    'wp_priority',
    'original_priority',
    'wp_post_raw_response.wp_priority',
    'wp_post_raw_response.original_priority',
  ]);

  const baseIdentity = {
    trelloCardId,
    sourceUrl: normalizeUrl(sourceUrlRaw),
  };

  const matchedContextItems = getMatchedContextItems(contextNodeNames, baseIdentity);
  const contextSources = matchedContextItems;

  const combinedContextMode = pickFirstFromObjects(contextSources, [
    'combined_context_mode',
  ]);

  const contextReviewLinksRaw = pickFirstFromObjects(contextSources, [
    'context_review_links',
    'external_context_review_links',
  ]);

  const contextQuality = pickFirstFromObjects(contextSources, [
    'context_quality',
    'external_context_quality',
  ]);

  const contextReady = pickFirstFromObjects(contextSources, [
    'context_ready_for_article_generation',
    'context_minimum_article_viability',
    'external_context_ready',
    'external_context_minimum_article_viability',
  ]);

  const contextReason = pickFirstFromObjects(contextSources, [
    'context_reason',
    'external_context_reason',
  ]);

  const internalContextCount = pickFirstFromObjects(contextSources, [
    'context_sources_internal_count',
    'schalketotal_context_article_count',
    'schalketotal_context_results_count',
  ]);

  const externalContextCount = pickFirstFromObjects(contextSources, [
    'context_sources_external_count',
    'external_context_results_count',
  ]);

  const contextCurrentStatusTitle = pickFirstFromObjects(contextSources, [
    'context_current_status_title',
    'external_context_current_status_title',
    'schalketotal_latest_context_article.title',
  ]);

  const contextCurrentStatusSource = pickFirstFromObjects(contextSources, [
    'context_current_status_source',
    'external_context_current_status_source',
    'schalketotal_latest_context_article.link',
  ]);

  const contextMinimumReason = pickFirstFromObjects(contextSources, [
    'context_minimum_article_viability_reason',
    'external_context_minimum_article_viability_reason',
  ]);

  const externalSearchQuery = pickFirstFromObjects(contextSources, [
    'external_context_search_query_used',
    'external_context_search_query',
  ]);

  const isExternalContext =
    Number(externalContextCount || 0) > 0 ||
    clean(combinedContextMode).includes('external') ||
    Boolean(externalSearchQuery) ||
    clean(contextReviewLinksRaw).includes('🌐 Verwendeter externer Kontext');

  const maxTrelloDescLength = isExternalContext
    ? MAX_TRELLO_DESC_LENGTH_EXTERNAL_SAFE
    : MAX_TRELLO_DESC_LENGTH_INTERNAL;

  const hasContextBlock =
    matchedContextItems.length > 0 &&
    Boolean(
      contextReviewLinksRaw ||
      contextQuality ||
      contextReady ||
      contextReason ||
      internalContextCount ||
      externalContextCount ||
      contextCurrentStatusTitle ||
      contextCurrentStatusSource ||
      combinedContextMode ||
      externalSearchQuery ||
      contextMinimumReason
    );

  const wpDraftBlock = buildText([
    '✅ WP Draft erstellt',
    '',
    'WP Post ID:',
    wpPostId,
    '',
    'WP Draft Link:',
    wpPostLink,
    '',
    'Erstellt am:',
    formatDateGerman(),
  ]);

  const compactOriginalBlock = buildCompactOriginalBlock({
    sourceName,
    sourceUrl,
    originalDesc,
    generatedTitle,
    generatedSocial,
    originalTitle,
    priority,
  });

  let descWasLimited = false;
  let originalDescWasLimited = false;
  let contextWasLimited = false;
  let descLimitMode = 'not_limited';
  let originalDescForOutput = originalDesc;
  let contextReviewLinksForOutput = contextReviewLinksRaw;

  let desc = '';

  if (isExternalContext) {
    // Google/externer Pfad:
    // Keine komplette alte Trello-Beschreibung.
    // Kontext bleibt direkt unter WP-Draft-Link.
    // Originalinfos bleiben kompakt unten.
    const contextHeader = hasContextBlock
      ? buildText([
          separator(),
          '🧠 Kontextprüfung',
          contextReason ? `Grund: ${contextReason}` : '',
          combinedContextMode ? `Modus: ${contextModeLabel(combinedContextMode)}` : '',
          externalSearchQuery ? `Externe Suchanfrage: ${externalSearchQuery}` : '',
          contextQuality ? `Qualität: ${contextQuality}` : '',
          contextReady ? `Für Artikelgenerierung tragfähig: ${cleanBooleanLabel(contextReady)}` : '',
          internalContextCount ? `Interne Kontextquellen: ${internalContextCount}` : '',
          externalContextCount ? `Externe Kontextquellen: ${externalContextCount}` : '',
          contextCurrentStatusTitle ? `Wichtigste Kontextquelle: ${contextCurrentStatusTitle}` : '',
          contextCurrentStatusSource ? `Kontext-Link: ${contextCurrentStatusSource}` : '',
          contextMinimumReason ? `Einschätzung: ${contextMinimumReason}` : '',
        ])
      : '';

    const bottomBlock = buildText([
      separator(),
      compactOriginalBlock,
    ]);

    const fixedExternalWithoutContext = buildText([
      wpDraftBlock,
      contextHeader,
      contextReviewLinksRaw ? separator() : '',
      bottomBlock,
    ]);

    const reservedForContext =
      maxTrelloDescLength -
      fixedExternalWithoutContext.length -
      80;

    if (contextReviewLinksRaw && reservedForContext < contextReviewLinksRaw.length) {
      contextWasLimited = true;
      descWasLimited = true;
      descLimitMode = 'external_context_limited_original_compact_kept';

      contextReviewLinksForOutput = limitExternalContext(
        contextReviewLinksRaw,
        Math.max(600, reservedForContext)
      );
    } else {
      descLimitMode = 'external_context_full_original_compact_kept';
    }

    originalDescForOutput = '';
    originalDescWasLimited = Boolean(originalDesc);

    desc = buildText([
      wpDraftBlock,
      contextHeader,
      contextReviewLinksForOutput ? separator() : '',
      contextReviewLinksForOutput,
      separator(),
      compactOriginalBlock,
    ]);

    if (desc.length > maxTrelloDescLength) {
      descWasLimited = true;
      descLimitMode = 'external_hard_limit_after_compact_blocks';

      desc = limitText(
        desc,
        maxTrelloDescLength,
        '\n\n[Beschreibung gekürzt, damit der normale Trello-Node nicht mit CloudFront 414 abbricht.]'
      );
    }
  } else {
    // Nicht-externer Pfad:
    // Bisherige Logik beibehalten.
    const fixedParts = [
      wpDraftBlock,
    ];

    if (hasContextBlock) {
      fixedParts.push(
        separator(),
        '🧠 Kontextprüfung',
        contextReason ? `Grund: ${contextReason}` : '',
        combinedContextMode ? `Modus: ${contextModeLabel(combinedContextMode)}` : '',
        externalSearchQuery ? `Externe Suchanfrage: ${externalSearchQuery}` : '',
        contextQuality ? `Qualität: ${contextQuality}` : '',
        contextReady ? `Für Artikelgenerierung tragfähig: ${cleanBooleanLabel(contextReady)}` : '',
        internalContextCount ? `Interne Kontextquellen: ${internalContextCount}` : '',
        externalContextCount ? `Externe Kontextquellen: ${externalContextCount}` : '',
        contextCurrentStatusTitle ? `Wichtigste Kontextquelle: ${contextCurrentStatusTitle}` : '',
        contextCurrentStatusSource ? `Kontext-Link: ${contextCurrentStatusSource}` : '',
        contextMinimumReason ? `Einschätzung: ${contextMinimumReason}` : ''
      );

      if (contextReviewLinksRaw) {
        fixedParts.push(
          separator(),
          contextReviewLinksRaw
        );
      }
    }

    const fixedWithoutOriginal = buildText(fixedParts);

    const fullLength = buildText([
      fixedWithoutOriginal,
      originalDesc ? separator() : '',
      originalDesc,
    ]).length;

    if (fullLength > maxTrelloDescLength) {
      descWasLimited = true;
      originalDescWasLimited = true;
      descLimitMode = 'internal_context_full_kept_original_desc_limited';

      const reservedForOriginal =
        maxTrelloDescLength -
        fixedWithoutOriginal.length -
        separator().length -
        120;

      originalDescForOutput = limitOriginalDesc(
        originalDesc,
        Math.max(0, reservedForOriginal)
      );
    }

    desc = buildText([
      fixedWithoutOriginal,
      originalDescForOutput ? separator() : '',
      originalDescForOutput,
    ]);

    if (desc.length > maxTrelloDescLength) {
      descWasLimited = true;
      descLimitMode = 'internal_context_too_long_hard_limit';

      desc =
        desc.slice(0, maxTrelloDescLength).trim() +
        '\n\n' +
        separator() +
        '\n\n⚠️ Beschreibung am Ende gekürzt, weil WP-Daten + SCHALKETOTAL-Kontext das Trello-Sicherheitslimit überschreiten.';
    }
  }

  output.push({
    json: {
      trello_prepare_status: trelloCardId ? 'ready' : 'error_invalid_or_missing_trello_card_id',

      trello_update_card_id: trelloCardId,

      trello_updated_name: title
        ? `✅ WP Draft erstellt – ${title}`
        : '✅ WP Draft erstellt',

      trello_updated_desc: desc,

      wp_post_id: wpPostId,
      wp_post_link: wpPostLink,

      trello_debug_sources: {
        item_index: i,

        base_trello_card_id: baseIdentity.trelloCardId,
