// Prepare Context Search Input
// Bereitet Suchdaten für Zusatzkontext vor.
// Ziel:
// - Nicht 1:1 den neuen Artikeltitel suchen
// - Stattdessen thematische Suchqueries bauen
// - SCHALKETOTAL intern eher breit suchen
// - Web extern etwas konkreter suchen

function clean(value) {
  return String(value ?? '').trim();
}

function normalizeSpaces(value) {
  return clean(value).replace(/\s+/g, ' ').trim();
}

function toNumber(value) {
  const num = Number(value);
  return Number.isFinite(num) ? num : 0;
}

function stripAccents(value) {
  return clean(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function unique(values) {
  const out = [];
  const seen = new Set();

  for (const value of values) {
    const v = clean(value);
    if (!v) continue;

    const key = stripAccents(v).toLowerCase();
    if (seen.has(key)) continue;

    seen.add(key);
    out.push(v);
  }

  return out;
}

function detectContextReason(item) {
  const sourceType = clean(item.original_source_type || item.source_type || item.wp_source_type).toLowerCase();
  const sourceName = clean(item.original_source_name || item.wp_source_name || item.source_name).toLowerCase();
  const url = clean(item.original_url || item.wp_source_url || item.url).toLowerCase();

  const fullText =
    clean(item.full_text) ||
    clean(item.cleaned_full_text) ||
    clean(item.article_text) ||
    clean(item.original_text);

  const fullTextLength =
    toNumber(item.full_text_length) ||
    fullText.length;

  const fullFetchStatus = clean(item.full_fetch_status).toLowerCase();
  const contentStatus = clean(item.content_status).toLowerCase();

  const isXSource =
    sourceType.includes('x') ||
    sourceType.includes('twitter') ||
    sourceName === 'x' ||
    sourceName.includes('twitter') ||
    url.includes('x.com/') ||
    url.includes('twitter.com/');

  if (isXSource) return 'x_source';
  if (!fullText) return 'missing_full_text';
  if (fullFetchStatus && !['ok', 'success', 'full_text_ok'].includes(fullFetchStatus)) return 'full_fetch_failed';
  if (contentStatus && !['ok', 'success', 'full_text_ok'].includes(contentStatus)) return 'content_status_not_ok';
  if (fullTextLength < 1200) return 'full_text_too_short';

  return 'manual_or_if_false';
}

function extractKnownEntities(text) {
  const source = clean(text);

  const knownPeople = [
    'Loris Karius',
    'Karius',
    'Tomáš Kalas',
    'Kalas',
    'Nikola Katić',
    'Katić',
    'Hasan Kurucay',
    'Kurucay',
    'Mertcan Ayhan',
    'Ayhan',
    'Timo Becker',
    'Becker',
    'Ron Schallenberg',
    'Schallenberg',
    'Janik Bachmann',
    'Bachmann',
    'Dejan Ljubičić',
    'Ljubičić',
    'Adil Aouchiche',
    'Aouchiche',
    'Finn Porath',
    'Porath',
    'Kenan Karaman',
    'Karaman',
    'Moussa Sylla',
    'Sylla',
    'Edin Džeko',
    'Džeko',
    'Bryan Lasme',
    'Lasme',
    'Miron Muslić',
    'Muslić',
    'Matthias Tillmann',
    'Frank Baumann',
    'Baumann',
    'Axel Hefer',
    'Hefer',
  ];

  const entities = [];

  const normalizedSource = stripAccents(source).toLowerCase();

  for (const person of knownPeople) {
    const normalizedPerson = stripAccents(person).toLowerCase();

    if (normalizedSource.includes(normalizedPerson)) {
      // Für die Suche bevorzugen wir bei bekannten Spielern meistens den Nachnamen.
      const parts = clean(person).split(/\s+/).filter(Boolean);
      entities.push(parts[parts.length - 1] || person);
    }
  }

  return unique(entities);
}

function extractTopicTerms(text) {
  const source = stripAccents(text).toLowerCase();

  const topicMap = [
    { terms: ['karriereende', 'retiring', 'retirement', 'beendet karriere'], output: 'Karriereende' },
    { terms: ['vertrag', 'verlaengerung', 'verlängerung', 'contract', 'nicht verlaengern', 'nicht verlängern'], output: 'Vertrag' },
    { terms: ['zukunft', 'future'], output: 'Zukunft' },
    { terms: ['verletzung', 'verletzungen', 'injury', 'injuries', 'struggl'], output: 'Verletzungen' },
    { terms: ['abschied', 'abgang', 'wechsel'], output: 'Abschied' },
    { terms: ['dfb pokal', 'dfb-pokal', 'pokalfinale', 'finale'], output: 'DFB-Pokal' },
    { terms: ['stuttgart', 'vfb'], output: 'Stuttgart' },
    { terms: ['schalke', 'schalke', 's04'], output: 'S04' },
    { terms: ['nationalmannschaft', 'wm'], output: 'Nationalmannschaft' },
    { terms: ['transfer'], output: 'Transfer' },
  ];

  const found = [];

  for (const entry of topicMap) {
    if (entry.terms.some(term => source.includes(stripAccents(term).toLowerCase()))) {
      found.push(entry.output);
    }
  }

  return unique(found);
}

function buildContextQueries(item) {
  const title =
    clean(item.final_title) ||
    clean(item.generated_title) ||
    clean(item.wp_title) ||
    clean(item.original_title) ||
    clean(item.title) ||
    clean(item.trello_card_name);

  const originalTitle = clean(item.original_title);
  const generatedSocial = clean(item.generated_social || item.wp_social);
  const originalText = clean(item.original_text);
  const fullText = clean(item.full_text);

  const allText = normalizeSpaces([
    title,
    originalTitle,
    generatedSocial,
    originalText,
    fullText,
  ].filter(Boolean).join(' '));

  let entities = extractKnownEntities(allText);
  let topics = extractTopicTerms(allText);

  // Fallback: wenn kein bekannter Name erkannt wird, einfache Großwort-/Titel-Heuristik
  if (!entities.length) {
    const fallbackWords = allText
      .split(/\s+/)
      .map(word => word.replace(/[^\p{L}\p{N}ÄÖÜäöüß-]/gu, ''))
      .filter(Boolean)
      .filter(word => /^[A-ZÄÖÜ][a-zäöüß-]{2,}/.test(word))
      .filter(word => ![
        'Nach',
        'Der',
        'Die',
        'Das',
        'Ein',
        'Eine',
        'S04',
        'Stuttgart',
        'Trello',
        'Generated',
        'Original',
        'Final',
        'Social',
        'Kommentar',
      ].includes(word));

    entities = unique(fallbackWords).slice(0, 2);
  }

  // S04 als Kontext fast immer sinnvoll ergänzen
  if (!topics.includes('S04')) {
    topics.unshift('S04');
  }

  // Interne SCHALKETOTAL-Suche: breit und kurz
  // Ziel: ältere Kontextartikel finden, nicht exakt den neuen Titel.
  const schalketotalQuery = unique([
    ...entities.slice(0, 2),
    'S04',
    ...topics.filter(term => !['DFB-Pokal', 'Stuttgart'].includes(term)).slice(0, 3),
  ]).join(' ');

  // Externe Websuche: etwas konkreter, aktueller
  const webQuery = unique([
    ...entities.slice(0, 2),
    'FC S04',
    ...topics.slice(0, 5),
  ]).join(' ');

  return {
    title,
    allText,
    entities,
    topics,
    schalketotalQuery: normalizeSpaces(schalketotalQuery),
    webQuery: normalizeSpaces(webQuery),
  };
}

const output = [];

for (const item of $input.all()) {
  const j = item.json || {};

  const reason = detectContextReason(j);
  const queries = buildContextQueries(j);

  output.push({
    json: {
      ...j,

      needs_context: true,
      context_reason: reason,

      context_search_title: queries.title,
      context_entities: queries.entities,
      context_topics: queries.topics,

      context_source_url:
        clean(j.original_url) ||
        clean(j.wp_source_url) ||
        clean(j.url),

      context_source_name:
        clean(j.original_source_name) ||
        clean(j.wp_source_name) ||
        clean(j.source_name),

      // Wichtig:
      // Interne Suche breit.
      // Externe Suche etwas konkreter.
      context_schalketotal_query: queries.schalketotalQuery,
      context_web_query: queries.webQuery,

      context_status: 'prepared',

      context_debug: {
        reason,
        entities: queries.entities,
        topics: queries.topics,
        schalketotal_query: queries.schalketotalQuery,
        web_query: queries.webQuery,
      },
    },
  });
}

return output;

// Prepare SCHALKETOTAL Main Entity Search
// Ziel:
// Saubere interne SCHALKETOTAL-Kontextsuche für alle Themenarten.
//
// Grundlogik:
// 1. Personen erkannt:
//    - interne Primärsuche immer Nachname only
//    - zusätzlich Query-Varianten speichern: Nachname + voller Name
//    - Beispiel: Nathaniel Brown -> Brown / Nathaniel Brown
//
// 2. Themen ohne Person:
//    - kurze, konkrete Query aus 2 bis maximal 3 starken Keywords
//    - Beispiel: Sommerfahrplan Testspiele Asien-Tour
//
// 3. X-/Trello-/Apify-Fälle:
//    - apify_full_text / full_text / article_text werden jetzt aktiv für Entity-Erkennung genutzt
//    - X-UI-Müll wie "New to X", "Sign up", "Trending now" wird entfernt
//    - konkrete Spielernamen gewinnen vor generischen Begriffen wie Paris, PSG, Transfer, Shootingstar
//
// 4. Niemals:
//    - nur S04 / S04s / FC S04 suchen
//    - lange Mischqueries bauen
//    - Füllwörter wie Erst, Fokus, mal, July, Danach, Priority nutzen
//
// Wichtige Outputs:
// - context_schalketotal_query_used: aktuell genutzte Primärquery
// - context_schalketotal_query_variants: optionale Suchvarianten für spätere Mehrfachsuche
// - context_search_keywords: Keywords für späteres Scoring/Filtering
// - context_is_person_context: true/false

function clean(value) {
  return String(value ?? '').trim();
}

function normalizeSpaces(value) {
  return clean(value).replace(/\s+/g, ' ').trim();
}

function stripAccents(value) {
  return clean(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalizeKey(value) {
  return stripAccents(value)
    .toLowerCase()
    .replace(/[„“"‚‘’'`´]/g, '')
    .replace(/&amp;/g, '&')
    .replace(/[^\p{L}\p{N}\s&.-]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeLoose(value) {
  return normalizeKey(value)
    .replace(/[.-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function unique(values) {
  const out = [];
  const seen = new Set();

  for (const value of values) {
    const v = normalizeSpaces(value);
    if (!v) continue;

    const key = normalizeLoose(v);
    if (!key || seen.has(key)) continue;

    seen.add(key);
    out.push(v);
  }

  return out;
}

function getLastName(value) {
  const words = normalizeSpaces(value)
    .split(/\s+/)
    .filter(Boolean);

  if (!words.length) return '';

  return words[words.length - 1];
}

function countOccurrencesLoose(text, needle) {
  const haystack = normalizeLoose(text);
  const n = normalizeLoose(needle);

  if (!haystack || !n) return 0;

  const escaped = n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const matches = haystack.match(new RegExp(`\\b${escaped}\\b`, 'g'));

  return matches ? matches.length : 0;
}

function cleanSearchSourceText(value, field = '') {
  let text = normalizeSpaces(value);

  if (!text) return '';

  // Trello Smartcard-Markdown reduzieren
  text = text.replace(
    /\[([^\]]+)\]\((https?:\/\/[^)\s]+)(?:\s+"[^"]*")?\)/gi,
    '$1'
  );

  // HTML grob entfernen, falls Content aus WP oder Scraper kommt
  text = text
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ');

  // X-/Twitter-UI-Müll abschneiden
  const lower = text.toLowerCase();
  const noiseMarkers = [
    'post conversation',
    'new to x?',
    'sign up now',
    'sign up with google',
    'create account',
    'trending now',
    'what’s happening',
    "what's happening",
    'opens in new tab',
  ];

  let cutAt = -1;

  for (const marker of noiseMarkers) {
    const idx = lower.indexOf(marker);
    if (idx >= 80 && (cutAt === -1 || idx < cutAt)) {
      cutAt = idx;
    }
  }

  if (cutAt > -1) {
    text = text.slice(0, cutAt);
  }

  // URLs entfernen, aber restlichen Text behalten
  text = text.replace(/https?:\/\/\S+/gi, ' ');

  // Typische X-Präfixe entschärfen
  text = text
    .replace(/\bTransfer News Live on X:\s*/gi, ' ')
    .replace(/\bon X:\s*/gi, ' ')
    .replace(/\bTwitter:\s*/gi, ' ');

  return normalizeSpaces(text);
}

