function isGenericTerm(value) {
  const key = normalizeLoose(value);

  if (!key) return true;
  if (key.length < 3) return true;
  if (/^\d+$/.test(key)) return true;
  if (GENERIC_TERMS.has(key)) return true;
  if (STOPWORDS.has(key)) return true;

  if (key.startsWith('schalke ')) return true;
  if (key.startsWith('schalke-')) return true;
  if (key.includes('system output')) return true;

  return false;
}

function isUsefulKeyword(value) {
  const key = normalizeLoose(value);

  if (!key) return false;
  if (key.length < 3) return false;
  if (/^\d+$/.test(key)) return false;
  if (isGenericTerm(value)) return false;

  return true;
}

