function looksLikeNamePart(value) {
  const v = clean(value);

  if (!v) return false;
  if (NON_PERSON_NAME_PARTS.has(v)) return false;
  if (isGenericTerm(v)) return false;

  return /^[A-ZÄÖÜ][A-Za-zÄÖÜäöüß-]{2,}$/.test(v);
}

function isLikelyPersonFullName(value) {
  const fullName = normalizeSpaces(value);
  const key = normalizeLoose(fullName);

  if (!fullName) return false;
  if (NON_PERSON_PHRASES.has(key)) return false;
  if (GENERIC_TERMS.has(key)) return false;

  const parts = fullName.split(/\s+/).filter(Boolean);

  if (parts.length < 2 || parts.length > 3) return false;

  return parts.every(looksLikeNamePart);
}

function scorePersonCandidate(fullName, source, allText, j) {
  const name = normalizeSpaces(fullName);
  const text = source.text || '';
  const field = source.field || '';

  let score = source.weight || 0;

  const titleLikeFields = new Set([
    'context_search_title',
    'generated_title',
    'trello_card_name',
    'title',
    'original_title',
  ]);

  const contentLikeFields = new Set([
    'apify_full_text',
    'full_text',
    'article_text',
    'raw_text',
    'description',
    'search_text',
    'cleaned_primary_text',
    'cleaned_editorial_text',
  ]);

  if (titleLikeFields.has(field)) score += 35;
  if (contentLikeFields.has(field)) score += 18;

  const firstIndex = normalizeLoose(text).indexOf(normalizeLoose(name));
  if (firstIndex >= 0) {
    score += Math.max(0, 35 - Math.floor(firstIndex / 60));
  }

  const occurrences = countOccurrencesLoose(allText, name);
  score += Math.min(occurrences * 10, 40);

  const textLower = normalizeLoose(text);
  const nameKey = normalizeLoose(name);
  const idx = textLower.indexOf(nameKey);

  if (idx >= 0) {
    const windowStart = Math.max(0, idx - 140);
    const windowEnd = Math.min(textLower.length, idx + nameKey.length + 180);
    const near = textLower.slice(windowStart, windowEnd);

    if (
      /\b(striker|forward|winger|defender|midfielder|goalkeeper|spieler|stuermer|stürmer|angreifer|verteidiger|torhueter|torhüter|mittelfeldspieler|offensivspieler|talent|youngster|teenager)\b/i.test(near)
    ) {
      score += 30;
    }

    if (
      /\b(transfer|wechsel|move|monitoring|interest|interesse|targeting|target|wunschliste|beobachtet|verpflichtung|ablöse|fee)\b/i.test(near)
    ) {
      score += 30;
    }

    if (
      /\b(schalke|schalke|s04|psg|paris|bournemouth|leipzig|juventus|barcelona|liverpool|manchester)\b/i.test(near)
    ) {
      score += 12;
    }
  }

  const sourceUrl = normalizeLoose(j.url || j.original_url || j.wp_source_url || '');
  if (
    (field === 'apify_full_text' || field === 'full_text' || field === 'article_text') &&
    (sourceUrl.includes('x com') || sourceUrl.includes('twitter com'))
  ) {
    score += 25;
  }

  return score;
}

function detectPersonFromEntities(j, allText) {
  const entities = Array.isArray(j.context_entities)
    ? j.context_entities.map(clean).filter(Boolean)
    : [];

  // Entity bereits als voller Name: "Nathaniel Brown"
  for (const entity of entities) {
    if (isLikelyPersonFullName(entity)) {
      return {
        fullName: normalizeSpaces(entity),
        lastName: getLastName(entity),
        source: 'context_entities_full_name',
        score: 120,
      };
    }
  }

  // Entities getrennt: ["Nathaniel", "Brown"]
  for (let i = 0; i < entities.length - 1; i++) {
    const first = entities[i];
    const second = entities[i + 1];
    const fullName = `${first} ${second}`;

    if (!isLikelyPersonFullName(fullName)) continue;

    const fullNameKey = normalizeLoose(fullName);
    const textKey = normalizeLoose(allText);

    if (textKey.includes(fullNameKey)) {
      return {
        fullName,
        lastName: second,
        source: 'context_entities_adjacent_name',
        score: 115,
      };
    }
  }

  return null;
}

function detectPersonFromText(j) {
  const sources = getTextSources(j);
  const allText = getAllSearchText(j);
  const candidates = new Map();

  for (const source of sources) {
    const text = source.text;

    const matches = text.match(
      /\b[A-ZÄÖÜ][A-Za-zÄÖÜäöüß-]{2,}\s+[A-ZÄÖÜ][A-Za-zÄÖÜäöüß-]{2,}(?:\s+[A-ZÄÖÜ][A-Za-zÄÖÜäöüß-]{2,})?\b/gu
    ) || [];

    for (const match of matches) {
      const fullName = normalizeSpaces(match);

      if (!isLikelyPersonFullName(fullName)) continue;

      const key = normalizeLoose(fullName);
      const score = scorePersonCandidate(fullName, source, allText, j);

      if (!candidates.has(key)) {
        candidates.set(key, {
          fullName,
          lastName: getLastName(fullName),
          source: `text_full_name:${source.field}`,
          score,
          sources: [source.field],
        });
      } else {
        const existing = candidates.get(key);
        existing.score += Math.round(score * 0.5);
        if (!existing.sources.includes(source.field)) {
          existing.sources.push(source.field);
        }
      }
    }
  }

  const sorted = [...candidates.values()]
    .filter(candidate => candidate.lastName && !isGenericTerm(candidate.lastName))
    .sort((a, b) => b.score - a.score);

  return sorted[0] || null;
}

function detectPerson(j) {
  const allText = getAllSearchText(j);

  return (
    detectPersonFromEntities(j, allText) ||
    detectPersonFromText(j) ||
    null
  );
}

function addCandidate(candidates, value, score, source, topic = '', kind = 'keyword') {
  const display = normalizeSpaces(value);
  if (!display) return;
  if (!isUsefulKeyword(display)) return;

  const key = normalizeLoose(display);
  if (!key) return;

  const existing = candidates.get(key);

  if (existing) {
    existing.score += score;
    existing.sources.push(source);

    if (topic && !existing.topics.includes(topic)) {
      existing.topics.push(topic);
    }

    if (kind === 'phrase' && existing.kind !== 'phrase') {
      existing.kind = 'phrase';
    }

    if (kind === 'entity_lastname') {
      existing.kind = 'entity_lastname';
    }

    return;
  }

  candidates.set(key, {
    value: display,
    key,
    score,
    sources: [source],
    topics: topic ? [topic] : [],
    kind,
  });
}

function addEntityCandidate(candidates, value, score, source) {
  const entity = normalizeSpaces(value);
  if (!entity) return;
  if (isGenericTerm(entity)) return;

  if (isLikelyPersonFullName(entity)) {
    const lastName = getLastName(entity);

    addCandidate(candidates, entity, score, source, '', 'entity_full');

    if (lastName && !isGenericTerm(lastName)) {
      addCandidate(candidates, lastName, score + 35, source, '', 'entity_lastname');
    }

    return;
  }

  addCandidate(candidates, entity, score, source, '', 'entity');
}

function extractContextEntityCandidates(candidates, j) {
  if (!Array.isArray(j.context_entities)) return;

  const entities = j.context_entities.map(clean).filter(Boolean);

  for (const entity of entities) {
    addEntityCandidate(candidates, entity, 90, 'context_entities');
  }

  // Adjacent entities als möglicher voller Name zusätzlich speichern
  for (let i = 0; i < entities.length - 1; i++) {
    const fullName = `${entities[i]} ${entities[i + 1]}`;

    if (isLikelyPersonFullName(fullName)) {
      addEntityCandidate(candidates, fullName, 100, 'context_entities_adjacent');
    }
  }
}

function extractDetectedPersonCandidates(candidates, detectedPerson) {
  if (!detectedPerson || !detectedPerson.fullName || !detectedPerson.lastName) return;

  addCandidate(
    candidates,
    detectedPerson.fullName,
    180 + Math.round(detectedPerson.score || 0),
    detectedPerson.source || 'detected_person',
    '',
    'entity_full'
  );

  addCandidate(
    candidates,
    detectedPerson.lastName,
    220 + Math.round(detectedPerson.score || 0),
    detectedPerson.source || 'detected_person_lastname',
    '',
    'entity_lastname'
  );
}

function extractContextTopicCandidates(candidates, j) {
  if (!Array.isArray(j.context_topics)) return;

  for (const topic of j.context_topics) {
    const t = clean(topic);
    if (!t || isGenericTerm(t)) continue;

    addCandidate(candidates, t, 18, 'context_topics', '', 'topic');
  }
}

function extractPhraseCandidates(candidates, sources) {
  for (const source of sources) {
    const text = source.text;

    for (const phrase of PHRASE_PATTERNS) {
      const matched = phrase.patterns.some(pattern => pattern.test(text));

      if (matched) {
        addCandidate(
          candidates,
          phrase.canonical,
          phrase.score + source.weight,
          `phrase:${source.field}`,
          phrase.topic,
          'phrase'
        );
      }
    }
  }
}

function extractCapitalizedCandidates(candidates, sources) {
  for (const source of sources) {
    const text = source.text;

    const matches = text.match(
      /\b[A-ZÄÖÜ][\p{L}\p{N}äöüßÄÖÜ-]{2,}(?:\s+[A-ZÄÖÜ][\p{L}\p{N}äöüßÄÖÜ-]{2,}){0,2}\b/gu
    ) || [];

    for (const match of matches) {
      const phrase = normalizeSpaces(match);
      if (!phrase) continue;

      const phraseKey = normalizeLoose(phrase);
      if (NON_PERSON_PHRASES.has(phraseKey)) continue;

      const parts = phrase.split(/\s+/).filter(Boolean);

      const cleanedParts = parts.filter(part => {
        if (NON_PERSON_NAME_PARTS.has(part)) return false;
        if (isGenericTerm(part)) return false;
        return true;
      });

      if (!cleanedParts.length) continue;

      const cleanedPhrase = cleanedParts.join(' ');
      if (!isUsefulKeyword(cleanedPhrase)) continue;

      addEntityCandidate(
        candidates,
        cleanedPhrase,
        30 + source.weight,
        `capitalized:${source.field}`
      );
    }
  }
}

function extractWordCandidates(candidates, sources) {
  for (const source of sources) {
    // original_text enthält oft Trello-/Workflow-Müll.
    // Für Einzelwörter daher nicht nutzen.
    if (source.field === 'original_text') continue;

    const words = source.text.match(/[\p{L}\p{N}]+(?:-[\p{L}\p{N}]+)?/gu) || [];

    for (const word of words) {
      const display = normalizeSpaces(word);
      if (!isUsefulKeyword(display)) continue;

      addCandidate(
        candidates,
        display,
        8 + source.weight,
        `word:${source.field}`,
        '',
        'word'
      );
    }
  }
}

function detectDominantTopic(candidates, j) {
  const topicScores = {};

  for (const candidate of candidates.values()) {
    for (const topic of candidate.topics || []) {
      topicScores[topic] = (topicScores[topic] || 0) + candidate.score;
    }
  }

  const text = normalizeLoose(getAllSearchText(j));

  if (
    text.includes('gerucht') ||
    text.includes('gerüchte') ||
    text.includes('geruecht') ||
    text.includes('reported interest') ||
    text.includes('interesse') ||
    text.includes('wunschspieler') ||
    text.includes('transfer') ||
    text.includes('monitoring') ||
    text.includes('targeting') ||
    text.includes('weigh up a move') ||
    text.includes('weighing up a move') ||
    text.includes('significant fee')
  ) {
    topicScores.transfer = (topicScores.transfer || 0) + 120;
  }

  if (
    text.includes('statement') ||
    text.includes('aussage') ||
    text.includes('erklart') ||
    text.includes('erklärt') ||
    text.includes('erst mal fokus') ||
    text.includes('stellt klar')
  ) {
    topicScores.statement = (topicScores.statement || 0) + 90;
  }

  if (
    text.includes('wm') ||
    text.includes('world cup') ||
    text.includes('nationalmannschaft')
  ) {
    topicScores.national_team = (topicScores.national_team || 0) + 70;
  }

  if (
    text.includes('strafe') ||
    text.includes('geldstrafe') ||
    text.includes('sportgericht') ||
    text.includes('verspatung') ||
    text.includes('verspätung')
  ) {
    topicScores.dfb_penalty = (topicScores.dfb_penalty || 0) + 110;
  }

  const sortedTopics = Object.entries(topicScores)
    .sort((a, b) => b[1] - a[1]);

  if (!sortedTopics.length) return '';

  return sortedTopics[0][0];
}

function candidateSort(a, b) {
  if (b.score !== a.score) return b.score - a.score;

  const kindOrder = {
    entity_lastname: 1,
    entity_full: 2,
    entity: 3,
    phrase: 4,
    topic: 5,
    word: 6,
  };

  const aKind = kindOrder[a.kind] || 9;
  const bKind = kindOrder[b.kind] || 9;

  return aKind - bKind;
}

function pushUniqueTerm(list, value, maxTerms) {
  const v = normalizeSpaces(value);
  if (!v) return;
  if (!isUsefulKeyword(v)) return;

  const key = normalizeLoose(v);

  if (list.some(existing => normalizeLoose(existing) === key)) return;

  list.push(v);

  if (list.length > maxTerms) {
    list.length = maxTerms;
  }
}

function getCandidatesByTopic(candidates, topic) {
  return [...candidates.values()]
    .filter(candidate => Array.isArray(candidate.topics) && candidate.topics.includes(topic))
    .sort(candidateSort);
}

function getBestEntityCandidate(candidates) {
  return [...candidates.values()]
    .filter(candidate =>
      candidate.kind === 'entity_lastname' ||
      candidate.kind === 'entity_full' ||
      candidate.kind === 'entity'
    )
    .filter(candidate => !isGenericTerm(candidate.value))
    .sort(candidateSort)[0] || null;
}

function getBestPhraseCandidate(candidates) {
  return [...candidates.values()]
    .filter(candidate => candidate.kind === 'phrase')
    .filter(candidate => !isGenericTerm(candidate.value))
    .sort(candidateSort)[0] || null;
}

function buildScheduleQuery(candidates) {
  const preferredOrder = [
    'Sommerfahrplan',
    'Testspiele',
    'Asien-Tour',
    'Trainingsstart',
    'Saisonvorbereitung',
    'Trainingslager',
    'Aston Villa',
