    'Tegernsee',
  ];

  const queryTerms = [];

  for (const term of preferredOrder) {
    const key = normalizeLoose(term);
    const exists = [...candidates.values()].some(candidate => normalizeLoose(candidate.value) === key);

    if (exists) {
      pushUniqueTerm(queryTerms, term, 3);
    }

    if (queryTerms.length >= 3) break;
  }

  return queryTerms.join(' ');
}

function buildDfbPenaltyQuery(candidates) {
  const preferredOrder = [
    'DFB',
    'Strafe',
    'Verspätung',
  ];

  const queryTerms = [];

  for (const term of preferredOrder) {
    const key = normalizeLoose(term);
    const exists = [...candidates.values()].some(candidate => normalizeLoose(candidate.value) === key);

    if (exists) {
      pushUniqueTerm(queryTerms, term, 3);
    }
  }

  if (!queryTerms.length) {
    const topicCandidates = getCandidatesByTopic(candidates, 'dfb_penalty');

    for (const candidate of topicCandidates) {
      pushUniqueTerm(queryTerms, candidate.value, 3);
      if (queryTerms.length >= 3) break;
    }
  }

  return queryTerms.join(' ');
}

function buildTopicQuery(candidates, topic) {
  const queryTerms = [];
  const entity = getBestEntityCandidate(candidates);
  const topicCandidates = getCandidatesByTopic(candidates, topic);

  if (entity) {
    pushUniqueTerm(queryTerms, entity.value, 3);
  }

  for (const candidate of topicCandidates) {
    pushUniqueTerm(queryTerms, candidate.value, 3);
    if (queryTerms.length >= 3) break;
  }

  if (!queryTerms.length) {
    const phrase = getBestPhraseCandidate(candidates);
    if (phrase) {
      pushUniqueTerm(queryTerms, phrase.value, 3);
    }
  }

  return queryTerms.join(' ');
}

function buildGeneralQuery(candidates) {
  const queryTerms = [];
  const entity = getBestEntityCandidate(candidates);
  const phrase = getBestPhraseCandidate(candidates);
  const sorted = [...candidates.values()].sort(candidateSort);

  if (entity) {
    pushUniqueTerm(queryTerms, entity.value, 3);
  }

  if (phrase) {
    pushUniqueTerm(queryTerms, phrase.value, 3);
  }

  for (const candidate of sorted) {
    pushUniqueTerm(queryTerms, candidate.value, 3);
    if (queryTerms.length >= 3) break;
  }

  return queryTerms.join(' ');
}

function buildNonPersonQuery(candidates, dominantTopic) {
  if (dominantTopic === 'schedule_calendar') {
    return buildScheduleQuery(candidates);
  }

  if (dominantTopic === 'dfb_penalty') {
    return buildDfbPenaltyQuery(candidates);
  }

  if (
    dominantTopic === 'transfer' ||
    dominantTopic === 'contract' ||
    dominantTopic === 'injury' ||
    dominantTopic === 'statement' ||
    dominantTopic === 'national_team' ||
    dominantTopic === 'match_competition'
  ) {
    return buildTopicQuery(candidates, dominantTopic);
  }

  return buildGeneralQuery(candidates);
}

function getMainEntityFromCandidates(candidates, dominantTopic) {
  if (dominantTopic === 'schedule_calendar') {
    const scheduleTerms = getCandidatesByTopic(candidates, 'schedule_calendar');
    return scheduleTerms[0]?.value || '';
  }

  const entity = getBestEntityCandidate(candidates);
  if (entity) return entity.value;

  const phrase = getBestPhraseCandidate(candidates);
  if (phrase) return phrase.value;

  return '';
}

function getNegativeTopicsForTopic(topic) {
  if (topic === 'schedule_calendar') {
    return [
      'transfer',
      'wechsel',
      'karriereende',
      'verletzung',
      'vertrag',
      'verlängerung',
      'ablöse',
      'wunschspieler',
      'transferalternativen',
    ];
  }

  if (topic === 'transfer') {
    return [
      'sommerfahrplan',
      'testspiel',
      'testspiele',
      'trainingsstart',
      'asien-tour',
      'asientour',
      'trainingslager',
    ];
  }

  if (topic === 'injury') {
    return [
      'transfer',
      'wechsel',
      'sommerfahrplan',
      'testspiel',
    ];
  }

  if (topic === 'contract') {
    return [
      'sommerfahrplan',
      'testspiel',
      'asien-tour',
    ];
  }

  return [];
}

function getSpecificityScore(query, candidates) {
  const terms = normalizeSpaces(query).split(/\s+/).filter(Boolean);

  let score = 0;

  score += Math.min(terms.length * 25, 75);
  score += Math.min(candidates.size * 2, 25);

  if (query.includes('-')) {
    score += 5;
  }

  if (!query || isGenericTerm(query)) {
    score = 0;
  }

  return Math.min(score, 100);
}

function getReadyStatus(query, specificityScore) {
  if (!query) return 'missing_specific_context_keywords';

  if (isGenericTerm(query)) {
    return 'missing_specific_context_keywords';
  }

  if (specificityScore < 25) {
    return 'too_unspecific';
  }

  return 'ready';
}

function getContextSearchKeywordsForPerson(person, candidates, j) {
  const values = [];

  values.push(person.lastName);
  values.push(person.fullName);

  if (Array.isArray(j.context_topics)) {
    values.push(...j.context_topics);
  }

  for (const candidate of [...candidates.values()].sort(candidateSort)) {
    if (
      candidate.kind === 'phrase' ||
      candidate.kind === 'topic' ||
      candidate.kind === 'entity_full' ||
      candidate.kind === 'entity'
    ) {
      values.push(candidate.value);
    }
  }

  return unique(values)
    .filter(value => !isGenericTerm(value))
    .slice(0, 14);
}

function getContextSearchKeywordsGeneral(candidates) {
  return [...candidates.values()]
    .sort(candidateSort)
    .map(candidate => candidate.value)
    .filter(value => !isGenericTerm(value))
    .slice(0, 14);
}

function buildPersonQueryVariants(person) {
  return unique([
    person.lastName,
    person.fullName,
  ]).filter(value => !isGenericTerm(value));
}

function buildNonPersonQueryVariants(query, candidates, dominantTopic) {
  const variants = [];

  if (query) {
    variants.push(query);
  }

  if (dominantTopic === 'schedule_calendar') {
    const scheduleTerms = getCandidatesByTopic(candidates, 'schedule_calendar')
      .map(candidate => candidate.value);

    const compact = [];

    for (const term of scheduleTerms) {
      pushUniqueTerm(compact, term, 3);
      if (compact.length >= 3) break;
    }

    if (compact.length) {
      variants.push(compact.join(' '));
    }
  }

  const bestEntity = getBestEntityCandidate(candidates);
  const bestPhrase = getBestPhraseCandidate(candidates);

  if (bestEntity) variants.push(bestEntity.value);
  if (bestPhrase) variants.push(bestPhrase.value);

  return unique(variants)
    .filter(value => !isGenericTerm(value))
    .slice(0, 4);
}

const output = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const candidates = new Map();
  const sources = getTextSources(j);

  const detectedPerson = detectPerson(j);

  extractContextEntityCandidates(candidates, j);
  extractDetectedPersonCandidates(candidates, detectedPerson);
  extractContextTopicCandidates(candidates, j);
  extractPhraseCandidates(candidates, sources);
  extractCapitalizedCandidates(candidates, sources);
  extractWordCandidates(candidates, sources);

  const dominantTopic = detectDominantTopic(candidates, j);

  let mainEntity = '';
  let query = '';
  let searchMode = '';
  let queryVariants = [];
  let contextSearchKeywords = [];

  if (detectedPerson && detectedPerson.lastName && !isGenericTerm(detectedPerson.lastName)) {
    mainEntity = detectedPerson.lastName;
    query = detectedPerson.lastName;
    searchMode = 'person_lastname_only';
    queryVariants = buildPersonQueryVariants(detectedPerson);
    contextSearchKeywords = getContextSearchKeywordsForPerson(detectedPerson, candidates, j);
  } else {
    query = buildNonPersonQuery(candidates, dominantTopic);
    mainEntity = getMainEntityFromCandidates(candidates, dominantTopic);
    searchMode = query ? 'specific_entity_and_keyword_search' : 'missing_specific_query';
    queryVariants = buildNonPersonQueryVariants(query, candidates, dominantTopic);
    contextSearchKeywords = getContextSearchKeywordsGeneral(candidates);
  }

  const specificityScore = getSpecificityScore(query, candidates);
  const status = getReadyStatus(query, specificityScore);
  const sortedCandidates = [...candidates.values()].sort(candidateSort);

  output.push({
    json: {
      ...j,

      context_main_entity: mainEntity,
      context_single_query: query,
      context_single_query_status: status,

      context_schalketotal_search_mode:
        status === 'ready'
          ? searchMode
          : 'missing_specific_query',

      context_schalketotal_primary_query: query,
      context_schalketotal_query_used: query,
      context_schalketotal_query_variants: queryVariants,

      context_person_full_name: detectedPerson?.fullName || '',
      context_person_last_name: detectedPerson?.lastName || '',
      context_is_person_context: Boolean(detectedPerson?.lastName),

      context_schalketotal_topic_bucket: dominantTopic || 'general',
      context_schalketotal_negative_terms: getNegativeTopicsForTopic(dominantTopic),

      context_search_keywords: contextSearchKeywords,

      context_search_keyword_debug: sortedCandidates
        .slice(0, 24)
        .map(candidate => ({
          value: candidate.value,
          score: candidate.score,
          kind: candidate.kind,
          topics: candidate.topics,
          sources: candidate.sources,
        })),

      context_specificity_score: specificityScore,

      context_main_entity_debug: {
        old_problem_prevented:
          mainEntity !== 'S04' &&
          mainEntity !== 'S04s' &&
          query !== 'S04' &&
          query !== 'S04s',

        person_detection: detectedPerson || null,
        forced_person_lastname_only: Boolean(detectedPerson?.lastName),
        source_fields_used: sources.map(source => source.field),
        dominant_topic: dominantTopic || 'general',
        candidates_total: candidates.size,
        query_terms_count: query ? query.split(/\s+/).filter(Boolean).length : 0,
        selected_query: query,
        selected_main_entity: mainEntity,
        query_variants: queryVariants,
        skipped_generic_entities: Array.isArray(j.context_entities)
          ? j.context_entities.filter(entity => isGenericTerm(entity))
          : [],
      },
    },
  });
}

return output;

// Filter SCHALKETOTAL Context Results
// Universeller redaktioneller Kontextfilter für SCHALKETOTAL.
//
// Grundlogik:
// - Score entscheidet zuerst nur: relevant genug oder raus.
// - Danach zählt Relevanzstufe:
//   Tier 3 = Hauptthema passt
//   Tier 2 = Nebenthema passt
//   Tier 1 = nur Person/Entity passt
// - Innerhalb gleicher Relevanzstufe gewinnt Datum klar vor Score.
// - Score nur als Relevanz-Gate und Tie-Breaker.
// - Low-Value-Formate wie Einzelkritik, Ticker, Aufstellung, Match-Preview werden blockiert.
// - Funktioniert für Personen, Transfers, Verträge, Verletzungen, Statements,
//   Nationalmannschaft/WM, Spiele/Wettbewerbe, Kalender/Sommerfahrplan, DFB-Strafen.
// - Output: pro Ursprungskarte genau 1 Item mit max. 5 Kontextartikeln.

const MAX_RESULTS = 5;
const MIN_SCORE = 75;

function clean(value) {
  return String(value ?? '').trim();
}

function stripHtml(value) {
  return clean(value)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&hellip;/g, '...')
    .replace(/&amp;/g, '&')
    .replace(/&#038;/g, '&')
    .replace(/&#8211;/g, '–')
    .replace(/&#8212;/g, '—')
    .replace(/&#8217;/g, '’')
    .replace(/&#8222;/g, '„')
    .replace(/&#8220;/g, '“')
    .replace(/&#8221;/g, '“')
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function stripAccents(value) {
  return clean(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalize(value) {
  return stripAccents(stripHtml(value))
    .toLowerCase()
    .replace(/[„“"‚‘’'`´]/g, '')
    .replace(/[^\p{L}\p{N}\s-]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeLoose(value) {
  return normalize(value)
    .replace(/-/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function unique(values) {
  const out = [];
  const seen = new Set();

  for (const value of values) {
    const v = clean(value);
    if (!v) continue;

    const key = normalizeLoose(v);
    if (!key || seen.has(key)) continue;

    seen.add(key);
    out.push(v);
  }

  return out;
}

function getTitle(result) {
  return stripHtml(result.title?.rendered || result.title || '');
}

function getExcerpt(result) {
  return stripHtml(result.excerpt?.rendered || result.excerpt || '');
}

function getContent(result) {
  return stripHtml(
    result.content?.rendered ||
    result.content ||
    result.content_preview ||
    ''
  );
}

function containsPhrase(text, phrase) {
  const t = normalizeLoose(text);
  const p = normalizeLoose(phrase);

  if (!t || !p) return false;

  if (p.includes(' ')) {
    return t.includes(p);
  }

  const escaped = p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`(^|\\s)${escaped}(\\s|$)`, 'i').test(t);
}

function getStableKey(j) {
  return (
    clean(j.workflow_item_id) ||
    clean(j.trello_card_id) ||
    clean(j.context_source_url) ||
    clean(j.original_url) ||
    clean(j.generated_title) ||
    clean(j.title) ||
    clean(j.context_single_query)
  );
}

function getOriginalItems() {
  try {
    return $('Prepare SCHALKETOTAL Main Entity Search').all().map(item => item.json || {});
  } catch (error) {}

  try {
