}

function getPairedIndex(item) {
  const paired = item.pairedItem;

  if (!paired) return null;

  if (typeof paired.item === 'number') {
    return paired.item;
  }

  if (Array.isArray(paired) && paired.length && typeof paired[0].item === 'number') {
    return paired[0].item;
  }

  return null;
}

