function isGenericTerm(value) {
  const key = normalizeLoose(value);

  if (!key) return true;
  if (key.length < 3) return true;
  if (/^\d+$/.test(key)) return true;
  if (GENERIC_TERMS.has(key)) return true;
  if (STOPWORDS.has(key)) return true;

  return false;
}

function detectLowValueFormat(title) {
  const t = normalizeLoose(title);

  if (t.includes('einzelkritik')) return 'einzelkritik';
  if (t.includes('noten')) return 'noten';
  if (t.includes('liveticker')) return 'liveticker';
  if (t.includes('ticker')) return 'ticker';
  if (t.includes('aufstellung')) return 'aufstellung';
  if (t.includes('voraussichtliche aufstellung')) return 'aufstellung';
  if (t.includes('startelf')) return 'startelf';
  if (t.includes('pressestimmen')) return 'pressestimmen';
  if (t.includes('player ratings')) return 'player_ratings';

  // Match-/Lineup-Previews, die bei Personen-/Transfer-/Kontextsuche fast immer Müll sind
  if (t.includes('gelb gefahr')) return 'match_preview';
  if (t.includes('gelbgefahr')) return 'match_preview';
  if (t.includes('so lasst') && t.includes('spielen')) return 'match_preview';
  if (t.includes('so lässt') && t.includes('spielen')) return 'match_preview';
  if (t.includes('so koennte') && t.includes('spielen')) return 'match_preview';
  if (t.includes('so konnte') && t.includes('spielen')) return 'match_preview';
  if (t.includes('so könnte') && t.includes('spielen')) return 'match_preview';
  if (t.includes('gegen') && t.includes('spielen')) return 'match_preview';

  return '';
}

function shouldHardBlockLowValueFormat(format) {
  if (!format) return false;

  const alwaysBlock = [
    'einzelkritik',
    'noten',
    'liveticker',
    'ticker',
    'aufstellung',
    'startelf',
    'pressestimmen',
    'player_ratings',
    'match_preview',
  ];

  return alwaysBlock.includes(format);
}

function splitQueryIntoTerms(query) {
  const q = clean(query);
  if (!q) return [];

  const rawParts = q
    .split(/\s+/)
    .map(clean)
    .filter(Boolean);

  const terms = [];

  for (let i = 0; i < rawParts.length; i++) {
    const one = rawParts[i];
    const two = rawParts[i + 1] ? `${rawParts[i]} ${rawParts[i + 1]}` : '';

    terms.push(one);

    if (two && /^[A-ZÄÖÜ]/.test(rawParts[i]) && /^[A-ZÄÖÜ]/.test(rawParts[i + 1])) {
      terms.push(two);
    }
  }

  return terms;
}

function getPersonTerms(original) {
  const values = [];

  if (original.context_person_last_name) values.push(original.context_person_last_name);
  if (original.context_person_full_name) values.push(original.context_person_full_name);
  if (original.context_is_person_context && original.context_main_entity) values.push(original.context_main_entity);

  if (Array.isArray(original.context_schalketotal_query_variants)) {
    values.push(...original.context_schalketotal_query_variants);
  }

  return unique(values).filter(value => !isGenericTerm(value));
}

function getSpecificSearchTerms(original) {
  const values = [];

  if (Array.isArray(original.context_search_keywords)) {
    values.push(...original.context_search_keywords);
  }

  if (Array.isArray(original.context_schalketotal_query_variants)) {
    values.push(...original.context_schalketotal_query_variants);
  }

  values.push(...splitQueryIntoTerms(original.context_single_query));
  values.push(...splitQueryIntoTerms(original.context_schalketotal_query_used));

  if (!isGenericTerm(original.context_main_entity)) {
    values.push(original.context_main_entity);
  }

  if (Array.isArray(original.context_entities)) {
    for (const entity of original.context_entities) {
      if (!isGenericTerm(entity)) {
        values.push(entity);
      }
    }
  }

  return unique(values)
    .map(clean)
    .filter(Boolean)
    .filter(value => !isGenericTerm(value))
    .filter(value => normalizeLoose(value).length >= 3)
    .slice(0, 22);
}

function getOriginalText(original) {
  return normalizeLoose([
    original.context_search_title,
    original.generated_title,
    original.original_title,
    original.generated_social,
    original.original_text,
    original.context_single_query,
    Array.isArray(original.context_topics) ? original.context_topics.join(' ') : '',
    Array.isArray(original.context_search_keywords) ? original.context_search_keywords.join(' ') : '',
  ].filter(Boolean).join(' '));
}

function getOriginalTopic(original) {
  const bucket = normalizeLoose(original.context_schalketotal_topic_bucket);

  if (bucket && bucket !== 'general') return bucket;

  const text = getOriginalText(original);

  if (
    text.includes('sommerfahrplan') ||
    text.includes('testspiel') ||
    text.includes('testspiele') ||
    text.includes('trainingsstart') ||
    text.includes('training start') ||
    text.includes('start of training') ||
    text.includes('saisonvorbereitung') ||
    text.includes('vorbereitung') ||
