    text.includes('wechsel') ||
    text.includes('leihe') ||
    text.includes('kaufoption') ||
    text.includes('ablose') ||
    text.includes('ablöse') ||
    text.includes('verpflichtung') ||
    text.includes('abgang') ||
    text.includes('gerucht') ||
    text.includes('gerüchte') ||
    text.includes('geruechte') ||
    text.includes('interesse') ||
    text.includes('reported interest') ||
    text.includes('preisschild') ||
    text.includes('ablösesumme') ||
    text.includes('ablosesumme') ||
    text.includes('ins visier') ||
    text.includes('im rennen')
  ) {
    return 'transfer';
  }

  if (
    text.includes('nationalmannschaft') ||
    text.includes('dfb team') ||
    text.includes('dfb-team') ||
    text.includes('wm') ||
    text.includes('world cup') ||
    text.includes('wm kader') ||
    text.includes('wm-kader')
