    return 'national_team';
  }

  if (
    text.includes('verletzung') ||
    text.includes('verletzt') ||
    text.includes('ausfall') ||
    text.includes('comeback') ||
    text.includes('reha')
  ) {
    return 'injury';
  }

  if (
    text.includes('vertrag') ||
    text.includes('vertrags') ||
    text.includes('verlangerung') ||
    text.includes('verlängerung') ||
    text.includes('ausstiegsklausel')
  ) {
    return 'contract';
  }

  if (
    text.includes('interview') ||
    text.includes('aussage') ||
    text.includes('statement') ||
    text.includes('erklart') ||
    text.includes('erklärt') ||
    text.includes('stellt klar') ||
    text.includes('fokus')
  ) {
    return 'statement';
  }

  if (
    text.includes('supercup') ||
    text.includes('dfb pokal') ||
    text.includes('dfb-pokal') ||
    text.includes('champions league') ||
    text.includes('bundesliga')
  ) {
    return 'match_competition';
  }

  return 'general';
}

function getOriginalSecondaryTopics(original) {
  const text = getOriginalText(original);
  const originalTopic = getOriginalTopic(original);
  const topics = new Set();

