function getHardNegativeTopicsForOriginalTopic(topic) {
  if (topic === 'schedule_calendar') return ['transfer', 'injury', 'contract'];
  if (topic === 'transfer') return ['schedule_calendar'];
  if (topic === 'injury') return ['schedule_calendar', 'transfer'];
  if (topic === 'contract') return ['schedule_calendar'];
  if (topic === 'dfb_penalty') return ['schedule_calendar', 'transfer'];

  return [];
}

function getSoftNegativeTerms(original, topic) {
  const values = [];

  if (Array.isArray(original.context_schalketotal_negative_terms)) {
    values.push(...original.context_schalketotal_negative_terms);
