function countTermHits(terms, title, excerpt, content) {
  const hits = [];

  for (const term of terms) {
    const inTitle = containsPhrase(title, term);
    const inExcerpt = containsPhrase(excerpt, term);
    const inContent = containsPhrase(content, term);

    if (inTitle || inExcerpt || inContent) {
      hits.push({
        term,
        inTitle,
        inExcerpt,
        inContent,
      });
    }
  }

  return hits;
}

function scoreSpecificTermHits(hits) {
  let score = 0;

  for (const hit of hits) {
    if (hit.inTitle) score += 32;
    if (hit.inExcerpt) score += 20;
    if (hit.inContent) score += 9;
  }

  return Math.min(score, 180);
}

function scorePersonHits(hits) {
  let score = 0;

  for (const hit of hits) {
    const isFullName = clean(hit.term).split(/\s+/).length >= 2;

    if (hit.inTitle) score += isFullName ? 115 : 90;
    if (hit.inExcerpt) score += isFullName ? 75 : 55;
    if (hit.inContent) score += isFullName ? 45 : 30;
  }

  return Math.min(score, 230);
}

function scoreTopicRequiredHits(topic, title, excerpt, content) {
  const requiredTerms = getTopicRequiredTerms(topic);
  const hits = countTermHits(requiredTerms, title, excerpt, content);

  let score = 0;

  for (const hit of hits) {
    if (hit.inTitle) score += 38;
    if (hit.inExcerpt) score += 24;
    if (hit.inContent) score += 10;
  }

  return {
    score: Math.min(score, 160),
    hits,
  };
}

function getRecencyBonus(dateValue) {
  const raw = clean(dateValue);
  if (!raw) return 0;

  const timestamp = new Date(raw).getTime();
  if (!Number.isFinite(timestamp)) return 0;

  const now = Date.now();
  const ageDays = Math.max(0, Math.floor((now - timestamp) / (1000 * 60 * 60 * 24)));

  if (ageDays <= 3) return 35;
  if (ageDays <= 7) return 30;
  if (ageDays <= 14) return 24;
  if (ageDays <= 30) return 18;
  if (ageDays <= 90) return 10;
  if (ageDays <= 180) return 5;

  return 0;
}

function getDateTimestamp(dateValue) {
  const raw = clean(dateValue);
  if (!raw) return 0;

  const timestamp = new Date(raw).getTime();

  return Number.isFinite(timestamp) ? timestamp : 0;
}

function hasHardTopicMismatch(originalTopic, resultTopics, topicRequiredHits) {
  if (!originalTopic || originalTopic === 'general') return false;

  const negativeTopics = getHardNegativeTopicsForOriginalTopic(originalTopic);
  const hasNegativeTopic = resultTopics.some(topic => negativeTopics.includes(topic));

  if (!hasNegativeTopic) return false;

  return topicRequiredHits.length === 0;
}

function getRelevanceTier({
  originalTopic,
  resultTopics,
  topicHits,
  specificHits,
  personHits,
  isPersonContext,
  matchingSecondaryTopics,
  hasMainEntityMatch,
}) {
  const hasPrimaryTopicMatch =
    originalTopic === 'general' ||
    resultTopics.includes(originalTopic) ||
    topicHits > 0;

  if (hasPrimaryTopicMatch) return 3;

  if (matchingSecondaryTopics.length > 0) return 2;

  if (isPersonContext && personHits > 0) return 1;

  if (!isPersonContext && hasMainEntityMatch) return 1;

  if (specificHits > 0) return 1;

  return 0;
}

function scoreResult(result, original) {
  const title = getTitle(result);
  const excerpt = getExcerpt(result);
  const content = getContent(result);

  const originalTopic = getOriginalTopic(original);
  const originalSecondaryTopics = getOriginalSecondaryTopics(original);
  const resultTopics = detectResultTopics(result);

  const isPersonContext =
    original.context_is_person_context === true ||
    Boolean(clean(original.context_person_last_name)) ||
    Boolean(clean(original.context_person_full_name));

  const personTerms = getPersonTerms(original);
  const personHits = countTermHits(personTerms, title, excerpt, content);

  const specificTerms = getSpecificSearchTerms(original);
  const specificHits = countTermHits(specificTerms, title, excerpt, content);

  const topicRequired = scoreTopicRequiredHits(originalTopic, title, excerpt, content);

  const mainEntity =
    !isGenericTerm(original.context_main_entity)
      ? clean(original.context_main_entity)
      : '';

  const hasMainEntityMatch =
    Boolean(mainEntity) &&
    (
      containsPhrase(title, mainEntity) ||
      containsPhrase(excerpt, mainEntity) ||
      containsPhrase(content, mainEntity)
    );

  const matchingSecondaryTopics = originalSecondaryTopics.filter(topic => resultTopics.includes(topic));

  const recencyBonus = getRecencyBonus(result.date || result.modified);
  const dateTimestamp = getDateTimestamp(result.date || result.modified);

  let score = 0;
  const reasons = [];
  const penalties = [];
  const blockedReasons = [];

  const lowValueFormat = detectLowValueFormat(title);

  if (lowValueFormat) {
    penalties.push(`low_value_format_${lowValueFormat}`);

    if (shouldHardBlockLowValueFormat(lowValueFormat)) {
      score -= 250;
      blockedReasons.push(`blocked_low_value_format_${lowValueFormat}`);
    } else {
      score -= 120;
    }
  }

  if (isPersonContext) {
    if (!personHits.length) {
      score -= 250;
      blockedReasons.push('person_not_found');
    } else {
      score += scorePersonHits(personHits);
      reasons.push(`person_hits_${personHits.length}`);
    }
  }

  if (!isPersonContext && mainEntity) {
    if (containsPhrase(title, mainEntity)) {
      score += 80;
      reasons.push('main_entity_in_title');
    }

    if (containsPhrase(excerpt, mainEntity)) {
      score += 50;
      reasons.push('main_entity_in_excerpt');
    }

    if (containsPhrase(content, mainEntity)) {
      score += 25;
      reasons.push('main_entity_in_content');
    }
  }

  if (specificHits.length) {
    score += scoreSpecificTermHits(specificHits);
    reasons.push(`specific_keyword_hits_${specificHits.length}`);
  }

  if (topicRequired.hits.length) {
    score += topicRequired.score;
    reasons.push(`topic_required_hits_${topicRequired.hits.length}`);
  }

  if (resultTopics.includes(originalTopic) && originalTopic !== 'general') {
    score += 55;
    reasons.push(`same_topic_${originalTopic}`);
  }

  if (matchingSecondaryTopics.length) {
    score += Math.min(matchingSecondaryTopics.length * 25, 50);
    reasons.push(`secondary_topic_match_${matchingSecondaryTopics.join('_')}`);
  }

  if (recencyBonus) {
    score += recencyBonus;
    reasons.push(`recency_bonus_${recencyBonus}`);
  }

  if (hasHardTopicMismatch(originalTopic, resultTopics, topicRequired.hits)) {
    score -= 240;
    blockedReasons.push(`hard_topic_mismatch_${originalTopic}_vs_${resultTopics.join('_') || 'unknown'}`);
  }

  const softNegativeTerms = getSoftNegativeTerms(original, originalTopic);
  const softNegativeHits = countTermHits(softNegativeTerms, title, excerpt, content);

  if (softNegativeHits.length) {
    const penalty = Math.min(softNegativeHits.length * 35, 120);
    score -= penalty;
    penalties.push(`negative_term_hits_${softNegativeHits.length}`);
  }

  const hasIdentityMatch =
    isPersonContext
      ? personHits.length > 0
      : (
          specificHits.length > 0 ||
          topicRequired.hits.length > 0 ||
          hasMainEntityMatch
        );

  if (!hasIdentityMatch) {
    score -= 220;
    blockedReasons.push('no_identity_or_specific_match');
  }

  if (originalTopic === 'schedule_calendar' && topicRequired.hits.length === 0) {
    score -= 180;
    blockedReasons.push('schedule_topic_without_schedule_hit');
  }

  if (originalTopic === 'dfb_penalty' && topicRequired.hits.length === 0) {
    score -= 180;
    blockedReasons.push('dfb_penalty_without_dfb_or_penalty_hit');
  }

  const relevanceTier = getRelevanceTier({
    originalTopic,
    resultTopics,
    topicHits: topicRequired.hits.length,
    specificHits: specificHits.length,
    personHits: personHits.length,
    isPersonContext,
    matchingSecondaryTopics,
    hasMainEntityMatch,
  });

  if (relevanceTier === 0) {
    score -= 180;
    blockedReasons.push('relevance_tier_0');
  }

  return {
    score,
    reasons,
    penalties,
    blockedReasons,

    personHits: personHits.length,
    topicHits: topicRequired.hits.length,
    specificHits: specificHits.length,

    originalTopic,
    originalSecondaryTopics,
    resultTopics,

    relevanceTier,
    primaryTopicMatch: relevanceTier === 3,
    secondaryTopicMatch: relevanceTier === 2,

    recencyBonus,
    dateTimestamp,

    matchedPersonTerms: personHits.map(hit => hit.term),
    matchedSpecificTerms: specificHits.map(hit => hit.term),
    matchedTopicTerms: topicRequired.hits.map(hit => hit.term),
    negativeTerms: softNegativeHits.map(hit => hit.term),

    lowValueFormat,
  };
}

const inputItems = $input.all();
const originalItems = getOriginalItems();

const groups = new Map();

for (let i = 0; i < originalItems.length; i++) {
  const original = originalItems[i] || {};
  const key = getStableKey(original) || `original_index_${i}`;

  groups.set(key, {
    key,
    originalIndex: i,
    original,
    rawResults: [],
  });
}

if (!groups.size) {
  groups.set('fallback_group_0', {
    key: 'fallback_group_0',
    originalIndex: 0,
    original: {},
    rawResults: [],
  });
}

const groupKeys = Array.from(groups.keys());
const originalCount = originalItems.length || groups.size;
const totalInputCount = inputItems.length;

const fallbackChunkSize =
  originalCount > 1 && totalInputCount >= originalCount
    ? Math.ceil(totalInputCount / originalCount)
    : totalInputCount;

for (let position = 0; position < inputItems.length; position++) {
  const item = inputItems[position];
  const result = item.json || {};

  let groupKey = '';

  const pairedIndex = getPairedIndex(item);

  if (
    pairedIndex !== null &&
    pairedIndex >= 0 &&
    pairedIndex < groupKeys.length
  ) {
    groupKey = groupKeys[pairedIndex];
  }

  if (!groupKey) {
    const resultKey = getStableKey(result);
    if (resultKey && groups.has(resultKey)) {
      groupKey = resultKey;
    }
  }

  if (!groupKey && originalCount > 1) {
    const fallbackIndex = Math.min(
      Math.floor(position / fallbackChunkSize),
      groupKeys.length - 1
    );

    groupKey = groupKeys[fallbackIndex];
  }

  if (!groupKey) {
    groupKey = groupKeys[0];
  }

  groups.get(groupKey).rawResults.push(result);
}

const output = [];

for (const group of groups.values()) {
  const original = group.original || {};
  const rawResults = group.rawResults || [];

  const seenIds = new Set();
  const candidates = [];
  const rejected = [];

  for (const result of rawResults) {
    const id = clean(result.id);
    if (!id || seenIds.has(id)) continue;
    seenIds.add(id);

    const title = getTitle(result);
    const excerpt = getExcerpt(result);
    const link = clean(result.link || result.url);
    const date = clean(result.date);

    const scoring = scoreResult(result, original);

    const candidateBase = {
      id,
      date,
      link,
      title,
      excerpt,

      context_score: scoring.score,
      context_score_reasons: scoring.reasons,
      context_score_penalties: scoring.penalties,
      context_blocked_reasons: scoring.blockedReasons,

      context_relevance_tier: scoring.relevanceTier,
      context_primary_topic_match: scoring.primaryTopicMatch,
      context_secondary_topic_match: scoring.secondaryTopicMatch,

      context_person_hits: scoring.personHits,
      context_topic_hits: scoring.topicHits,
      context_specific_hits: scoring.specificHits,

      context_original_topic: scoring.originalTopic,
      context_original_secondary_topics: scoring.originalSecondaryTopics,
      context_result_topics: scoring.resultTopics,

      context_recency_bonus: scoring.recencyBonus,
      context_date_timestamp: scoring.dateTimestamp,

      context_low_value_format: scoring.lowValueFormat,

      context_matched_person_terms: scoring.matchedPersonTerms,
      context_matched_specific_terms: scoring.matchedSpecificTerms,
      context_matched_topic_terms: scoring.matchedTopicTerms,
      context_negative_terms: scoring.negativeTerms,
    };

    if (scoring.score < MIN_SCORE || scoring.blockedReasons.length) {
      rejected.push(candidateBase);
      continue;
    }

    candidates.push(candidateBase);
  }

  candidates.sort((a, b) => {
    const tierA = Number(a.context_relevance_tier) || 0;
    const tierB = Number(b.context_relevance_tier) || 0;

    if (tierA !== tierB) {
      return tierB - tierA;
    }

    const dateA = Number(a.context_date_timestamp) || 0;
    const dateB = Number(b.context_date_timestamp) || 0;

    if (dateA !== dateB) {
      return dateB - dateA;
    }

    const scoreA = Number(a.context_score) || 0;
    const scoreB = Number(b.context_score) || 0;

    return scoreB - scoreA;
  });

  rejected.sort((a, b) => {
    const tierA = Number(a.context_relevance_tier) || 0;
    const tierB = Number(b.context_relevance_tier) || 0;

    if (tierA !== tierB) {
      return tierB - tierA;
    }

    const dateA = Number(a.context_date_timestamp) || 0;
    const dateB = Number(b.context_date_timestamp) || 0;

    if (dateA !== dateB) {
      return dateB - dateA;
    }

    return (Number(b.context_score) || 0) - (Number(a.context_score) || 0);
  });

  const selected = candidates.slice(0, MAX_RESULTS);

  output.push({
    json: {
      ...original,

      schalketotal_context_results_raw_count: rawResults.length,
      schalketotal_context_results_count: selected.length,
      schalketotal_context_results: selected,
      schalketotal_context_post_ids: selected.map(item => item.id),
      schalketotal_context_status: selected.length ? 'found' : 'no_relevant_internal_context',

      schalketotal_context_debug: {
        group_key: group.key,
        original_index: group.originalIndex,

        main_entity:
          !isGenericTerm(original.context_main_entity)
            ? clean(original.context_main_entity)
            : '',

        is_person_context:
          original.context_is_person_context === true ||
          Boolean(clean(original.context_person_last_name)) ||
          Boolean(clean(original.context_person_full_name)),

        person_terms: getPersonTerms(original),

        original_topic: getOriginalTopic(original),
        original_secondary_topics: getOriginalSecondaryTopics(original),

        specific_search_terms: getSpecificSearchTerms(original),

        query_used: clean(original.context_schalketotal_query_used || original.context_single_query),

        query_variants: Array.isArray(original.context_schalketotal_query_variants)
          ? original.context_schalketotal_query_variants
          : [],

        sort_logic: 'tier_first_then_date_then_score',
        tier_meaning: {
          3: 'primary_topic_match',
          2: 'secondary_topic_match',
          1: 'entity_or_person_match_only',
          0: 'not_relevant',
        },

        raw_count: rawResults.length,
        selected_count: selected.length,
        rejected_count: rejected.length,

        min_score: MIN_SCORE,
        max_results: MAX_RESULTS,

        total_groups: groups.size,
        total_input_items: inputItems.length,
        fallback_chunk_size: fallbackChunkSize,

        selected_preview: selected.slice(0, 5).map(item => ({
          id: item.id,
          title: item.title,
          score: item.context_score,
          tier: item.context_relevance_tier,
          primary_topic_match: item.context_primary_topic_match,
          secondary_topic_match: item.context_secondary_topic_match,
          date: item.date,
          reasons: item.context_score_reasons,
          matched_person_terms: item.context_matched_person_terms,
          matched_specific_terms: item.context_matched_specific_terms,
          matched_topic_terms: item.context_matched_topic_terms,
          result_topics: item.context_result_topics,
          recency_bonus: item.context_recency_bonus,
          low_value_format: item.context_low_value_format,
        })),

        rejected_preview: rejected.slice(0, 8).map(item => ({
          id: item.id,
          title: item.title,
          score: item.context_score,
          tier: item.context_relevance_tier,
          blocked: item.context_blocked_reasons,
