          recency_bonus: item.context_recency_bonus,
          low_value_format: item.context_low_value_format,
        })),
      },
    },
  });
}

return output;

// Prepare SCHALKETOTAL Context Article Fetch
// Macht aus schalketotal_context_results einzelne Items,
// damit der nächste HTTP-Node jeden Kontextartikel vollständig laden kann.

function clean(value) {
