// Build SCHALKETOTAL Context Block
// Baut aus geladenen SCHALKETOTAL-Kontextartikeln einen kompakten Kontextblock
// für die spätere Artikelgenerierung.
//
// Wichtig:
// - Neuester Artikel wird als aktueller Stand markiert
// - Ältere Artikel dienen nur als Hintergrund
// - Kein 1:1-Kopieren alter Artikel
// - Quellenlinks bleiben erhalten
// - Kontextartikel werden separat gespeichert

function clean(value) {
  return String(value ?? '').trim();
}

function stripHtml(value) {
  return clean(value)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<figure[\s\S]*?<\/figure>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&hellip;/g, '...')
    .replace(/&amp;/g, '&')
    .replace(/&#8211;/g, '–')
    .replace(/&#8212;/g, '—')
    .replace(/&#8217;/g, '’')
    .replace(/&#8222;/g, '„')
    .replace(/&#8220;/g, '“')
    .replace(/&#8221;/g, '“')
    .replace(/\s+/g, ' ')
    .trim();
}

function truncate(value, maxLength) {
  const text = clean(value);

  if (text.length <= maxLength) return text;

  return text.slice(0, maxLength).replace(/\s+\S*$/, '').trim() + '...';
}

function getTitle(item) {
  return stripHtml(item.title?.rendered || item.title || '');
}

function getContent(item) {
  return stripHtml(item.content?.rendered || item.content || '');
}

function getExcerpt(item) {
  return stripHtml(item.excerpt?.rendered || item.excerpt || '');
}

function getOriginalContext() {
  try {
    return $('Filter SCHALKETOTAL Context Results').first().json || {};
  } catch (error) {}

  try {
    return $('Prepare SCHALKETOTAL Main Entity Search').first().json || {};
  } catch (error) {}

  try {
    return $('Prepare Context Search Input').first().json || {};
  } catch (error) {}

  return {};
}

function formatGermanDate(value) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return clean(value);
  }

  return new Intl.DateTimeFormat('de-DE', {
    timeZone: 'Europe/Berlin',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(date) + ' Uhr';
}

const original = getOriginalContext();

const articles = [];

for (const item of $input.all()) {
  const j = item.json || {};

  const id = clean(j.id);
  const title = getTitle(j);
  const link = clean(j.link);
  const date = clean(j.date);
  const excerpt = getExcerpt(j);
  const content = getContent(j);

  if (!id || !title || !content) continue;

  articles.push({
    id,
    date,
    date_german: formatGermanDate(date),
    title,
    link,
    excerpt,
    content_preview: truncate(content, 1400),
    content_length: content.length,
  });
}

// Wichtig: neuester Kontextartikel zuerst
articles.sort((a, b) => {
  return new Date(b.date).getTime() - new Date(a.date).getTime();
});

const latestArticle = articles[0] || null;
const backgroundArticles = articles.slice(1);

const latestContextBlock = latestArticle
  ? [
      'AKTUELLER STAND AUS SCHALKETOTAL-ARCHIV:',
      `Titel: ${latestArticle.title}`,
      `Datum: ${latestArticle.date_german}`,
      `URL: ${latestArticle.link}`,
      `Inhalt: ${truncate(latestArticle.content_preview, 1200)}`,
    ].join('\n')
  : '';

const backgroundLines = [];

backgroundArticles.forEach((article, index) => {
  backgroundLines.push(
    `HINTERGRUND ${index + 1}: ${article.title}`,
    `Datum: ${article.date_german}`,
    `URL: ${article.link}`,
    `Inhalt: ${truncate(article.content_preview, 800)}`,
