  );
});

const timelineLines = articles.map((article, index) => {
  const label = index === 0 ? 'Aktueller Stand' : 'Hintergrund';
  return `${index + 1}. ${label} – ${article.date_german}: ${article.title}`;
});

const contextBlock = [
  'WICHTIGE EINORDNUNG FÜR DIE ARTIKELGENERIERUNG:',
  'Der neueste Kontextartikel gilt als aktuellster bekannter Stand aus dem SCHALKETOTAL-Archiv.',
  'Ältere Artikel dürfen nur als Hintergrund genutzt werden.',
  'Bei Widersprüchen gilt immer der neueste Stand.',
  'Formulierungen aus alten Artikeln dürfen nicht übernommen werden.',
  '',
  latestContextBlock,
  '',
  'ZEITLICHE EINORDNUNG:',
  timelineLines.join('\n'),
  '',
  'WEITERE HINTERGRUNDARTIKEL:',
  backgroundLines.join('\n').trim(),
].filter(Boolean).join('\n');

return [
  {
    json: {
      ...original,

      schalketotal_context_article_count: articles.length,
      schalketotal_context_articles: articles,

      schalketotal_latest_context_article: latestArticle,
      schalketotal_background_context_articles: backgroundArticles,

