      schalketotal_context_block_status: articles.length ? 'ready' : 'empty',

      context_available: articles.length > 0,
      context_sources_internal_count: articles.length,
      context_current_status_source: latestArticle ? latestArticle.link : '',
      context_current_status_title: latestArticle ? latestArticle.title : '',
