];

// Normalize Editorial Context Facts
// Parst den JSON-Output aus "Extract Editorial Context Facts"
// und baut daraus stabile Felder für die spätere Artikelgenerierung.
//
// Wichtig:
// - Originaldaten aus "Build SCHALKETOTAL Context Block" bleiben erhalten
// - KI-Kontextbriefing wird separat gespeichert
// - Kontext wird in context_from_existing_articles für den Artikelprompt bereitgestellt

function clean(value) {
  return String(value ?? '').trim();
}

function tryGetNodeJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (error) {
    return {};
  }
}

function extractTextFromOpenAiOutput(j) {
  if (typeof j === 'string') return j;

  if (typeof j.text === 'string') return j.text;
  if (typeof j.output_text === 'string') return j.output_text;
  if (typeof j.content === 'string') return j.content;
  if (typeof j.message === 'string') return j.message;
  if (typeof j.response === 'string') return j.response;

  if (Array.isArray(j.output)) {
    for (const out of j.output) {
      if (Array.isArray(out.content)) {
        for (const content of out.content) {
          if (typeof content.text === 'string') {
            return content.text;
          }
        }
      }
    }
  }

  if (Array.isArray(j.content)) {
    for (const content of j.content) {
      if (typeof content.text === 'string') {
        return content.text;
      }
      if (typeof content === 'string') {
        return content;
      }
    }
  }

  if (j.choices?.[0]?.message?.content) {
    return j.choices[0].message.content;
  }

  return '';
}

function parseJsonLoose(value) {
  let text = clean(value);

  if (!text) {
    return null;
  }

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    return JSON.parse(text);
  } catch (error) {}

  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace >= 0 && lastBrace > firstBrace) {
    const jsonText = text.slice(firstBrace, lastBrace + 1);

    try {
      return JSON.parse(jsonText);
    } catch (error) {}
  }

  return null;
}

function asArray(value) {
  if (Array.isArray(value)) {
    return value.map(clean).filter(Boolean);
  }

  if (typeof value === 'string' && value.trim()) {
    return [clean(value)];
  }

  return [];
}

function buildBriefing(facts, rawContext) {
  const lines = [];

  lines.push('REDAKTIONELLES KONTEXT-BRIEFING AUS BESTEHENDEN SCHALKETOTAL-ARTIKELN');
  lines.push('');
  lines.push('Wichtig: Dieser Kontext dient nur zur Einordnung. Keine Formulierungen kopieren. Bei Widersprüchen gilt der aktuelle Stand.');
  lines.push('');

  if (facts.context_quality) {
    lines.push(`Kontextqualität: ${facts.context_quality}`);
  }

  if (facts.current_status) {
    lines.push('');
    lines.push('Aktueller Stand:');
    lines.push(clean(facts.current_status));
  }

  if (facts.main_news_angle) {
    lines.push('');
    lines.push('Nachrichtenkern:');
    lines.push(clean(facts.main_news_angle));
  }

  const latest = asArray(facts.latest_context_facts);
  if (latest.length) {
    lines.push('');
    lines.push('Fakten aus dem aktuellsten Kontextartikel:');
    latest.forEach(fact => lines.push(`- ${fact}`));
  }

  const background = asArray(facts.background_facts);
  if (background.length) {
    lines.push('');
    lines.push('Hintergrundfakten aus älteren Kontextartikeln:');
    background.forEach(fact => lines.push(`- ${fact}`));
  }

  const timeline = asArray(facts.timeline);
  if (timeline.length) {
    lines.push('');
    lines.push('Zeitliche Entwicklung:');
    timeline.forEach(fact => lines.push(`- ${fact}`));
  }

  const uncertain = asArray(facts.uncertain_points);
  if (uncertain.length) {
    lines.push('');
    lines.push('Unsichere/offene Punkte sauber kennzeichnen:');
    uncertain.forEach(fact => lines.push(`- ${fact}`));
  }

  const safe = asArray(facts.safe_article_points);
  if (safe.length) {
    lines.push('');
    lines.push('Sicher verwendbare Artikelpunkte:');
    safe.forEach(fact => lines.push(`- ${fact}`));
  }

  const lengthSupport = asArray(facts.length_support_points);
  if (lengthSupport.length) {
    lines.push('');
    lines.push('Punkte zur sinnvollen Artikellänge von 330 bis 390 Wörtern:');
    lengthSupport.forEach(fact => lines.push(`- ${fact}`));
  }

  const sourceNotes = asArray(facts.source_handling_notes);
  if (sourceNotes.length) {
    lines.push('');
    lines.push('Quellenhinweise:');
    sourceNotes.forEach(fact => lines.push(`- ${fact}`));
  }

  const doNotClaim = asArray(facts.do_not_claim);
  if (doNotClaim.length) {
    lines.push('');
    lines.push('Nicht behaupten:');
    doNotClaim.forEach(fact => lines.push(`- ${fact}`));
  }

  const structure = asArray(facts.recommended_article_structure);
  if (structure.length) {
    lines.push('');
    lines.push('Empfohlene Artikelstruktur:');
    structure.forEach(fact => lines.push(`- ${fact}`));
  }

  const viability = facts.minimum_article_viability || {};
  lines.push('');
  lines.push('Mindestlänge-Einschätzung:');
  lines.push(`can_write_330_words: ${Boolean(viability.can_write_330_words)}`);
  if (viability.reason) {
    lines.push(`Begründung: ${clean(viability.reason)}`);
  }

  return lines.join('\n').trim();
}

const original =
  tryGetNodeJson('Build SCHALKETOTAL Context Block') ||
  tryGetNodeJson('Filter SCHALKETOTAL Context Results') ||
  {};

const output = [];

for (const item of $input.all()) {
  const j = item.json || {};

  const rawText = extractTextFromOpenAiOutput(j);
  const facts = parseJsonLoose(rawText);

  if (!facts) {
    output.push({
      json: {
        ...original,

        editorial_context_parse_status: 'error',
        editorial_context_parse_error: 'Could not parse JSON from Extract Editorial Context Facts',
        editorial_context_raw_output: rawText,

        context_from_existing_articles: clean(original.schalketotal_context_block),
        context_editorial_briefing: '',
        context_quality: 'unknown',
        context_minimum_article_viability: false,
      },
    });
    continue;
  }

  const briefing = buildBriefing(facts, original.schalketotal_context_block);

  const canWrite330Words = Boolean(facts.minimum_article_viability?.can_write_330_words);

  output.push({
    json: {
      ...original,

      editorial_context_parse_status: 'ok',
      editorial_context_raw_output: rawText,
      editorial_context_facts: facts,

      context_quality: clean(facts.context_quality),
      context_current_status: clean(facts.current_status),
      context_main_news_angle: clean(facts.main_news_angle),

      context_latest_facts: asArray(facts.latest_context_facts),
      context_background_facts: asArray(facts.background_facts),
      context_timeline: asArray(facts.timeline),
      context_uncertain_points: asArray(facts.uncertain_points),
      context_safe_article_points: asArray(facts.safe_article_points),
      context_length_support_points: asArray(facts.length_support_points),
      context_do_not_claim: asArray(facts.do_not_claim),
      context_recommended_article_structure: asArray(facts.recommended_article_structure),

      context_minimum_article_viability: canWrite330Words,
      context_minimum_article_viability_reason: clean(facts.minimum_article_viability?.reason),

      context_editorial_briefing: briefing,

      // Dieses Feld nutzt dein bestehender Artikelprompt bereits.
      context_from_existing_articles: briefing,

      context_ready_for_article_generation:
        canWrite330Words &&
        ['strong', 'usable'].includes(clean(facts.context_quality).toLowerCase()),
    },
  });
}

return output;

// Prepare Context Review Links
