// Decide External Context Needed
// Entscheidet, ob der interne SCHALKETOTAL-Kontext ausreicht
// oder ob zusätzlich externe Websuche nötig ist.
//
// Kompatibel mit dem neuen Node:
// "Filter SCHALKETOTAL Context Results"
//
// Grundlogik:
// - Der Filter entscheidet bereits, welche internen Treffer relevant sind.
// - Dieser Node bewertet nicht mehr komplett neu über wilde Keyword-Extraktion.
// - Er nutzt die neuen Felder:
//   context_relevance_tier
//   context_primary_topic_match
//   context_secondary_topic_match
//   context_original_topic
//   context_result_topics
//   context_score
//   context_low_value_format
// - Bei X-Quellen ist die Hürde höher.
// - Wenige oder schwache interne Treffer => externe Suche.
// - Gute interne Hauptthema-Treffer => keine externe Suche nötig.

const MIN_ACCEPTABLE_SCORE = 75;
const MIN_STRONG_SCORE = 120;
const MIN_X_PRIMARY_RESULTS = 2;
const MIN_DEFAULT_PRIMARY_RESULTS = 1;

function clean(value) {
  return String(value ?? '').trim();
}

function stripAccents(value) {
  return clean(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalizeKey(value) {
  return stripAccents(value)
    .toLowerCase()
    .replace(/[\s-]+/g, '_')
    .replace(/[^\p{L}\p{N}_]/gu, '')
    .replace(/_+/g, '_')
    .replace(/^_+|_+$/g, '')
    .trim();
}

function toNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
}

function unique(values) {
  const out = [];
  const seen = new Set();

  for (const value of values) {
    const v = clean(value);
    if (!v) continue;

    const key = v.toLowerCase();
    if (seen.has(key)) continue;

    seen.add(key);
    out.push(v);
  }

  return out;
}

function isTrue(value) {
  if (value === true) return true;

  const v = clean(value).toLowerCase();

  return ['true', 'yes', 'ja', '1'].includes(v);
}

function isFalse(value) {
  if (value === false) return true;

  const v = clean(value).toLowerCase();

  return ['false', 'no', 'nein', '0'].includes(v);
}

function isXSource(j) {
  const url = clean(
    j.original_url ||
    j.source_url ||
    j.context_source_url ||
    j.wp_source_url ||
    ''
  ).toLowerCase();

  const sourceType = clean(j.source_type || j.original_source_type || '').toLowerCase();
  const contextReason = clean(j.context_reason || '').toLowerCase();

  return (
    url.includes('x.com/') ||
    url.includes('twitter.com/') ||
    sourceType.includes('x') ||
    contextReason === 'x_source'
  );
}

function getResultArray(j) {
  return Array.isArray(j.schalketotal_context_results)
    ? j.schalketotal_context_results
    : [];
}

function getResultTopics(result) {
  if (!Array.isArray(result.context_result_topics)) return [];

  return result.context_result_topics
    .map(normalizeKey)
    .filter(Boolean);
}

function getOriginalTopic(j, results) {
  const directTopic = clean(
    j.context_schalketotal_topic_bucket ||
    j.context_original_topic ||
    ''
  );

  if (directTopic) {
    return normalizeKey(directTopic);
  }

  for (const result of results) {
    const topic = clean(result.context_original_topic);
    if (topic) return normalizeKey(topic);
  }

  return 'general';
}

function isGeneralTopic(topic) {
  return !topic || topic === 'general';
}

function getResultTier(result) {
  const tier = toNumber(result.context_relevance_tier);

  if (tier > 0) return tier;

  if (isTrue(result.context_primary_topic_match)) return 3;
  if (isTrue(result.context_secondary_topic_match)) return 2;

  return 0;
}

function getResultScore(result) {
  return toNumber(result.context_score);
}

function hasLowValueFormat(result) {
  const format = clean(result.context_low_value_format);

  if (format) return true;

  const blockedReasons = Array.isArray(result.context_blocked_reasons)
    ? result.context_blocked_reasons
    : [];

  return blockedReasons.length > 0;
}

function hasTopicHit(result) {
  return toNumber(result.context_topic_hits) > 0;
}

function hasSpecificHit(result) {
  return toNumber(result.context_specific_hits) > 0;
}

function hasPersonHit(result) {
  return toNumber(result.context_person_hits) > 0;
}

function isPrimaryTopicResult(result, originalTopic) {
  const tier = getResultTier(result);

  if (tier === 3) return true;

  if (isTrue(result.context_primary_topic_match)) return true;

  if (isGeneralTopic(originalTopic)) {
    return tier >= 1 || hasSpecificHit(result) || hasPersonHit(result);
  }

  const resultTopics = getResultTopics(result);

  if (resultTopics.includes(originalTopic)) return true;

  if (hasTopicHit(result)) return true;

  return false;
}

function isSecondaryTopicResult(result) {
  const tier = getResultTier(result);

  if (tier === 2) return true;

  return isTrue(result.context_secondary_topic_match);
}

function isEntityOnlyResult(result) {
  const tier = getResultTier(result);

  return tier === 1;
}

function isStrongResult(result) {
  if (hasLowValueFormat(result)) return false;

  const score = getResultScore(result);

  return score >= MIN_STRONG_SCORE;
}

function isStrongPrimaryResult(result, originalTopic) {
  return (
    isPrimaryTopicResult(result, originalTopic) &&
    isStrongResult(result)
  );
}

function getDateTimestamp(value) {
  const raw = clean(value);
  if (!raw) return 0;

  const timestamp = new Date(raw).getTime();

  return Number.isFinite(timestamp) ? timestamp : 0;
}

function getAgeDays(value) {
  const timestamp = getDateTimestamp(value);
  if (!timestamp) return null;

  return Math.max(0, Math.floor((Date.now() - timestamp) / (1000 * 60 * 60 * 24)));
}

function isContextReadyFalse(j) {
  const values = [
    j.context_ready_for_article_generation,
    j.context_minimum_article_viability,
    j.external_context_ready,
    j.external_context_minimum_article_viability,
  ];

  return values.some(isFalse);
}

function getStatus(j, results) {
  return clean(j.schalketotal_context_status || (results.length ? 'found' : ''));
}

function buildCheckedResults(results, originalTopic) {
  return results.map(result => {
    const score = getResultScore(result);
    const tier = getResultTier(result);
    const primary = isPrimaryTopicResult(result, originalTopic);
    const secondary = isSecondaryTopicResult(result);
    const strong = isStrongResult(result);
    const strongPrimary = isStrongPrimaryResult(result, originalTopic);

    return {
      id: clean(result.id),
      title: clean(result.title),
      date: clean(result.date),
      score,
      tier,
      primary_topic_match: primary,
      secondary_topic_match: secondary,
      entity_only_match: isEntityOnlyResult(result),
      strong_match: strong,
      strong_primary_match: strongPrimary,
      low_value_format: clean(result.context_low_value_format),
      result_topics: getResultTopics(result),
      topic_hits: toNumber(result.context_topic_hits),
      specific_hits: toNumber(result.context_specific_hits),
      person_hits: toNumber(result.context_person_hits),
      age_days: getAgeDays(result.date || result.modified),
    };
  });
}

const output = [];

for (const item of $input.all()) {
  const j = item.json || {};

  const results = getResultArray(j);
  const internalStatus = getStatus(j, results);
  const internalCount = toNumber(j.schalketotal_context_results_count || results.length);

  const xSource = isXSource(j);
  const originalTopic = getOriginalTopic(j, results);

  const scores = results.map(getResultScore);
  const bestScore = scores.length ? Math.max(...scores) : 0;

  const validResults = results.filter(result => !hasLowValueFormat(result));

  const primaryResults = validResults.filter(result =>
    isPrimaryTopicResult(result, originalTopic)
  );

  const secondaryResults = validResults.filter(result =>
    isSecondaryTopicResult(result)
  );

  const entityOnlyResults = validResults.filter(result =>
    isEntityOnlyResult(result)
  );

  const strongResults = validResults.filter(result =>
    isStrongResult(result)
  );

  const strongPrimaryResults = validResults.filter(result =>
    isStrongPrimaryResult(result, originalTopic)
  );

  const latestInternalTimestamp = validResults.length
    ? Math.max(...validResults.map(result => getDateTimestamp(result.date || result.modified)))
    : 0;

  const latestInternalAgeDays = latestInternalTimestamp
    ? Math.max(0, Math.floor((Date.now() - latestInternalTimestamp) / (1000 * 60 * 60 * 24)))
    : null;

  let needsExternalContext = false;
  const reasons = [];

  if (internalStatus === 'no_relevant_internal_context') {
    needsExternalContext = true;
    reasons.push('no_relevant_internal_context');
  }

  if (internalCount === 0 || results.length === 0) {
    needsExternalContext = true;
    reasons.push('zero_internal_results');
  }

  if (validResults.length === 0 && results.length > 0) {
    needsExternalContext = true;
    reasons.push('only_low_value_internal_results');
  }

  if (bestScore > 0 && bestScore < MIN_ACCEPTABLE_SCORE) {
    needsExternalContext = true;
    reasons.push('weak_best_internal_score');
  }

  if (!isGeneralTopic(originalTopic) && primaryResults.length === 0) {
    needsExternalContext = true;
    reasons.push('no_primary_topic_internal_context');
  }

  if (internalCount === 1 && primaryResults.length < 1) {
    needsExternalContext = true;
    reasons.push('single_internal_result_without_primary_topic');
  }

  if (xSource && strongPrimaryResults.length === 0) {
    needsExternalContext = true;
    reasons.push('x_source_without_strong_primary_internal_context');
  }

  if (xSource && primaryResults.length < MIN_X_PRIMARY_RESULTS) {
    needsExternalContext = true;
    reasons.push('x_source_too_few_primary_internal_results');
  }

  if (!xSource && !isGeneralTopic(originalTopic) && primaryResults.length < MIN_DEFAULT_PRIMARY_RESULTS) {
    needsExternalContext = true;
    reasons.push('too_few_primary_internal_results');
  }

  if (xSource && isContextReadyFalse(j)) {
    needsExternalContext = true;
    reasons.push('x_source_context_not_article_viable');
  }

  const internalContextSufficient =
    internalStatus !== 'no_relevant_internal_context' &&
    internalCount > 0 &&
    validResults.length > 0 &&
    bestScore >= MIN_ACCEPTABLE_SCORE &&
    (
      isGeneralTopic(originalTopic)
        ? strongResults.length > 0 || primaryResults.length > 0
        : primaryResults.length >= MIN_DEFAULT_PRIMARY_RESULTS
    ) &&
    (
      xSource
        ? strongPrimaryResults.length >= 1 && primaryResults.length >= MIN_X_PRIMARY_RESULTS
        : true
    );

  const hardExternalReasons = reasons.filter(reason =>
    [
      'no_relevant_internal_context',
      'zero_internal_results',
      'only_low_value_internal_results',
      'no_primary_topic_internal_context',
      'single_internal_result_without_primary_topic',
      'x_source_without_strong_primary_internal_context',
      'x_source_too_few_primary_internal_results',
      'x_source_context_not_article_viable',
      'too_few_primary_internal_results',
    ].includes(reason)
  );

  if (internalContextSufficient && hardExternalReasons.length === 0) {
    needsExternalContext = false;
    reasons.push('internal_context_sufficient');
  }

  if (!needsExternalContext && !internalContextSufficient) {
    needsExternalContext = true;
    reasons.push('internal_context_not_sufficient');
  }

  output.push({
    json: {
      ...j,

      external_context_needed: needsExternalContext,
      external_context_reason: unique(reasons).join(', '),

      internal_context_evaluation: {
        is_x_source: xSource,

        original_topic: originalTopic,
        internal_status: internalStatus,
        internal_count: internalCount,
        valid_internal_results: validResults.length,

        best_score: bestScore,

        primary_results: primaryResults.length,
        secondary_results: secondaryResults.length,
        entity_only_results: entityOnlyResults.length,

        strong_results: strongResults.length,
        strong_primary_results: strongPrimaryResults.length,

        latest_internal_age_days: latestInternalAgeDays,

        min_acceptable_score: MIN_ACCEPTABLE_SCORE,
        min_strong_score: MIN_STRONG_SCORE,
        min_x_primary_results: MIN_X_PRIMARY_RESULTS,
        min_default_primary_results: MIN_DEFAULT_PRIMARY_RESULTS,

        internal_context_sufficient: internalContextSufficient,
        external_context_needed: needsExternalContext,
        reasons: unique(reasons),

        checked_results: buildCheckedResults(results, originalTopic),
      },
    },
  });
}

return output;

// Prepare External Context Search
// Baut eine externe Websuchanfrage, wenn der interne SCHALKETOTAL-Kontext nicht reicht.
//
// Ziel:
// - Wenn SCHALKETOTAL intern nichts Passendes findet, wird extern gezielt gesucht.
// - Die bereits vorbereitete interne Kontext-Query wird bevorzugt genutzt.
// - Keine generischen S04-only-Suchen.
// - Keine Müllbegriffe wie July, legt, Danach, Priority.
// - Bei Kalender-/Sommerfahrplan-Themen: FC S04 + konkrete Thema-Keywords.
// - Bei Personen-/Transfer-/Vertrags-/Verletzungsfällen: Person + FC S04 + Thema.
// - DFB-/Strafen-/Verspätungsfälle behalten Speziallogik.
// - Provider ist Apify Google Search.

function clean(value) {
  return String(value ?? '').trim();
}

function stripAccents(value) {
  return clean(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalize(value) {
  return stripAccents(value)
    .toLowerCase()
    .replace(/&amp;/g, '&')
    .replace(/[„“"‚‘’'`´]/g, '')
    .replace(/[^\p{L}\p{N}\s%.€-]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeLoose(value) {
  return normalize(value)
    .replace(/-/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function dedupe(values) {
  const out = [];
  const seen = new Set();

  for (const value of values) {
    const v = clean(value);
    if (!v) continue;

    const key = normalizeLoose(v);
    if (!key || seen.has(key)) continue;

    seen.add(key);
    out.push(v);
  }

  return out;
}

function containsAny(text, terms) {
  const n = normalizeLoose(text);
  return terms.some(term => n.includes(normalizeLoose(term)));
}

