  if (!raw) return '';

  const match = raw.match(/Original Title:\s*([\s\S]*?)(?:\n\s*---|\n\s*✍️|$)/i);

  if (match && clean(match[1])) {
    return clean(match[1]);
  }

  return raw.slice(0, 240);
}

function getFullSignalText(j) {
