function extractCapitalizedNames(text) {
  const value = clean(text);

  if (!value) return [];

  const words = value
    .replace(/[-–—]/g, ' ')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .split(/\s+/)
    .map(clean)
    .filter(Boolean);

  const names = [];

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    const next = words[i + 1];

    if (!/^[A-ZÄÖÜ][a-zäöüß]{2,}$/.test(word)) continue;
    if (isGenericTerm(word)) continue;
    if (normalizeLoose(word) === 'euro') continue;

    if (
      next &&
      /^[A-ZÄÖÜ][a-zäöüß]{2,}$/.test(next) &&
      !isGenericTerm(next) &&
      normalizeLoose(next) !== 'euro'
    ) {
      names.push(`${word} ${next}`);
      names.push(next);
    } else {
      names.push(word);
    }
  }

  return dedupe(names);
}

function extractEntityTerms(j) {
  const terms = [];

  if (Array.isArray(j.context_entities)) {
    for (const entity of j.context_entities) {
      const e = clean(entity);
      if (!e || isGenericTerm(e)) continue;

      const parts = e
        .replace(/[-–—]/g, ' ')
        .split(/\s+/)
        .map(clean)
        .filter(Boolean)
        .filter(part => !isGenericTerm(part));

      if (parts.length) {
        terms.push(parts.join(' '));

        if (parts.length > 1) {
          terms.push(parts[parts.length - 1]);
        }
      }
    }
  }

  for (const value of [j.context_main_entity]) {
    const v = clean(value);
    if (!v || isGenericTerm(v)) continue;
    terms.push(v);
  }

  return dedupe(terms);
}

function extractKnownClubs(text) {
  const value = clean(text);

  const clubs = [
    'FC S04',
    'S04',
    'Union Berlin',
    'Eintracht Frankfurt',
    'Frankfurt',
    'Liverpool',
    'FC Liverpool',
    'Parma',
    'Real Madrid',
    'Barcelona',
    'FC Barcelona',
    'Chelsea',
    'Arsenal',
    'Manchester United',
    'Manchester City',
    'Tottenham',
    'Tottenham Hotspur',
    'Newcastle',
