    'Inter',
    'Milan',
    'Dortmund',
    'Borussia Dortmund',
    'Leverkusen',
    'Stuttgart',
    'VfB Stuttgart',
    'RB Leipzig',
    'Leipzig',
    'Aston Villa',
    'Wehen Wiesbaden',
  ];

  const found = [];

  for (const club of clubs) {
    const escaped = club.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`(^|[^\\p{L}\\p{N}])${escaped}([^\\p{L}\\p{N}]|$)`, 'iu');

    if (regex.test(value)) {
      found.push(club);
    }
  }

  const normalized = found.map(club => {
    if (club === 'Frankfurt' && containsAny(value, ['Eintracht'])) {
      return 'Eintracht Frankfurt';
    }

    if (club === 'S04') {
      return 'FC S04';
    }

    if (club === 'Dortmund') {
      return 'Borussia Dortmund';
    }

    if (club === 'Leipzig') {
      return 'RB Leipzig';
    }

    if (club === 'Stuttgart') {
      return 'VfB Stuttgart';
    }

    if (club === 'Newcastle') {
      return 'Newcastle United';
    }

    if (club === 'Barcelona') {
      return 'FC Barcelona';
    }

    return club;
  });

  return dedupe(normalized);
}

function extractMoneyAmounts(text) {
  const value = clean(text);
  const amounts = [];

  const regex = /(\d{1,3}(?:[.\s]\d{3})+|\d+)\s*(?:euro|eur|€)/giu;

  for (const match of value.matchAll(regex)) {
    const number = clean(match[1]).replace(/[^\d]/g, '');

    if (!number) continue;

    amounts.push(`${number} Euro`);
  }

  return dedupe(amounts);
}

function detectDfbPenaltyCase(text) {
  const n = normalizeLoose(text);

  const hasDfb = n.includes('dfb') || n.includes('sportgericht');

  const hasPenalty =
    n.includes('strafe') ||
    n.includes('strafen') ||
    n.includes('geldstrafe') ||
    n.includes('geldstrafen') ||
    n.includes('bestraft') ||
    n.includes('bestrafung') ||
    n.includes('sanktion') ||
    n.includes('sanktionen');

  const hasDelay =
    n.includes('verspatung') ||
    n.includes('verspaetung') ||
    n.includes('verspätung') ||
    n.includes('verspatete') ||
    n.includes('verspätete') ||
    n.includes('zu spat') ||
    n.includes('zu spät');

  return hasDfb && (hasPenalty || hasDelay);
}

function getDfbPenaltyTopics(text) {
  const n = normalizeLoose(text);
  const topics = [];

  if (
    n.includes('strafe') ||
    n.includes('strafen') ||
    n.includes('geldstrafe') ||
    n.includes('geldstrafen') ||
    n.includes('bestraft') ||
    n.includes('bestrafung') ||
    n.includes('sanktion')
  ) {
    topics.push('Strafe');
  }

  if (
    n.includes('verspatung') ||
    n.includes('verspaetung') ||
    n.includes('verspätung') ||
    n.includes('verspatete') ||
    n.includes('verspätete') ||
    n.includes('zu spat') ||
    n.includes('zu spät')
  ) {
    topics.push('Verspätung');
  }

  return dedupe(topics);
}

function detectTopicBucket(j, text) {
  const existing = normalizeLoose(j.context_schalketotal_topic_bucket);
  if (existing && existing !== 'general') return existing;

  const n = normalizeLoose(text);

  if (
    n.includes('sommerfahrplan') ||
    n.includes('summer schedule') ||
    n.includes('testspiel') ||
    n.includes('testspiele') ||
    n.includes('friendly') ||
    n.includes('friendlies') ||
    n.includes('trainingsstart') ||
    n.includes('start of training') ||
    n.includes('saisonvorbereitung') ||
    n.includes('vorbereitung') ||
    n.includes('asien tour') ||
    n.includes('asientour') ||
    n.includes('asien reise') ||
    n.includes('asia tour') ||
    n.includes('trainingslager') ||
    n.includes('training camp')
  ) {
    return 'schedule_calendar';
  }

  if (
    n.includes('transfer') ||
    n.includes('wechsel') ||
    n.includes('leihe') ||
    n.includes('kaufoption') ||
    n.includes('kaufpflicht') ||
    n.includes('ablöse') ||
    n.includes('ablose') ||
    n.includes('verpflichtung') ||
    n.includes('neuzugang') ||
    n.includes('abgang')
  ) {
    return 'transfer';
  }

  if (
    n.includes('vertrag') ||
    n.includes('vertrags') ||
    n.includes('verlängerung') ||
    n.includes('verlaengerung') ||
    n.includes('ausstiegsklausel')
  ) {
    return 'contract';
  }

  if (
    n.includes('verletzung') ||
    n.includes('verletzt') ||
    n.includes('ausfall') ||
    n.includes('comeback') ||
    n.includes('reha')
  ) {
    return 'injury';
  }

  if (
    n.includes('interview') ||
    n.includes('aussage') ||
    n.includes('statement') ||
    n.includes('erklart') ||
    n.includes('erklärt') ||
    n.includes('stellt klar') ||
    n.includes('lobt') ||
    n.includes('kritisiert')
  ) {
    return 'statement';
  }

  if (
    n.includes('supercup') ||
    n.includes('dfb pokal') ||
    n.includes('dfb-pokal') ||
    n.includes('champions league') ||
    n.includes('bundesliga')
  ) {
    return 'match_competition';
  }

  return 'general';
}

