    'strafe',
    'strafen',
    'geldstrafe',
    'geldstrafen',
    'sanktion',
    'verspätung',
    'verspaetung',
    'verspatung',

    'transfer',
    'wechsel',
    'vertrag',
    'verletzung',
    'karriereende',
    'abschied',
    'kader',
    'trainer',
    'leihe',
    'comeback',
    'interesse',
    'gerücht',
    'geruecht',
    'zukunft',
    'medizincheck',
    'einigung',
  ];

  const cleanedRawTopics = rawTopics.filter(topic => {
    const t = normalizeLoose(topic);
    if (!t) return false;
    return allowed.some(keyword => t.includes(normalizeLoose(keyword)));
  });

  return dedupe([...fromText, ...cleanedRawTopics]).slice(0, 6);
}

function buildDfbPenaltySearchQuery(j, combinedText) {
  const schalkeRelevant = hasS04Relevance(j);
  const amounts = extractMoneyAmounts(combinedText);
  const clubs = extractKnownClubs(combinedText);

  const otherClubs = clubs.filter(club => {
    const n = normalizeLoose(club);
    return !['schalke', 'schalke'].includes(n);
  });

  const penaltyTopics = getDfbPenaltyTopics(combinedText);

  const queryParts = [
    'DFB',
    schalkeRelevant ? 'FC S04' : 'S04',
    amounts[0] || '',
    ...penaltyTopics,
    ...otherClubs,
  ];

  const query = dedupe(queryParts)
    .filter(Boolean)
    .slice(0, 9)
    .join(' ');

  if (query.split(/\s+/).length >= 4) {
    return query;
  }

  return dedupe([
    'DFB',
    'FC S04',
    'Strafe',
    'Verspätung',
    amounts[0] || '',
  ]).join(' ');
}

function splitQueryTerms(query) {
  return clean(query)
    .split(/\s+/)
    .map(clean)
    .filter(Boolean)
    .filter(term => isUsefulSearchTerm(term));
}

function getInternalPreparedTerms(j) {
  const values = [];

  values.push(...splitQueryTerms(j.context_schalketotal_query_used));
  values.push(...splitQueryTerms(j.context_single_query));

  if (Array.isArray(j.context_search_keywords)) {
    for (const keyword of j.context_search_keywords) {
      if (isUsefulSearchTerm(keyword)) {
        values.push(keyword);
      }
    }
  }

  return dedupe(values);
}

function buildScheduleExternalQuery(j, combinedText) {
  const schalkeRelevant = hasS04Relevance(j);

  const internalTerms = getInternalPreparedTerms(j);

  const preferred = [
    'Sommerfahrplan',
    'Testspiele',
    'Asien-Tour',
    'Trainingsstart',
    'Saisonvorbereitung',
    'Trainingslager',
    'Aston Villa',
    'Wehen Wiesbaden',
    'Tegernsee',
  ];

  const terms = [];

  for (const preferredTerm of preferred) {
    const preferredKey = normalizeLoose(preferredTerm);

    const exists =
      internalTerms.some(term => normalizeLoose(term) === preferredKey) ||
      normalizeLoose(combinedText).includes(preferredKey);

    if (exists) {
      terms.push(preferredTerm);
    }
  }

  const selectedTerms = dedupe(terms).slice(0, 4);

  const queryParts = [
    schalkeRelevant ? 'FC S04' : 'S04',
    ...selectedTerms,
  ];

  const query = dedupe(queryParts)
    .filter(Boolean)
    .join(' ');

  if (selectedTerms.length >= 2) {
    return query;
  }

  // Fallback, falls das Mapping nicht genug erkennt.
  return dedupe([
    schalkeRelevant ? 'FC S04' : 'S04',
    clean(j.context_schalketotal_query_used || j.context_single_query || ''),
  ])
    .filter(Boolean)
    .join(' ');
}

function buildTopicExternalQuery(j, combinedText, topicBucket) {
  const schalkeRelevant = hasS04Relevance(j);

  const nameCandidates = dedupe([
    ...extractCapitalizedNames(combinedText),
    ...extractEntityTerms(j),
  ]).filter(term => !isGenericTerm(term));

  const primaryName =
    nameCandidates.find(term => term.split(/\s+/).length >= 2) ||
    nameCandidates[0] ||
    '';

  const clubs = extractKnownClubs(combinedText);

  const nonS04Club =
    clubs.find(club => !['schalke', 'schalke'].includes(normalizeLoose(club))) ||
    '';

  const topics = getImportantTopics(j, combinedText)
    .filter(topic => !isGenericTerm(topic) || ['DFB', 'Strafe', 'Verspätung'].includes(topic));

  const queryParts = [];

  if (primaryName) {
    queryParts.push(primaryName);
  }

  if (schalkeRelevant) {
    queryParts.push('FC S04');
  } else if (nonS04Club) {
    queryParts.push(nonS04Club);
  }

  queryParts.push(...topics);

  const query = dedupe(queryParts)
    .filter(part => !isGenericTerm(part) || ['FC S04', 'DFB', 'Strafe', 'Verspätung'].includes(part))
    .slice(0, 7)
    .join(' ');

  if (query.split(/\s+/).length >= 3) {
    return query;
  }

  const internalTerms = getInternalPreparedTerms(j);

  if (internalTerms.length) {
    return dedupe([
      schalkeRelevant ? 'FC S04' : '',
      ...internalTerms.slice(0, 4),
    ])
      .filter(Boolean)
      .join(' ');
  }

  return '';
}

function buildSearchQuery(j) {
  const originalCore = extractOriginalCore(j);
  const relevantText = getRelevantText(j);
  const combinedText = [originalCore, relevantText, j.original_text].filter(Boolean).join(' ');
  const fullSignalText = getFullSignalText(j);
  const topicBucket = detectTopicBucket(j, fullSignalText);

  // Spezialfall zuerst:
  // DFB-Strafe / Verspätung / Geldstrafe darf nie zu "Euro FC S04" werden.
  if (detectDfbPenaltyCase(fullSignalText)) {
    return buildDfbPenaltySearchQuery(j, fullSignalText);
  }

  if (topicBucket === 'schedule_calendar') {
    return buildScheduleExternalQuery(j, fullSignalText);
  }

  const topicQuery = buildTopicExternalQuery(j, fullSignalText, topicBucket);

  if (topicQuery) {
    return topicQuery;
  }

  const schalkeRelevant = hasS04Relevance(j);

  if (originalCore) {
    const cleanedCore = originalCore
      .replace(/\[Originalbeschreibung gekürzt\]/gi, '')
      .replace(/\[Kontextprüfung gekürzt[^\]]*\]/gi, '')
      .replace(/\s+/g, ' ')
      .trim();

    return dedupe([
      schalkeRelevant ? 'FC S04' : '',
      cleanedCore.slice(0, 140),
    ])
      .filter(Boolean)
      .join(' ')
      .trim();
  }

  return dedupe([
    schalkeRelevant ? 'FC S04' : '',
    clean(j.context_web_query),
  ])
    .filter(Boolean)
    .join(' ')
    .trim();
}

const output = [];

for (const item of $input.all()) {
  const j = item.json || {};

  const relevantText = getRelevantText(j);
  const originalCore = extractOriginalCore(j);
  const fullSignalText = getFullSignalText(j);
  const topicBucket = detectTopicBucket(j, fullSignalText);
  const query = buildSearchQuery(j);

  output.push({
    json: {
      ...j,

      external_context_search_query: query,
      external_context_search_status: query ? 'ready' : 'missing_query',
      external_context_provider: 'apify_google_search',
      external_context_max_results: 5,

      external_context_search_debug: {
        schalke_relevant: hasS04Relevance(j),
        topic_bucket: topicBucket,
        original_core: originalCore,
        relevant_text: relevantText,

        internal_context_results_count: j.schalketotal_context_results_count || 0,
        internal_context_status: j.schalketotal_context_status || '',
        internal_query_used: clean(j.context_schalketotal_query_used || ''),
        internal_single_query: clean(j.context_single_query || ''),
        internal_search_keywords: Array.isArray(j.context_search_keywords)
          ? j.context_search_keywords
          : [],

        detected_dfb_penalty_case: detectDfbPenaltyCase(fullSignalText),
        detected_money_amounts: extractMoneyAmounts(fullSignalText),
        detected_dfb_penalty_topics: getDfbPenaltyTopics(fullSignalText),
        detected_names: dedupe([
          ...extractCapitalizedNames([originalCore, relevantText].join(' ')),
          ...extractEntityTerms(j),
        ]),
        detected_clubs: extractKnownClubs(fullSignalText),
        topics: getImportantTopics(j, fullSignalText),

        old_context_web_query: clean(j.context_web_query),
        external_context_needed: j.external_context_needed,
        external_context_reason: j.external_context_reason,
        final_query: query,
      },
    },
  });
}

return output;

// Normalize External Context Results
// Normalisiert die Ergebnisse aus "Run Apify External Search".
//
// Ziel:
// - Apify/Google-Suchergebnisse in stabile Workflow-Felder überführen
// - seriöse Medienquellen bevorzugen
// - Google-Translate-URLs auf echte Zielquellen dekodieren
// - translate.google.com niemals als Quelle übernehmen
// - Social/Foren/Statistikseiten abwerten oder blocken
// - maximal 5 brauchbare externe Kontextquellen speichern
// - ursprüngliche Workflow-Daten aus "Prepare External Context Search" erhalten
//
// Wichtig:
// Externe Snippets sind nur Kontextsignale.
// Der spätere Artikel darf daraus keine harten Fakten machen,
// wenn sie nicht sauber durch Quelle/Snippet belegt sind.

function clean(value) {
  return String(value ?? '').trim();
}

function stripHtml(value) {
  return clean(value)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&hellip;/g, '...')
    .replace(/&#8211;/g, '–')
    .replace(/&#8212;/g, '—')
    .replace(/&#8217;/g, '’')
    .replace(/&#8222;/g, '„')
    .replace(/&#8220;/g, '“')
    .replace(/&#8221;/g, '“')
    .replace(/\s+/g, ' ')
    .trim();
}

function stripAccents(value) {
  return clean(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalize(value) {
  return stripAccents(stripHtml(value))
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s.-]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function safeDecode(value) {
  try {
    return decodeURIComponent(value);
  } catch (error) {
    return value;
  }
}

function getOriginalItems() {
  try {
    return $('Prepare External Context Search').all().map(item => item.json || {});
  } catch (error) {
    return [];
  }
}

function getPairedIndex(item) {
  const paired = item.pairedItem;

  if (!paired) return null;

  if (typeof paired.item === 'number') {
    return paired.item;
  }

  if (Array.isArray(paired) && paired.length && typeof paired[0].item === 'number') {
    return paired[0].item;
  }

  return null;
}

function getStableKey(j) {
  return (
    clean(j.workflow_item_id) ||
    clean(j.trello_card_id) ||
    clean(j.context_source_url) ||
    clean(j.original_url) ||
    clean(j.generated_title) ||
    clean(j.title) ||
    clean(j.external_context_search_query)
  );
}

function decodeGoogleRedirect(url) {
  const value = clean(url);

  if (!value) return '';

  const qMatch = value.match(/[?&]q=([^&]+)/i);
  if (qMatch && qMatch[1]) {
    return safeDecode(qMatch[1]);
  }

  const urlMatch = value.match(/[?&]url=([^&]+)/i);
  if (urlMatch && urlMatch[1]) {
    return safeDecode(urlMatch[1]);
  }

  return value;
}

function decodeGoogleTranslateUrl(url) {
  const value = clean(url);

  if (!value) return '';

  // translate.google.com/translate?u=https://...
  if (!/translate\.google\./i.test(value)) {
    return value;
  }

  const uMatch = value.match(/[?&]u=([^&]+)/i);
  if (uMatch && uMatch[1]) {
    return safeDecode(uMatch[1]);
  }

  return value;
}

function normalizeUrl(url) {
  let value = clean(url);

  if (!value) return '';

  value = decodeGoogleRedirect(value);
  value = decodeGoogleTranslateUrl(value);

  if (value.startsWith('//')) {
    value = `https:${value}`;
  }

  if (value.startsWith('/url?')) {
    value = decodeGoogleRedirect(value);
    value = decodeGoogleTranslateUrl(value);
  }

  return value;
}

function getHostname(url) {
  const value = normalizeUrl(url);

  if (!value) return '';

  try {
    return new URL(value).hostname.toLowerCase().replace(/^www\./, '');
  } catch (error) {
    const match = value.match(/^https?:\/\/([^/?#]+)/i);
    if (match && match[1]) {
      return match[1].toLowerCase().replace(/^www\./, '');
    }
  }

  return '';
}

function cleanUrlForDedup(url) {
  const value = normalizeUrl(url);

  if (!value) return '';

  try {
    const parsed = new URL(value);

    parsed.hash = '';

    const removableParams = [
      'utm_source',
      'utm_medium',
      'utm_campaign',
      'utm_term',
      'utm_content',
      'fbclid',
      'gclid',
      'mc_cid',
      'mc_eid',
    ];

    for (const param of removableParams) {
      parsed.searchParams.delete(param);
    }

    return parsed.toString().replace(/\/$/, '');
  } catch (error) {
    return value.split('#')[0].replace(/\/$/, '');
  }
}

function getDomainLabel(hostname) {
  const host = clean(hostname).toLowerCase().replace(/^www\./, '');

  if (!host) return '';

  const known = [
    ['sportbild.bild.de', 'SPORT BILD'],
    ['kicker.de', 'Kicker'],
    ['bild.de', 'BILD'],
    ['sport.sky.de', 'Sky Sport'],
    ['sky.de', 'Sky'],
    ['sport1.de', 'SPORT1'],
    ['spox.com', 'SPOX'],
    ['transfermarkt.de', 'Transfermarkt'],
    ['sueddeutsche.de', 'Süddeutsche Zeitung'],
    ['spiegel.de', 'Spiegel'],
    ['faz.net', 'FAZ'],
    ['welt.de', 'Welt'],
    ['tz.de', 'tz'],
    ['merkur.de', 'Merkur'],
    ['abendzeitung-gelsenkirchen.de', 'Abendzeitung'],
    ['ran.de', 'ran'],
    ['sport.de', 'sport.de'],
    ['liverpoolfc.com', 'FC Liverpool'],
    ['schalke.com', 'FC S04'],
    ['uefa.com', 'UEFA'],
    ['bundesliga.com', 'Bundesliga'],
    ['theathletic.com', 'The Athletic'],
    ['skysports.com', 'Sky Sports'],
    ['espn.com', 'ESPN'],
    ['bbc.com', 'BBC'],
    ['bbc.co.uk', 'BBC'],
    ['theguardian.com', 'The Guardian'],
    ['football-italia.net', 'Football Italia'],
    ['fabrizioromano.com', 'Fabrizio Romano'],
    ['wikipedia.org', 'Wikipedia'],
    ['sofascore.com', 'Sofascore'],
    ['flashscore.com', 'Flashscore'],
    ['liveticker.com', 'Liveticker'],
  ];

  for (const [domain, label] of known) {
    if (host === domain || host.endsWith(`.${domain}`)) {
      return label;
    }
  }

  return host;
}

function classifySource(hostname, websiteTitle, url) {
  const host = normalize(hostname);
  const website = normalize(websiteTitle);
  const full = `${host} ${website} ${normalize(url)}`;

  if (
    full.includes('translate.google') ||
    full.includes('googleusercontent') ||
    full.includes('google.com/search') ||
    full.includes('google.de/search')
  ) {
    return 'blocked';
  }

  if (
    full.includes('x.com') ||
    full.includes('twitter.com') ||
    full.includes('instagram.com') ||
    full.includes('facebook.com') ||
    full.includes('tiktok.com') ||
    full.includes('youtube.com')
  ) {
    return 'social';
  }

  if (
    full.includes('reddit.com') ||
    full.includes('forum') ||
    full.includes('community')
  ) {
    return 'forum';
  }

  if (
    full.includes('wikipedia.org') ||
    full.includes('wikidata.org')
  ) {
    return 'reference';
  }

  if (
    full.includes('transfermarkt.') ||
    full.includes('sofascore.') ||
    full.includes('flashscore.') ||
    full.includes('liveticker.') ||
    full.includes('soccerway.') ||
    full.includes('worldfootball.net')
  ) {
    return 'database';
  }

  if (
    full.includes('liverpoolfc.com') ||
    full.includes('schalke.com') ||
    full.includes('uefa.com') ||
    full.includes('bundesliga.com')
  ) {
    return 'official';
  }

  if (
    full.includes('kicker.de') ||
    full.includes('bild.de') ||
    full.includes('sportbild.bild.de') ||
    full.includes('sport.sky.de') ||
    full.includes('sky.de') ||
    full.includes('sport1.de') ||
    full.includes('spox.com') ||
    full.includes('sueddeutsche.de') ||
    full.includes('spiegel.de') ||
    full.includes('faz.net') ||
    full.includes('welt.de') ||
    full.includes('tz.de') ||
    full.includes('merkur.de') ||
    full.includes('abendzeitung-gelsenkirchen.de') ||
    full.includes('ran.de') ||
    full.includes('sport.de') ||
    full.includes('theathletic.com') ||
    full.includes('skysports.com') ||
    full.includes('espn.com') ||
    full.includes('bbc.') ||
    full.includes('theguardian.com') ||
    full.includes('football-italia.net')
  ) {
    return 'media';
  }

  return 'other';
}

function isBlockedUrl(url) {
  const normalizedUrl = normalizeUrl(url);
  const host = getHostname(normalizedUrl);

  if (!normalizedUrl) return true;

  if (
    host === 'google.de' ||
    host === 'google.com' ||
    host === 'translate.google.com' ||
    host.startsWith('google.') ||
    host.startsWith('translate.google.')
  ) {
    return true;
  }

  if (normalizedUrl.includes('webcache')) return true;

  return false;
}

function isLowValueSourceType(sourceType) {
  return ['blocked', 'social', 'forum'].includes(clean(sourceType));
}

function scoreExternalResult(result, index, original) {
  const title = stripHtml(result.title);
  const description = stripHtml(result.description);
  const websiteTitle = stripHtml(result.websiteTitle);
  const url = normalizeUrl(result.url);
  const hostname = getHostname(url);
  const sourceType = classifySource(hostname, websiteTitle, url);

  let score = 100;
  const reasons = [];

  const position = Number(result.position || index + 1);

  if (Number.isFinite(position)) {
    score += Math.max(0, 25 - position * 2);
    reasons.push(`google_position_${position}`);
  }

  if (sourceType === 'media') {
    score += 40;
    reasons.push('media_source');
  }

  if (sourceType === 'official') {
    score += 35;
    reasons.push('official_source');
  }

  if (sourceType === 'database') {
    score -= 15;
    reasons.push('database_source');
  }

  if (sourceType === 'reference') {
    score -= 25;
    reasons.push('reference_source');
  }

  if (sourceType === 'forum') {
    score -= 80;
    reasons.push('forum_source');
  }

  if (sourceType === 'social') {
    score -= 90;
    reasons.push('social_source');
  }

  if (sourceType === 'blocked') {
    score -= 200;
    reasons.push('blocked_source');
  }

  const combined = normalize(`${title} ${description}`);

  const query = clean(original.external_context_search_query);
  const queryTerms = query
    .split(/\s+/)
    .map(clean)
    .filter(term => term.length >= 4)
    .slice(0, 8);

  let queryHits = 0;

  for (const term of queryTerms) {
    if (combined.includes(normalize(term))) {
      queryHits++;
    }
  }

  if (queryHits >= 2) {
    score += 20;
    reasons.push('query_terms_match');
  }

  if (queryHits >= 4) {
    score += 20;
    reasons.push('strong_query_match');
  }

  const titleSignals = [
    'transfer',
    'wechsel',
    'vertrag',
    'verpflichtet',
    'einigung',
    'medizincheck',
    'medical',
    'contract',
    'deal',
    'injury',
    'verletzung',
    'abschied',
    'karriereende',
  ];

  for (const signal of titleSignals) {
    if (normalize(title).includes(normalize(signal))) {
      score += 10;
      reasons.push(`title_signal_${signal}`);
    }
  }

  if (!description) {
    score -= 15;
    reasons.push('missing_description');
  }

  if (isBlockedUrl(url)) {
    score -= 200;
    reasons.push('blocked_url');
  }

  return {
    score,
    reasons,
    sourceType,
    hostname,
  };
}

function getOrganicResults(apifyItem) {
  if (Array.isArray(apifyItem.organicResults)) {
    return apifyItem.organicResults;
  }

  if (Array.isArray(apifyItem.organic_results)) {
    return apifyItem.organic_results;
  }

  if (Array.isArray(apifyItem.results)) {
    return apifyItem.results;
  }

  return [];
}

function normalizeOrganicResults(apifyItem, original) {
  const organic = getOrganicResults(apifyItem);

  const aiSources = Array.isArray(apifyItem.aiOverview?.sources)
    ? apifyItem.aiOverview.sources
    : [];

  const peopleAlsoAsk = Array.isArray(apifyItem.peopleAlsoAsk)
    ? apifyItem.peopleAlsoAsk
    : [];

  const raw = [];

  for (const result of organic) {
    raw.push({
      title: stripHtml(result.title),
      websiteTitle: stripHtml(result.websiteTitle || result.source || result.siteName),
      url: normalizeUrl(result.url || result.link),
      original_url_from_search: clean(result.url || result.link),
      displayedUrl: stripHtml(result.displayedUrl || result.displayedLink),
      description: stripHtml(result.description || result.snippet),
      date: clean(result.date),
      position: result.position,
      result_type: 'organic',
    });
  }

  for (const result of aiSources) {
    const normalizedUrl = normalizeUrl(result.url);

    raw.push({
      title: stripHtml(result.title),
      websiteTitle: getDomainLabel(getHostname(normalizedUrl)),
      url: normalizedUrl,
      original_url_from_search: clean(result.url),
      displayedUrl: getHostname(normalizedUrl),
      description: stripHtml(result.description),
      date: clean(result.date),
      position: 50,
      result_type: 'ai_overview_source',
    });
  }

  for (const result of peopleAlsoAsk) {
    if (!result.url) continue;

    const normalizedUrl = normalizeUrl(result.url);

    raw.push({
      title: stripHtml(result.title || result.question),
      websiteTitle: getDomainLabel(getHostname(normalizedUrl)),
      url: normalizedUrl,
      original_url_from_search: clean(result.url),
      displayedUrl: getHostname(normalizedUrl),
      description: stripHtml(result.answer),
      date: clean(result.date),
      position: 60,
      result_type: 'people_also_ask',
    });
  }

  const seenUrls = new Set();
  const normalized = [];
  const rejected = [];

  for (let i = 0; i < raw.length; i++) {
    const result = raw[i];

    const url = normalizeUrl(result.url);
    const hostname = getHostname(url);

    if (!url) {
      rejected.push({
        reason: 'missing_url',
        title: result.title,
        raw_url: result.original_url_from_search || result.url,
      });
      continue;
    }

    if (isBlockedUrl(url)) {
      rejected.push({
        reason: 'blocked_url',
        title: result.title,
        raw_url: result.original_url_from_search || result.url,
        normalized_url: url,
        hostname,
      });
      continue;
    }

    const scoring = scoreExternalResult(
      {
        ...result,
        url,
      },
      i,
      original
    );

    if (isLowValueSourceType(scoring.sourceType)) {
      rejected.push({
        reason: `low_value_source_${scoring.sourceType}`,
        title: result.title,
        raw_url: result.original_url_from_search || result.url,
        normalized_url: url,
        hostname,
      });
      continue;
    }

    const urlKey = cleanUrlForDedup(url);

    if (seenUrls.has(urlKey)) {
      rejected.push({
        reason: 'duplicate_url',
        title: result.title,
        normalized_url: url,
        hostname,
      });
      continue;
    }

    seenUrls.add(urlKey);

    const sourceLabel =
      getDomainLabel(scoring.hostname) ||
      result.websiteTitle ||
      scoring.hostname;

    normalized.push({
      title: result.title,
      url,
      original_url_from_search: result.original_url_from_search,
      domain: scoring.hostname,
      source_name: sourceLabel,
      source_type: scoring.sourceType,
      description: result.description,
      date: result.date,
      google_position: result.position || null,
      result_type: result.result_type,
      external_context_score: scoring.score,
      external_context_score_reasons: scoring.reasons,
    });
  }

  normalized.sort((a, b) => {
    if (b.external_context_score !== a.external_context_score) {
      return b.external_context_score - a.external_context_score;
    }

    return Number(a.google_position || 999) - Number(b.google_position || 999);
  });

  return {
    normalized,
    rejected,
    raw_count: raw.length,
  };
}

function buildExternalContextBlock(results, apifyItem, original) {
  const lines = [];

  lines.push('EXTERNER SUCHKONTEXT');
  lines.push('');
  lines.push('Wichtig: Diese Ergebnisse stammen aus einer externen Websuche.');
  lines.push('Sie dienen nur als zusätzlicher Kontext und müssen vorsichtig verwendet werden.');
  lines.push('Keine Fakten erfinden. Keine Formulierungen kopieren. Quelle nur nennen, wenn sie hier eindeutig erkennbar ist.');
  lines.push('');

  lines.push(`Suchanfrage: ${clean(apifyItem.searchQuery?.term || original.external_context_search_query)}`);
  lines.push('');

  if (!results.length) {
    lines.push('Keine verwertbaren externen Ergebnisse gefunden.');
    return lines.join('\n').trim();
  }

  lines.push('Gefundene externe Quellen:');

  results.forEach((result, index) => {
    lines.push('');
    lines.push(`${index + 1}. ${result.source_name}`);
    lines.push(`Titel: ${result.title}`);

    if (result.date) {
      lines.push(`Datum: ${result.date}`);
    }

    lines.push(`URL: ${result.url}`);

    if (result.description) {
      lines.push(`Snippet: ${result.description}`);
    }

    lines.push(`Quellentyp: ${result.source_type}`);
    lines.push(`Score: ${result.external_context_score}`);
  });

  return lines.join('\n').trim();
}

const inputItems = $input.all();
const originalItems = getOriginalItems();

const output = [];

for (let i = 0; i < inputItems.length; i++) {
  const apifyItem = inputItems[i].json || {};

  let original = originalItems[i] || {};

  const pairedIndex = getPairedIndex(inputItems[i]);

  if (
    pairedIndex !== null &&
    pairedIndex >= 0 &&
    pairedIndex < originalItems.length
  ) {
    original = originalItems[pairedIndex] || original;
  }

  const normalizedPackage = normalizeOrganicResults(apifyItem, original);
  const allResults = normalizedPackage.normalized;
  const rejectedResults = normalizedPackage.rejected;

  const maxResults = Number(original.external_context_max_results || 5);

  let selectedResults = allResults
    .filter(result => result.external_context_score >= 60)
    .slice(0, maxResults);

  // Sicherheitsfallback:
  // Wenn alles knapp unter Score liegt, trotzdem die besten 3 behalten,
  // solange sie nicht blockiert wurden.
  if (!selectedResults.length && allResults.length) {
    selectedResults = allResults.slice(0, Math.min(3, maxResults));
  }

  const externalContextBlock = buildExternalContextBlock(selectedResults, apifyItem, original);

  output.push({
    json: {
      ...original,

      external_context_search_query_used:
        clean(apifyItem.searchQuery?.term) ||
        clean(original.external_context_search_query),

      external_context_results_raw_count: normalizedPackage.raw_count,
      external_context_results_total_normalized: allResults.length,

      external_context_results_count: selectedResults.length,
      external_context_results: selectedResults,

      external_context_status: selectedResults.length ? 'found' : 'no_relevant_external_context',
      external_context_block: externalContextBlock,

      external_context_debug: {
        provider: clean(original.external_context_provider) || 'apify_google_search',
        search_query:
          clean(apifyItem.searchQuery?.term) ||
          clean(original.external_context_search_query),
        apify_error: Boolean(apifyItem['#error']),
        apify_status_code: apifyItem['#debug']?.statusCode || null,
        raw_organic_count: getOrganicResults(apifyItem).length,
        raw_combined_count: normalizedPackage.raw_count,
        normalized_count: allResults.length,
        selected_count: selectedResults.length,
        selected_domains: selectedResults.map(result => result.domain),
        selected_sources: selectedResults.map(result => result.source_name),
        rejected_count: rejectedResults.length,
        rejected_preview: rejectedResults.slice(0, 8),
        stable_key: getStableKey(original),
        google_translate_handling: 'decode_u_parameter_to_original_source_or_block',
      },
    },
  });
}

return output;

// Prepare External Context Review Links
// Baut eine Trello-freundliche Review-Liste für externe Quellen.
//
// Wichtig:
// - Input kommt aus "Normalize External Editorial Context Facts".
// - Dieser Node baut KEIN neues external_context_briefing mehr.
// - Das strukturierte KI-Briefing aus Normalize External Editorial Context Facts bleibt erhalten.
// - context_from_existing_articles wird hier bewusst NICHT gesetzt.
// - Interne SCHALKETOTAL-Felder werden aus dem externen Pfad entfernt.
// - Danach geht es weiter zu "Prepare Unified Context For Article".

function clean(value) {
  return String(value ?? '').trim();
}

function formatDate(value) {
  const raw = clean(value);

  if (!raw) return '';

  const date = new Date(raw);

  if (Number.isNaN(date.getTime())) {
    return raw;
  }

  return new Intl.DateTimeFormat('de-DE', {
    timeZone: 'Europe/Berlin',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(date) + ' Uhr';
}

function asArray(value) {
  if (Array.isArray(value)) {
    return value.map(clean).filter(Boolean);
  }

  if (typeof value === 'string' && value.trim()) {
    return [clean(value)];
  }

  return [];
}

function sanitizeBase(j) {
  const removePrefixes = [
    'schalketotal_',
  ];

  const removeExact = new Set([
    'schalketotal_context_results',
    'schalketotal_context_post_ids',
    'schalketotal_context_status',
    'schalketotal_context_debug',
    'schalketotal_context_results_raw_count',
    'schalketotal_context_results_count',

    'schalketotal_context_article_count',
    'schalketotal_context_articles',
    'schalketotal_latest_context_article',
    'schalketotal_background_context_articles',
    'schalketotal_context_timeline',
    'schalketotal_context_block',
    'schalketotal_context_block_status',

    'internal_context_evaluation',

    'internal_context_briefing',
    'context_from_existing_articles',
    'context_editorial_briefing',

    'context_sources_internal_count',

    'context_latest_facts',
    'context_background_facts',
    'context_timeline',
    'context_uncertain_points',
    'context_safe_article_points',
    'context_length_support_points',
    'context_do_not_claim',
    'context_recommended_article_structure',

    'editorial_context_parse_status',
    'editorial_context_raw_output',
    'editorial_context_facts',

    'context_review_links',
    'context_review_links_status',
  ]);

  const base = {};

  for (const [key, value] of Object.entries(j)) {
    if (removeExact.has(key)) continue;
    if (removePrefixes.some(prefix => key.startsWith(prefix))) continue;

    base[key] = value;
  }

  return base;
}

function buildExternalReviewLinks(j, results) {
  const lines = [];

  lines.push('🌐 Verwendeter externer Kontext');
  lines.push('');

  if (j.external_context_search_query_used || j.external_context_search_query) {
    lines.push(`Suchanfrage: ${clean(j.external_context_search_query_used || j.external_context_search_query)}`);
    lines.push('');
  }

  if (j.external_context_quality) {
    lines.push('Kontextbewertung');
    lines.push(`Qualität: ${clean(j.external_context_quality)}`);
    lines.push(`Artikel tragfähig: ${j.external_context_ready ? 'ja' : 'nein'}`);

    if (j.external_context_minimum_article_viability_reason) {
      lines.push(`Grund: ${clean(j.external_context_minimum_article_viability_reason)}`);
    }

    lines.push('');
  }

  if (j.external_context_main_news_angle) {
    lines.push('Nachrichtenkern');
    lines.push(clean(j.external_context_main_news_angle));
    lines.push('');
  }

  const visibleFacts = asArray(j.external_context_visible_source_facts);
  if (visibleFacts.length) {
    lines.push('Sichtbare Fakten aus externen Treffern');
    visibleFacts.slice(0, 6).forEach(fact => lines.push(`- ${fact}`));
    lines.push('');
  }

  const uncertainPoints = asArray(j.external_context_uncertain_points);
  if (uncertainPoints.length) {
    lines.push('Unsichere / offene Punkte');
    uncertainPoints.slice(0, 5).forEach(point => lines.push(`- ${point}`));
    lines.push('');
  }

  const doNotClaim = asArray(j.external_context_do_not_claim);
  if (doNotClaim.length) {
    lines.push('Nicht behaupten');
    doNotClaim.slice(0, 6).forEach(point => lines.push(`- ${point}`));
    lines.push('');
  }

  if (!results.length) {
    lines.push('Externe Quellen');
    lines.push('Keine verwertbaren externen Quellen gefunden.');
    return lines.join('\n').trim();
  }

  lines.push('Externe Quellen');

  results.forEach((result, index) => {
    const sourceName =
      clean(result.source_name) ||
      clean(result.domain) ||
      'Externe Quelle';

    lines.push('');
    lines.push(`${index + 1}. ${sourceName}`);

    if (result.title) {
      lines.push(clean(result.title));
    }

    if (result.date) {
      lines.push(formatDate(result.date));
    }

    if (result.url) {
      lines.push(clean(result.url));
    }

    if (result.description) {
      lines.push(`Snippet: ${clean(result.description)}`);
    }

    if (result.source_type) {
      lines.push(`Typ: ${clean(result.source_type)}`);
    }

    if (result.external_context_score !== undefined) {
      lines.push(`Score: ${result.external_context_score}`);
    }
  });

  return lines.join('\n').trim();
}

function pickCurrentExternalStatus(j, results) {
  if (j.external_context_current_status_source || j.external_context_current_status_title) {
    return {
      source: clean(j.external_context_current_status_source),
      title: clean(j.external_context_current_status_title),
      date: clean(j.external_context_current_status_date),
    };
  }

  if (!results.length) {
    return {
      source: '',
      title: clean(j.external_context_current_status || ''),
      date: '',
    };
  }

  const preferred =
    results.find(result => ['media', 'official'].includes(clean(result.source_type))) ||
    results[0];

  return {
    source: clean(preferred.url),
    title: clean(preferred.title),
    date: clean(preferred.date),
  };
}

const output = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const base = sanitizeBase(j);

  const results = Array.isArray(j.external_context_results)
    ? j.external_context_results
    : [];

  const reviewLinks = buildExternalReviewLinks(j, results);
  const currentExternalStatus = pickCurrentExternalStatus(j, results);

  const hasExternalResults = results.length > 0;
  const hasExternalBriefing = Boolean(clean(j.external_context_briefing));
  const hasParsedFacts = clean(j.external_editorial_context_parse_status) === 'ok';

  const externalReady =
    Boolean(j.external_context_ready) ||
    (
      hasExternalBriefing &&
      hasExternalResults &&
      ['strong', 'usable'].includes(clean(j.external_context_quality).toLowerCase())
    );

  output.push({
    json: {
      ...base,

      // Externe Roh- und KI-Kontextdaten bleiben erhalten
      external_context_results_count: results.length,
      external_context_results: results,
      external_context_status: hasExternalResults ? 'found' : 'no_relevant_external_context',

      external_editorial_context_parse_status: clean(j.external_editorial_context_parse_status),
      external_editorial_context_raw_output: j.external_editorial_context_raw_output || '',
      external_editorial_context_facts: j.external_editorial_context_facts || {},

      external_context_quality: clean(j.external_context_quality) || (hasExternalResults ? 'usable' : 'weak'),
      external_context_current_status: clean(j.external_context_current_status),
      external_context_main_news_angle: clean(j.external_context_main_news_angle),

      external_context_visible_source_facts: asArray(j.external_context_visible_source_facts),
      external_context_background_facts: asArray(j.external_context_background_facts),
      external_context_source_situation: asArray(j.external_context_source_situation),
      external_context_uncertain_points: asArray(j.external_context_uncertain_points),
      external_context_safe_article_points: asArray(j.external_context_safe_article_points),
      external_context_length_support_points: asArray(j.external_context_length_support_points),
      external_context_source_handling_notes: asArray(j.external_context_source_handling_notes),
      external_context_do_not_claim: asArray(j.external_context_do_not_claim),
      external_context_recommended_article_structure: asArray(j.external_context_recommended_article_structure),

      external_context_minimum_article_viability: Boolean(j.external_context_minimum_article_viability),
      external_context_minimum_article_viability_reason: clean(j.external_context_minimum_article_viability_reason),

      // Wichtig: Wird NICHT neu gebaut, sondern aus Normalize External Editorial Context Facts übernommen.
      external_context_briefing: clean(j.external_context_briefing),

      external_context_ready: externalReady,

      // Review-Felder für Trello / spätere Kontrolle
      external_context_review_links: reviewLinks,
      external_context_review_links_status: reviewLinks ? 'ready' : 'empty',

      // Einheitliches Review-Feld für spätere Nodes
      context_review_links: reviewLinks,
      context_review_links_status: reviewLinks ? 'ready' : 'empty',

      // Saubere Quellenzählung
      context_sources_external_count: results.length,
      context_sources_internal_count: 0,

      // Aktuelle externe Hauptquelle
      external_context_current_status_source: currentExternalStatus.source,
      external_context_current_status_title: currentExternalStatus.title,
      external_context_current_status_date: currentExternalStatus.date,

      combined_context_mode: 'external_only_pending_unified',
      combined_context_status: externalReady ? 'pending_unified' : 'weak',

      external_context_review_debug: {
        source_node_expected: 'Normalize External Editorial Context Facts',
        parsed_facts_available: hasParsedFacts,
        external_briefing_available: hasExternalBriefing,
        external_results_used: results.length,
        external_ready: externalReady,
        removed_schalketotal_fields: true,
        context_from_existing_articles_not_set_here: true,
      },
    },
  });
}

return output;

// Prepare Unified Context For Article
// Vereinheitlicht internen und externen Kontext für die Artikelgenerierung.
//
// Ziel:
// - Interner SCHALKETOTAL-Kontext bleibt sauber intern.
// - Externer Web-Kontext bleibt sauber extern.
// - Der Artikelgenerator bekommt ein einziges finales Briefing:
//   context_editorial_briefing
// - context_from_existing_articles wird nur gesetzt, wenn wirklich interne SCHALKETOTAL-Archivartikel vorhanden sind.
// - Kein Überschreiben von Rohdaten.
// - Kompatibel mit internem Pfad, externem Pfad und später kombiniertem Pfad.

function clean(value) {
  return String(value ?? '').trim();
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function hasInternalContext(j) {
  if (clean(j.internal_context_briefing)) return true;
  if (clean(j.schalketotal_context_block)) return true;
  if (clean(j.context_from_existing_articles) && !clean(j.external_context_briefing)) return true;
  if (Number(j.context_sources_internal_count || 0) > 0) return true;
  if (Array.isArray(j.schalketotal_context_articles) && j.schalketotal_context_articles.length) return true;

  return false;
}

function hasExternalContext(j) {
  if (clean(j.external_context_briefing)) return true;
  if (Array.isArray(j.external_context_results) && j.external_context_results.length) return true;
  if (Number(j.context_sources_external_count || 0) > 0) return true;

  return false;
}

function buildInternalBriefing(j) {
  if (clean(j.internal_context_briefing)) {
    return clean(j.internal_context_briefing);
  }

  // Im internen Pfad kommt dieses Feld aus Normalize Editorial Context Facts.
  // Dort ist es fachlich korrekt, weil es aus bestehenden SCHALKETOTAL-Artikeln stammt.
  if (clean(j.context_from_existing_articles) && !clean(j.external_context_briefing)) {
    return clean(j.context_from_existing_articles);
  }

  if (clean(j.context_editorial_briefing) && !clean(j.external_context_briefing)) {
    return clean(j.context_editorial_briefing);
  }

  if (clean(j.schalketotal_context_block)) {
    return clean(j.schalketotal_context_block);
  }

  return '';
}

function buildExternalBriefing(j) {
  if (clean(j.external_context_briefing)) {
    return clean(j.external_context_briefing);
  }

  return '';
}

function buildCombinedBriefing(j, internalBriefing, externalBriefing) {
  const lines = [];

  lines.push('REDAKTIONELLES GESAMTBRIEFING FÜR ARTIKELGENERIERUNG');
  lines.push('');
  lines.push('Grundregeln:');
  lines.push('- Keine Fakten erfinden.');
  lines.push('- Keine Formulierungen aus Quellen oder Kontextartikeln kopieren.');
  lines.push('- Trello, Workflow, Input und Automatisierung niemals als Quelle nennen.');
  lines.push('- Bei Unsicherheit weich formulieren: offenbar, soll, demnach, laut Bericht.');
  lines.push('- Wenn interne und externe Informationen widersprüchlich sind, keine harte Aussage treffen, sondern redaktionell vorsichtig einordnen.');
  lines.push('');

  if (j.original_url) {
    lines.push(`Ausgangslink / Fundstelle: ${clean(j.original_url)}`);
  }

  if (j.original_title) {
    lines.push(`Originalmeldung: ${clean(j.original_title)}`);
  }

  if (j.generated_social) {
    lines.push(`Redaktionelle Kurzfassung: ${clean(j.generated_social)}`);
  }

  lines.push('');

  if (internalBriefing) {
    lines.push('────────────────────');
    lines.push('INTERNER SCHALKETOTAL-KONTEXT');
    lines.push('────────────────────');
    lines.push(internalBriefing);
    lines.push('');
  }

  if (externalBriefing) {
    lines.push('────────────────────');
    lines.push('EXTERNER WEB-KONTEXT');
    lines.push('────────────────────');
    lines.push(externalBriefing);
    lines.push('');
  }

  if (!internalBriefing && !externalBriefing) {
    lines.push('Kein verwertbarer Kontext vorhanden.');
  }

  lines.push('────────────────────');
  lines.push('ABSCHLIESSENDE REDAKTIONELLE HINWEISE');
  lines.push('────────────────────');

  if (internalBriefing && externalBriefing) {
    lines.push('- Interner SCHALKETOTAL-Kontext dient als Archiv-/Einordnungsebene.');
    lines.push('- Externer Kontext dient nur als ergänzende Quellenlage.');
    lines.push('- Externe Snippets nicht als vollständige Artikel auswerten.');
  } else if (internalBriefing) {
    lines.push('- Der Artikel basiert auf internem SCHALKETOTAL-Kontext.');
    lines.push('- Bei alten Artikeln gilt: neuester interner Kontext schlägt ältere Hintergrundartikel.');
  } else if (externalBriefing) {
    lines.push('- Der Artikel basiert auf externer Web-Suche.');
    lines.push('- Externe Snippets nur vorsichtig verwenden.');
    lines.push('- Keine SCHALKETOTAL-Archivartikel behaupten oder einbauen.');
  }

  lines.push('- Quelle nur nennen, wenn Medium oder Journalist im Input/Kontext eindeutig erkennbar ist.');

  return lines.join('\n').trim();
}

function buildUnifiedReviewLinks(j) {
  const parts = [];

  const internalReview = clean(j.internal_context_review_links || j.context_review_links_internal);
  const externalReview = clean(j.external_context_review_links);

  // Im internen Pfad heißt es bisher context_review_links.
  // Das übernehmen wir nur als intern, wenn kein external_context_review_links existiert.
  const legacyReview = clean(j.context_review_links);

  if (internalReview) {
    parts.push(internalReview);
  } else if (legacyReview && !externalReview) {
    parts.push(legacyReview);
  }

  if (externalReview) {
    parts.push(externalReview);
  }

  return parts.join('\n\n────────────────────\n\n').trim();
}

function pickCurrentStatus(j, hasInternal, hasExternal) {
  if (hasInternal && clean(j.context_current_status_source)) {
    return {
      source: clean(j.context_current_status_source),
      title: clean(j.context_current_status_title),
      date: clean(j.context_current_status_date),
    };
  }

  if (hasExternal && clean(j.external_context_current_status_source)) {
    return {
      source: clean(j.external_context_current_status_source),
      title: clean(j.external_context_current_status_title),
      date: clean(j.external_context_current_status_date),
    };
  }

  return {
    source: clean(j.context_current_status_source || j.external_context_current_status_source),
    title: clean(j.context_current_status_title || j.external_context_current_status_title),
    date: clean(j.context_current_status_date || j.external_context_current_status_date),
  };
}

const output = [];

for (const item of $input.all()) {
  const j = item.json || {};

  const internalAvailable = hasInternalContext(j);
  const externalAvailable = hasExternalContext(j);

  const internalBriefing = buildInternalBriefing(j);
  const externalBriefing = buildExternalBriefing(j);
  const combinedBriefing = buildCombinedBriefing(j, internalBriefing, externalBriefing);

  let mode = 'none';

  if (internalAvailable && externalAvailable) {
    mode = 'internal_and_external';
  } else if (internalAvailable) {
    mode = 'internal_only';
  } else if (externalAvailable) {
    mode = 'external_only';
  }

  const ready = internalAvailable || externalAvailable;

  const reviewLinks = buildUnifiedReviewLinks(j);
  const currentStatus = pickCurrentStatus(j, internalAvailable, externalAvailable);

  const internalCount =
    Number(j.context_sources_internal_count || 0) ||
    asArray(j.schalketotal_context_articles).length ||
    Number(j.schalketotal_context_article_count || 0) ||
    0;

  const externalCount =
    Number(j.context_sources_external_count || 0) ||
    asArray(j.external_context_results).length ||
    0;

  output.push({
    json: {
      ...j,

      internal_context_available: internalAvailable,
      external_context_available: externalAvailable,

      internal_context_briefing: internalBriefing,
      external_context_briefing: externalBriefing,
      combined_context_briefing: combinedBriefing,

      // Das ist ab jetzt das zentrale Feld für Artikelgenerierung.
      context_editorial_briefing: combinedBriefing,

      // Dieses Feld bleibt nur für echten internen Archivkontext gesetzt.
      context_from_existing_articles: internalAvailable ? internalBriefing : '',

      context_quality: ready ? 'usable' : 'weak',
      context_ready_for_article_generation: ready,
      context_minimum_article_viability: ready,
      context_minimum_article_viability_reason: ready
        ? `Kontext verfügbar: ${mode}. Artikelgenerierung möglich.`
        : 'Kein verwertbarer interner oder externer Kontext vorhanden.',

      context_sources_internal_count: internalCount,
      context_sources_external_count: externalCount,

      context_current_status_source: currentStatus.source,
      context_current_status_title: currentStatus.title,
      context_current_status_date: currentStatus.date,

      context_review_links: reviewLinks,
      context_review_links_status: reviewLinks ? 'ready' : 'empty',

      combined_context_mode: mode,
      combined_context_status: ready ? 'ready' : 'weak',

      unified_context_debug: {
        mode,
        internal_available: internalAvailable,
        external_available: externalAvailable,
        internal_briefing_length: internalBriefing.length,
        external_briefing_length: externalBriefing.length,
        combined_briefing_length: combinedBriefing.length,
        context_from_existing_articles_set: Boolean(internalAvailable && internalBriefing),
        context_editorial_briefing_set: Boolean(combinedBriefing),
      },
    },
  });
}

return output;

// Normalize External Editorial Context Facts
// Parst den JSON-Output aus "Extract External Editorial Context Facts"
// und baut daraus stabile Felder für die spätere Zusammenführung.
//
// Wichtig:
// - Originaldaten aus "Normalize External Context Results" bleiben erhalten
// - KI-Briefing wird separat gespeichert
// - Kein interner SCHALKETOTAL-Kontext wird gesetzt
// - context_from_existing_articles wird hier bewusst NICHT gesetzt

function clean(value) {
  return String(value ?? '').trim();
}

function tryGetNodeJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (error) {
    return {};
  }
}

function extractTextFromOpenAiOutput(j) {
  if (typeof j === 'string') return j;

  if (typeof j.text === 'string') return j.text;
  if (typeof j.output_text === 'string') return j.output_text;
  if (typeof j.content === 'string') return j.content;
  if (typeof j.message === 'string') return j.message;
  if (typeof j.response === 'string') return j.response;

  if (Array.isArray(j.output)) {
    for (const out of j.output) {
      if (Array.isArray(out.content)) {
        for (const content of out.content) {
          if (typeof content.text === 'string') {
            return content.text;
          }
        }
      }
    }
  }

  if (Array.isArray(j.content)) {
    for (const content of j.content) {
      if (typeof content.text === 'string') {
        return content.text;
      }

      if (typeof content === 'string') {
        return content;
      }
    }
  }

  if (j.choices?.[0]?.message?.content) {
    return j.choices[0].message.content;
  }

  return '';
}

function parseJsonLoose(value) {
  let text = clean(value);

  if (!text) return null;

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    return JSON.parse(text);
  } catch (error) {}

  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace >= 0 && lastBrace > firstBrace) {
    const jsonText = text.slice(firstBrace, lastBrace + 1);

    try {
      return JSON.parse(jsonText);
    } catch (error) {}
  }

  return null;
}

function asArray(value) {
  if (Array.isArray(value)) {
    return value.map(clean).filter(Boolean);
  }

  if (typeof value === 'string' && value.trim()) {
    return [clean(value)];
  }

  return [];
}

function buildExternalBriefing(facts, original) {
  const lines = [];

  lines.push('REDAKTIONELLES BRIEFING AUS EXTERNER WEB-SUCHE');
  lines.push('');
  lines.push('Wichtig: Dieser Kontext wurde aus externen Suchergebnissen, Titeln und Snippets abgeleitet.');
  lines.push('Er ist kein SCHALKETOTAL-Archivkontext und kein vollständig gelesener Volltext.');
  lines.push('Keine Formulierungen kopieren. Keine Fakten ergänzen, die nicht im Input sichtbar waren.');
  lines.push('Trello, Workflow, Input, Automatisierung, Google und Google Translate niemals als Quelle nennen.');
  lines.push('');

  if (facts.external_context_quality) {
    lines.push(`Kontextqualität: ${clean(facts.external_context_quality)}`);
  }

  if (facts.current_status) {
    lines.push('');
    lines.push('Aktuell erkennbarer Stand:');
    lines.push(clean(facts.current_status));
  }

  if (facts.main_news_angle) {
    lines.push('');
    lines.push('Nachrichtenkern:');
    lines.push(clean(facts.main_news_angle));
  }

  const visibleFacts = asArray(facts.visible_source_facts);
  if (visibleFacts.length) {
    lines.push('');
    lines.push('Sichtbare Fakten aus externen Titeln/Snippets:');
    visibleFacts.forEach(fact => lines.push(`- ${fact}`));
  }

  const background = asArray(facts.background_facts);
  if (background.length) {
    lines.push('');
    lines.push('Hintergrund aus sichtbaren externen Treffern:');
    background.forEach(fact => lines.push(`- ${fact}`));
  }

  const sourceSituation = asArray(facts.source_situation);
  if (sourceSituation.length) {
    lines.push('');
    lines.push('Quellenlage:');
    sourceSituation.forEach(fact => lines.push(`- ${fact}`));
  }

  const uncertain = asArray(facts.uncertain_points);
  if (uncertain.length) {
    lines.push('');
    lines.push('Unsichere/offene Punkte sauber kennzeichnen:');
    uncertain.forEach(fact => lines.push(`- ${fact}`));
  }

  const safe = asArray(facts.safe_article_points);
  if (safe.length) {
    lines.push('');
    lines.push('Sicher verwendbare Artikelpunkte:');
    safe.forEach(fact => lines.push(`- ${fact}`));
  }

  const lengthSupport = asArray(facts.length_support_points);
  if (lengthSupport.length) {
    lines.push('');
    lines.push('Punkte zur sinnvollen Artikellänge von 330 bis 390 Wörtern:');
    lengthSupport.forEach(fact => lines.push(`- ${fact}`));
  }

  const sourceNotes = asArray(facts.source_handling_notes);
  if (sourceNotes.length) {
    lines.push('');
    lines.push('Quellenhinweise:');
    sourceNotes.forEach(fact => lines.push(`- ${fact}`));
  }

  const doNotClaim = asArray(facts.do_not_claim);
  if (doNotClaim.length) {
    lines.push('');
    lines.push('Nicht behaupten:');
    doNotClaim.forEach(fact => lines.push(`- ${fact}`));
  }

  const structure = asArray(facts.recommended_article_structure);
  if (structure.length) {
    lines.push('');
    lines.push('Empfohlene Artikelstruktur:');
    structure.forEach(fact => lines.push(`- ${fact}`));
  }

  const viability = facts.minimum_article_viability || {};

  lines.push('');
  lines.push('Mindestlänge-Einschätzung:');
  lines.push(`can_write_330_words: ${Boolean(viability.can_write_330_words)}`);

  if (viability.reason) {
    lines.push(`Begründung: ${clean(viability.reason)}`);
  }

  if (Array.isArray(original.external_context_results) && original.external_context_results.length) {
    lines.push('');
    lines.push('Verwendete externe Treffer:');

    original.external_context_results.forEach((result, index) => {
      const source = clean(result.source_name) || clean(result.domain) || `Quelle ${index + 1}`;

      lines.push(`${index + 1}. ${source}`);
      if (result.title) lines.push(`Titel: ${clean(result.title)}`);
      if (result.url) lines.push(`URL: ${clean(result.url)}`);
    });
  }

  return lines.join('\n').trim();
}

function pickExternalCurrentStatus(original, facts) {
  const results = Array.isArray(original.external_context_results)
    ? original.external_context_results
    : [];

  if (!results.length) {
    return {
      source: '',
      title: clean(facts.current_status),
      date: '',
    };
  }

  const preferred =
    results.find(result => ['media', 'official'].includes(clean(result.source_type))) ||
    results[0];

  return {
    source: clean(preferred.url),
    title: clean(preferred.title),
    date: clean(preferred.date),
  };
}

const original =
  tryGetNodeJson('Normalize External Context Results') ||
  tryGetNodeJson('Prepare External Context Search') ||
  {};

const output = [];

for (const item of $input.all()) {
  const j = item.json || {};

  const rawText = extractTextFromOpenAiOutput(j);
  const facts = parseJsonLoose(rawText);

  if (!facts) {
    output.push({
      json: {
        ...original,

        external_editorial_context_parse_status: 'error',
        external_editorial_context_parse_error: 'Could not parse JSON from Extract External Editorial Context Facts',
        external_editorial_context_raw_output: rawText,

        external_context_briefing: clean(original.external_context_block),
        external_context_quality: 'unknown',
        external_context_ready: false,

        context_sources_external_count: Array.isArray(original.external_context_results)
          ? original.external_context_results.length
          : 0,
      },
    });
    continue;
  }

  const briefing = buildExternalBriefing(facts, original);
  const canWrite330Words = Boolean(facts.minimum_article_viability?.can_write_330_words);
  const quality = clean(facts.external_context_quality).toLowerCase();
  const currentStatus = pickExternalCurrentStatus(original, facts);

  output.push({
    json: {
      ...original,

      external_editorial_context_parse_status: 'ok',
      external_editorial_context_raw_output: rawText,
      external_editorial_context_facts: facts,

      external_context_quality: clean(facts.external_context_quality),
      external_context_current_status: clean(facts.current_status),
      external_context_main_news_angle: clean(facts.main_news_angle),

      external_context_visible_source_facts: asArray(facts.visible_source_facts),
      external_context_background_facts: asArray(facts.background_facts),
      external_context_source_situation: asArray(facts.source_situation),
      external_context_uncertain_points: asArray(facts.uncertain_points),
      external_context_safe_article_points: asArray(facts.safe_article_points),
      external_context_length_support_points: asArray(facts.length_support_points),
      external_context_source_handling_notes: asArray(facts.source_handling_notes),
      external_context_do_not_claim: asArray(facts.do_not_claim),
      external_context_recommended_article_structure: asArray(facts.recommended_article_structure),

      external_context_minimum_article_viability: canWrite330Words,
      external_context_minimum_article_viability_reason: clean(facts.minimum_article_viability?.reason),

      external_context_briefing: briefing,

      external_context_ready:
        canWrite330Words &&
        ['strong', 'usable'].includes(quality),

      context_sources_external_count: Array.isArray(original.external_context_results)
        ? original.external_context_results.length
        : 0,

      external_context_current_status_source: currentStatus.source,
      external_context_current_status_title: currentStatus.title,
      external_context_current_status_date: currentStatus.date,
    },
  });
}

return output;

// Parse Manual Article Card
// Erkennt fertig geschriebene Artikel aus Trello-Karten und bereitet sie für die bestehende WP-Strecke vor.
//
// Unterstützt:
// - HTML: <h1>, <h2>, <strong>, <p>
// - Markdown: **Lead**, ## Zwischenüberschrift, [Linktext](URL)
// - Manuelle Karten ohne <h1>: Kartentitel wird als WordPress-Titel verwendet
//
// Wichtig:
// - Artikeltext wird nicht KI-generiert.
// - Der Text wird nur technisch für WordPress bereinigt/formatiert.
// - Bei manuellen Karten wird der erste echte Absatz automatisch fett gesetzt.
// - XPoster wird NICHT manuell gesetzt. Das erledigt später die bestehende Logik automatisch.

function clean(value) {
  return String(value ?? '').trim();
}

function normalizeSpaces(value) {
  return clean(value)
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\t/g, ' ')
    .replace(/[ ]{2,}/g, ' ')
    .trim();
}

function decodeEntities(value) {
  return clean(value)
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#8222;/g, '„')
    .replace(/&#8220;/g, '“')
    .replace(/&#8221;/g, '“')
    .replace(/&#8211;/g, '–')
    .replace(/&#8212;/g, '—')
    .replace(/&#8217;/g, '’')
    .trim();
}

function stripHtml(value) {
  return decodeEntities(value)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function limitText(value, maxLength) {
  const text = stripHtml(value);

  if (text.length <= maxLength) return text;

  return text
    .slice(0, maxLength)
    .replace(/\s+\S*$/, '')
    .replace(/[,.!?;:]+$/, '')
    .trim();
}

function extractField(raw, labels) {
  const text = normalizeSpaces(raw);

  for (const label of labels) {
    const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    const regex = new RegExp(
      `(?:^|\\n)\\s*${escaped}\\s*:?\\s*\\n?([\\s\\S]*?)(?=\\n\\s*(?:Meta Description|Meta|Social|Fokus Keyphrase|Focus Keyphrase|Tags|Kategorie|Category|Quelle|Source)\\s*:|$)`,
      'i'
    );

    const match = text.match(regex);

    if (match && clean(match[1])) {
      return clean(match[1]);
    }
  }

  return '';
}

function removeOptionalFieldBlocks(raw) {
  let text = normalizeSpaces(raw);

  const labels = [
    'Meta Description',
    'Meta',
    'Social',
    'Fokus Keyphrase',
    'Focus Keyphrase',
    'Tags',
    'Kategorie',
    'Category',
    'Quelle',
    'Source',
  ];

  for (const label of labels) {
    const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    const regex = new RegExp(
      `\\n?\\s*${escaped}\\s*:?\\s*\\n?[\\s\\S]*?(?=\\n\\s*(?:${labels.map(l => l.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')})\\s*:|$)`,
      'gi'
    );

    text = text.replace(regex, '');
  }

  return text.trim();
}

function extractH1(raw) {
  const match = clean(raw).match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);

  if (match && clean(match[1])) {
    return stripHtml(match[1]);
  }

  return '';
}

function removeH1(raw) {
  return clean(raw)
    .replace(/<h1[^>]*>[\s\S]*?<\/h1>/i, '')
    .trim();
}

function markdownInlineToHtml(value) {
  let text = clean(value);

  // Markdown-Links: [Text](URL "optional")
  text = text.replace(
    /\[([^\]]+)\]\((https?:\/\/[^\s)"]+)(?:\s+"[^"]*")?\)/g,
    '<a href="$2">$1</a>'
  );

  // Bold: **Text**
  text = text.replace(/\*\*([\s\S]*?)\*\*/g, '<strong>$1</strong>');

  // Italic: _Text_
  text = text.replace(/_([^_\n]+)_/g, '<em>$1</em>');

  return text.trim();
}

function convertMarkdownBlocksToHtml(value) {
  const text = normalizeSpaces(value);

  if (!text) return '';

  const blocks = text
    .split(/\n{2,}/)
    .map(block => block.trim())
    .filter(Boolean);

  const htmlBlocks = [];

  for (const block of blocks) {
    const trimmed = block.trim();

    if (!trimmed) continue;

    // Bereits vorhandene HTML-Blöcke erhalten
    if (/^<h2[^>]*>[\s\S]*<\/h2>$/i.test(trimmed)) {
      htmlBlocks.push(trimmed);
      continue;
    }

    if (/^<h3[^>]*>[\s\S]*<\/h3>$/i.test(trimmed)) {
      htmlBlocks.push(trimmed.replace(/^<h3/i, '<h2').replace(/<\/h3>$/i, '</h2>'));
      continue;
    }

    if (/^<p[^>]*>[\s\S]*<\/p>$/i.test(trimmed)) {
      htmlBlocks.push(trimmed);
      continue;
    }

    if (/^<strong[^>]*>[\s\S]*<\/strong>$/i.test(trimmed)) {
      htmlBlocks.push(`<p>${trimmed}</p>`);
      continue;
    }

    if (/^<ul[^>]*>|^<ol[^>]*>|^<blockquote[^>]*>|^<figure[^>]*>|^<table[^>]*>/i.test(trimmed)) {
      htmlBlocks.push(trimmed);
      continue;
    }

    // Markdown H2
    if (/^##\s+/.test(trimmed)) {
      const heading = trimmed.replace(/^##\s+/, '').trim();
      htmlBlocks.push(`<h2>${markdownInlineToHtml(heading)}</h2>`);
      continue;
    }

    // Markdown H3 als H2 normalisieren
    if (/^###\s+/.test(trimmed)) {
      const heading = trimmed.replace(/^###\s+/, '').trim();
      htmlBlocks.push(`<h2>${markdownInlineToHtml(heading)}</h2>`);
      continue;
    }

    // Normaler Absatz
    htmlBlocks.push(`<p>${markdownInlineToHtml(trimmed).replace(/\n/g, '<br>')}</p>`);
  }

  return htmlBlocks.join('\n\n').trim();
}

function sanitizeArticleHtml(value) {
  let html = clean(value);

  html = html
    .replace(/<h1[^>]*>[\s\S]*?<\/h1>/gi, '')
    .replace(/\u00a0/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  html = convertMarkdownBlocksToHtml(html);

  html = html
    .replace(/<p>\s*<\/p>/gi, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  return html;
}

function ensureStrongFirstParagraph(html) {
  let value = clean(html);

  if (!value) return '';

  const firstParagraphMatch = value.match(/<p[^>]*>([\s\S]*?)<\/p>/i);

  if (!firstParagraphMatch) {
    return value;
  }

  const firstParagraphFull = firstParagraphMatch[0];
  const firstParagraphInner = firstParagraphMatch[1].trim();

  if (!firstParagraphInner) {
    return value;
  }

  // Wenn der erste Absatz bereits strong enthält, nichts ändern
  if (/<strong[^>]*>[\s\S]*?<\/strong>/i.test(firstParagraphInner)) {
    return value;
  }

  const newFirstParagraph = `<p><strong>${firstParagraphInner}</strong></p>`;

  return value.replace(firstParagraphFull, newFirstParagraph).trim();
}

function extractStrongLead(html) {
  const match = clean(html).match(/<strong[^>]*>([\s\S]*?)<\/strong>/i);

  if (match && clean(match[1])) {
    return stripHtml(match[1]);
  }

  return '';
}

function extractFirstParagraphText(html) {
  const pMatch = clean(html).match(/<p[^>]*>([\s\S]*?)<\/p>/i);

  if (pMatch && clean(pMatch[1])) {
    return stripHtml(pMatch[1]);
  }

  return stripHtml(html).slice(0, 220);
}

function buildMetaDescription(manualMeta, lead, articleHtml) {
  if (manualMeta) return limitText(manualMeta, 155);
  if (lead) return limitText(lead, 155);
  return limitText(extractFirstParagraphText(articleHtml), 155);
}

function buildSocial(manualSocial, title, lead) {
  if (manualSocial) return limitText(manualSocial, 260);

  const base = lead || title;
  if (!base) return '';

  const text = limitText(base, 210);

  if (title && !text.includes(title.slice(0, 25))) {
    return limitText(`${title} – ${text}`, 260);
  }

  return text;
}

function splitTags(value) {
  return clean(value)
    .split(/[,;\n|]+/)
    .map(tag => stripHtml(tag))
    .map(tag => tag.replace(/^#/, '').trim())
    .filter(Boolean);
}

function dedupe(values) {
  const output = [];
  const seen = new Set();

  for (const value of values) {
    const v = clean(value);
    if (!v) continue;

    const key = v.toLowerCase();
    if (seen.has(key)) continue;

    seen.add(key);
    output.push(v);
  }

  return output;
}

function extractNameCandidates(text) {
  const blacklist = new Set([
    'Der','Die','Das','Ein','Eine','Einer','Eines','Beim','Vom','Zum','Zur','Mit','Ohne',
    'Und','Oder','Auch','Wie','Laut','Nach','Neben','Genau','Klar','Sommer','Saison',
    'Bundesliga','Champions','League','Transfer','Transfers','Defensive','Offensive',
    'Nationalmannschaft','Traditionsklub','Gelsenkirchener','S04','Mailand','Podcast',
    'Medienberichten','Interessant','Parallel','Ausgangslage',
  ]);

  const plain = stripHtml(text);

  const words = plain
    .replace(/[^\p{L}\p{N}\s-]/gu, ' ')
    .split(/\s+/)
    .map(clean)
    .filter(Boolean);

  const names = [];

  for (let i = 0; i < words.length; i++) {
    const w1 = words[i];
    const w2 = words[i + 1];
    const w3 = words[i + 2];

    if (!/^[A-ZÄÖÜ][a-zäöüß-]{2,}$/.test(w1)) continue;
    if (blacklist.has(w1)) continue;

    if (
      w2 &&
      /^[A-ZÄÖÜ][a-zäöüß-]{2,}$/.test(w2) &&
      !blacklist.has(w2)
    ) {
      if (
        w3 &&
        /^[A-ZÄÖÜ][a-zäöüß-]{2,}$/.test(w3) &&
        !blacklist.has(w3)
      ) {
        names.push(`${w1} ${w2} ${w3}`);
      }

      names.push(`${w1} ${w2}`);
      names.push(w2);
    } else {
      names.push(w1);
    }
  }

  return dedupe(names);
}

function buildFocusKeyphrase(manualFocus, title, articleHtml) {
  if (manualFocus) return stripHtml(manualFocus);

  const candidates = extractNameCandidates(`${title}\n${articleHtml}`);

  if (candidates.length) return candidates[0];

  return stripHtml(title).split(/\s+/).slice(0, 3).join(' ');
}

function buildTags(manualTags, title, articleHtml, focusKeyphrase) {
  const tags = [];

  tags.push(...splitTags(manualTags));

  if (focusKeyphrase) tags.push(focusKeyphrase);

  const candidates = extractNameCandidates(`${title}\n${articleHtml}`);
  tags.push(...candidates.slice(0, 5));

  return dedupe(tags).slice(0, 10);
}

function extractSourceUrl(raw) {
  const manualSource = extractField(raw, ['Quelle', 'Source']);
  const fromManual = clean(manualSource).match(/https?:\/\/[^\s)]+/i);

  if (fromManual) return fromManual[0];

  const anyUrl = clean(raw).match(/https?:\/\/[^\s)]+/i);

  if (anyUrl) return anyUrl[0];

  return '';
}

function getCardText(j) {
  return (
    clean(j.original_text) ||
    clean(j.desc) ||
    clean(j.description) ||
    clean(j.trello_card_desc) ||
    ''
  );
}

const output = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const rawCardText = getCardText(j);

  const manualMeta = extractField(rawCardText, ['Meta Description', 'Meta']);
  const manualSocial = extractField(rawCardText, ['Social']);
  const manualFocus = extractField(rawCardText, ['Fokus Keyphrase', 'Focus Keyphrase']);
  const manualTags = extractField(rawCardText, ['Tags']);
  const manualCategory = extractField(rawCardText, ['Kategorie', 'Category']);

  const articleOnlyRaw = removeOptionalFieldBlocks(rawCardText);

  const h1Title = extractH1(articleOnlyRaw);

  const fallbackTitle =
    clean(j.final_title) ||
    clean(j.generated_title) ||
    clean(j.title) ||
    clean(j.trello_card_name);

  const manualTitle = h1Title || fallbackTitle;

  const articleWithoutH1 = removeH1(articleOnlyRaw);

  let manualArticleHtml = sanitizeArticleHtml(articleWithoutH1);
  manualArticleHtml = ensureStrongFirstParagraph(manualArticleHtml);

  const lead = extractStrongLead(manualArticleHtml) || extractFirstParagraphText(manualArticleHtml);

  const manualMetaDescription = buildMetaDescription(manualMeta, lead, manualArticleHtml);
  const manualSocialCaption = buildSocial(manualSocial, manualTitle, lead);
  const manualFocusKeyphrase = buildFocusKeyphrase(manualFocus, manualTitle, manualArticleHtml);
  const manualTagNames = buildTags(manualTags, manualTitle, manualArticleHtml, manualFocusKeyphrase);

  const sourceUrl = extractSourceUrl(rawCardText) || clean(j.original_url);

  const parseErrors = [];

  if (!manualTitle) {
    parseErrors.push('missing_title_h1_or_card_title');
  }

  if (!manualArticleHtml || stripHtml(manualArticleHtml).length < 250) {
    parseErrors.push('article_too_short_or_missing');
  }

  output.push({
