// Normalize Manual SEO Fields
// Parst den Output aus "Generate Manual SEO Fields"
// und führt ihn mit den Daten aus "Parse Manual Article Card" zusammen.
//
// Wichtig:
// - Der manuelle Artikel wird NICHT überschrieben.
// - OpenAI ergänzt nur SEO-/WP-Felder: Meta, Fokus-Keyphrase, Tags, Social.
// - Falls OpenAI kaputtes JSON oder keine Tags liefert, werden Tags robust aus Titel + Artikel extrahiert.
// - Danach kann der bestehende Node "Prepare WP Create Payload" weiterverwendet werden.

function clean(value) {
  return String(value ?? '').trim();
}

function stripHtml(value) {
  return clean(value)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#8222;/g, '„')
    .replace(/&#8220;/g, '“')
    .replace(/&#8221;/g, '“')
    .replace(/&#8211;/g, '–')
    .replace(/&#8212;/g, '—')
    .replace(/&#8217;/g, '’')
    .replace(/\s+/g, ' ')
    .trim();
}

function limitText(value, maxLength) {
  const text = stripHtml(value);

  if (text.length <= maxLength) return text;

  return text
    .slice(0, maxLength)
    .replace(/\s+\S*$/, '')
    .replace(/[,.!?;:]+$/, '')
    .trim();
}

function dedupe(values) {
  const output = [];
  const seen = new Set();

  for (const value of values) {
    const v = stripHtml(value).replace(/^#/, '').trim();
    if (!v) continue;

    const key = v.toLowerCase();
    if (seen.has(key)) continue;

    seen.add(key);
    output.push(v);
  }

  return output;
}

function extractTextFromOpenAiOutput(j) {
  if (typeof j === 'string') return j;

  if (typeof j.text === 'string') return j.text;
  if (typeof j.output_text === 'string') return j.output_text;
  if (typeof j.content === 'string') return j.content;
  if (typeof j.message === 'string') return j.message;
  if (typeof j.response === 'string') return j.response;

  if (Array.isArray(j.output)) {
    for (const out of j.output) {
      if (Array.isArray(out.content)) {
        for (const content of out.content) {
          if (typeof content.text === 'string') {
            return content.text;
          }
        }
      }
    }
  }

  if (Array.isArray(j.content)) {
    for (const content of j.content) {
      if (typeof content.text === 'string') return content.text;
      if (typeof content === 'string') return content;
    }
  }

  if (j.choices?.[0]?.message?.content) {
    return j.choices[0].message.content;
  }

  return '';
}

function parseJsonLoose(value) {
  let text = clean(value);

  if (!text) return null;

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    return JSON.parse(text);
  } catch (error) {}

  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace >= 0 && lastBrace > firstBrace) {
    const jsonText = text.slice(firstBrace, lastBrace + 1);

    try {
      return JSON.parse(jsonText);
    } catch (error) {}
  }

  return null;
}

function asArray(value) {
  if (Array.isArray(value)) {
    return value.map(stripHtml).filter(Boolean);
  }

  if (typeof value === 'string' && value.trim()) {
    return value
      .split(/[,;\n|]+/)
      .map(stripHtml)
      .filter(Boolean);
  }

  return [];
}

function tryGetNodeItems(nodeName) {
  try {
    return $(nodeName).all().map(item => item.json || {});
  } catch (error) {
    return [];
  }
}

function getFallbackByIndex(items, index) {
  if (index < items.length) return items[index];
  console.warn("[Normalize Manual SEO Fields] getFallbackByIndex: index " + index + " out of bounds (items.length=" + items.length + "), returning empty fallback");
  return { _fallback_warning: "index_out_of_bounds", _requested_index: index };
}

function normalizeMeta(value, fallback) {
  const chosen = clean(value) || clean(fallback);
  return limitText(chosen, 155);
}

function normalizeSocial(value, fallback) {
  const chosen = clean(value) || clean(fallback);
  return limitText(chosen, 260);
}

function normalizeFocus(value, fallback) {
  const chosen = stripHtml(value) || stripHtml(fallback);
  return chosen.slice(0, 80).trim();
}

function extractNameCandidates(text) {
  const plain = stripHtml(text);

  const blacklist = new Set([
    'Der','Die','Das','Ein','Eine','Einer','Eines','Beim','Vom','Zum','Zur','Mit','Ohne',
    'Und','Oder','Auch','Wie','Laut','Nach','Neben','Genau','Klar','Aktuell','Interessant',
    'Sommer','Saison','Bundesliga','Champions','League','Transfer','Transfers','Defensive',
    'Offensive','Innenverteidigung','Nationalmannschaft','Traditionsklub','Gelsenkirchener','S04',
    'FC','Artikel','News','Gerücht','Vertrag','Verletzung','Quelle','Bericht','Medienberichten',
    'Sport','Podcast','Hier','We','Go',
  ]);

  const words = plain
    .replace(/[^\p{L}\p{N}\s-]/gu, ' ')
    .split(/\s+/)
    .map(clean)
    .filter(Boolean);

  const names = [];

  for (let i = 0; i < words.length; i++) {
    const w1 = words[i];
    const w2 = words[i + 1];
    const w3 = words[i + 2];

    if (!/^[A-ZÄÖÜ][a-zäöüß-]{2,}$/.test(w1)) continue;
    if (blacklist.has(w1)) continue;

    if (
      w2 &&
      /^[A-ZÄÖÜ][a-zäöüß-]{2,}$/.test(w2) &&
      !blacklist.has(w2)
    ) {
      if (
        w3 &&
        /^[A-ZÄÖÜ][a-zäöüß-]{2,}$/.test(w3) &&
        !blacklist.has(w3)
      ) {
        names.push(`${w1} ${w2} ${w3}`);
      }

      names.push(`${w1} ${w2}`);
    }
  }

  return dedupe(names);
}

function extractClubCandidates(text) {
  const plain = stripHtml(text);

  const clubs = [
    'Newcastle United',
    'FC Barcelona',
    'Barcelona',
    'Inter Mailand',
    'Inter',
    'AC Mailand',
    'Real Madrid',
    'FC Liverpool',
    'Liverpool',
    'Manchester City',
    'Manchester United',
    'Arsenal',
    'Chelsea',
    'Tottenham',
    'Juventus',
    'Parma Calcio',
    'OSC Lille',
    'Paris Saint-Germain',
    'PSG',
  ];

  const found = [];

  for (const club of clubs) {
    const escaped = club.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`(^|[^\\p{L}\\p{N}])${escaped}([^\\p{L}\\p{N}]|$)`, 'iu');

    if (regex.test(plain)) {
      found.push(club);
    }
  }

  return dedupe(found);
}

function normalizeTags(value, fallbackTags, title, articleHtml, focusKeyphrase) {
  const blocked = new Set([
    'schalke',
    'schalke',
    'schalke',
    'schalke',
    'transfer',
    'transfers',
    'news',
    'gerücht',
    'gerüchte',
    'vertrag',
    'verträge',
    'verletzung',
    'bundesliga',
    'sport bild',
    'bild',
    'sky',
    'kicker',
    'tz',
    'fabrizio romano',
  ]);

  const articleText = `${title}\n${articleHtml}`;

  const extractedNames = extractNameCandidates(articleText);
  const extractedClubs = extractClubCandidates(articleText);

  const tags = dedupe([
    ...asArray(value),
    ...asArray(fallbackTags),
    focusKeyphrase,
    ...extractedNames,
    ...extractedClubs,
  ]);

  const filtered = tags.filter(tag => {
    const key = tag.toLowerCase();
    if (blocked.has(key)) return false;
    if (key.length < 2) return false;
    if (/^\d+$/.test(key)) return false;
    return true;
  });

  return dedupe(filtered).slice(0, 6);
}

