function clean(value) {
  return String(value ?? '').trim();
}

function pick(...values) {
  for (const value of values) {
    const cleaned = clean(value);
    if (cleaned) return cleaned;
  }
  return '';
}

function enc(value) {
  return encodeURIComponent(clean(value));
}

function extractBetween(text, startLabel, endLabels = []) {
  const source = String(text || '');
  const startIndex = source.indexOf(startLabel);

  if (startIndex === -1) return '';

  const afterStart = source.slice(startIndex + startLabel.length);

  let endIndex = afterStart.length;

  for (const label of endLabels) {
    const idx = afterStart.indexOf(label);
    if (idx !== -1 && idx < endIndex) {
      endIndex = idx;
    }
  }

  return afterStart.slice(0, endIndex).trim();
}

function makeId(...parts) {
  const base = parts.map(clean).filter(Boolean).join('|') || `${Date.now()}-${Math.random()}`;

  return Buffer
    .from(base)
    .toString('base64')
    .replace(/[^a-zA-Z0-9]/g, '')
    .slice(0, 40);
}

