parameters.jsCode:
return $input.all().map(inputItem => {
  const item = inputItem.json;

  let raw =
    item.text ||
    item.markdown ||
    item.articleText ||
    item.article_text ||
    item.content ||
    item.data?.text ||
    item.data?.markdown ||
    item.data?.articleText ||
    item.data?.content ||
    "";

  raw = String(raw || "").trim();

  function cleanApifyText(value) {
    return String(value)
      // Markdown-Links: [Text](URL) → Text
      .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
      // Markdown-Bilder entfernen
      .replace(/!\[[^\]]*\]\([^)]+\)/g, " ")
      // Überschriften-Markdown entfernen
      .replace(/^#{1,6}\s*/gm, "")
      // Fett/Kursiv-Markdown entfernen
      .replace(/\*\*/g, "")
      .replace(/\*/g, "")
      // typische UI-Zeilen raus
      .replace(/TTS-Player überspringen/gi, " ")
      .replace(/Text to Speech:[^\n]*/gi, " ")
      .replace(/Geschwindigkeit der Wiedergabe/gi, " ")
      .replace(/Artikel weiterlesen/gi, " ")
      // Bildzeilen / Fotozeilen grob entfernen
      .replace(/^Foto:\s.*$/gim, " ")
      .replace(/^Bild:\s.*$/gim, " ")
      // Whitespace normalisieren
      .replace(/\s+/g, " ")
      .trim();
  }

  const text = cleanApifyText(raw);

  item.article_text = text;
  item.article_text_length = text.length;
  item.full_text = text;
  item.full_text_length = text.length;
  item.article_extract_method = "apify_text";

  if (text.length >= 800) {
    item.content_status = "full_text_ok";
    item.full_fetch_status = "ok";
    item.full_fetch_error = "";
  } else {
    item.content_status = "needs_context";
    item.full_fetch_status = "failed";
    item.full_fetch_error = "Apify konnte keinen ausreichenden Artikeltext extrahieren.";
  }

  return { json: item };
});

return $input.all().map(item => {
  const j = item.json;

  const rawText = String(
    j.full_text ||
    j.apify_text ||
    j.text ||
    j.markdown ||
    ""
  );

  const cleanedText = rawText
    .replace(/TTS-Player überspringen/gi, "")
    .replace(/Text to Speech:.*?(\n|$)/gi, "")
    .replace(/Geschwindigkeit der Wiedergabe/gi, "")
    .replace(/Artikel weiterlesen/gi, "")
    .replace(/Foto:\s?.*/gi, "")
    .replace(/\s+/g, " ")
    .trim();

  return {
    json: {
      ...j,
      full_text: cleanedText,
      full_text_length: cleanedText.length,
      content_status: cleanedText.length >= 800 ? "full_text_ok" : "full_text_short",
      article_extract_method: "apify_text",
      full_fetch_status: cleanedText.length >= 800 ? "ok" : "failed",
      full_fetch_error: cleanedText.length >= 800 ? "" : "apify_text_too_short"
    }
  };
});

function cleanUrl(raw) {
  let url = String(raw || "").trim();

  const mdMatch = url.match(/\((https?:\/\/[^)\s"]+)/);
  if (mdMatch) url = mdMatch[1];

  url = url.split("](")[0];
  url = url.split("#")[0];
  url = url.split("?")[0];

  return url.trim();
}

return $input.all().map((item) => {
  const j = item.json;

  const mergeUrl = cleanUrl(
    j.merge_url ||
    j.apify_url ||
    j.url ||
    j.original_url ||
    j.input?.url ||
    j.request?.url
  );

  const text = String(
    j.apify_full_text ||
    j.article_text ||
    j.text ||
    j.full_text ||
    ""
  ).trim();

  return {
    json: {
      merge_url: mergeUrl,
      apify_full_text: text,
      apify_full_text_length: text.length,
      apify_content_status: text.length > 0 ? "full_text_ok" : "full_text_missing",
      apify_article_extract_method: text.length > 0 ? "apify_text" : "apify_no_real_article_text",
      apify_full_fetch_status: text.length > 0 ? "ok" : "failed",
      apify_full_fetch_error: text.length > 0 ? "" : "apify_text_missing_or_empty"
    }
  };
});

function cleanText(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}

return $input.all().map((item) => {
  const j = item.json;

  const articleText = cleanText(
    j.apify_full_text ||
    j.article_text ||
    j.full_text ||
    ""
  );

  const articleLength = articleText.length;

  return {
    json: {
      ...j,

      article_text: articleText,
      full_text: articleText,
      article_text_length: articleLength,
      full_text_length: articleLength,

      full_fetch_status: articleLength > 0 ? "ok" : "failed",
      full_fetch_error: articleLength > 0 ? "" : (j.apify_full_fetch_error || "apify_text_missing"),

      content_status: articleLength > 0 ? "full_text_ok" : "full_text_missing",
      article_extract_method: j.apify_article_extract_method || "apify_text"
    }
  };
});

return {
  json: {
    ...$json,
    _row_type: "current_article_item"
  }
};

const rows = $input.all().map(item => item.json);

const current = rows.find(row => row._row_type === "current_article_item");

if (!current) {
  throw new Error("Kein current_article_item gefunden. Prüfe Mark Current Article Item und Merge Original + Article Style Examples.");
}

const targetCluster = String(
  current.article_style_example_cluster ||
  current.style_example_cluster ||
  ""
).trim();

const targetTopicType = String(current.topic_type || "").trim();

const allExamples = rows
  .filter(row => row._row_type !== "current_article_item")
  .filter(row => row.active !== false)
  .filter(row => row.approved_example !== false);

function priorityValue(example) {
  const value = Number(example.priority);
  return Number.isFinite(value) ? value : 999;
}

function getUniqueKey(example) {
  return (
    example.id ||
    example.example_title ||
    `${example.topic_cluster || ""}_${example.subtype || ""}_${example.priority || ""}`
  );
}

function pickUnique(examples, limit, alreadySeen) {
  const picked = [];

  for (const example of examples) {
    const key = getUniqueKey(example);
    if (!key || alreadySeen.has(key)) continue;

    alreadySeen.add(key);
    picked.push(example);

    if (picked.length >= limit) break;
  }

  return picked;
}

const seen = new Set();

const exactClusterExamples = allExamples
  .filter(example => String(example.topic_cluster || "").trim() === targetCluster)
  .sort((a, b) => priorityValue(a) - priorityValue(b));

const sameTopicExamples = allExamples
  .filter(example => String(example.topic_type || "").trim() === targetTopicType)
  .filter(example => String(example.topic_cluster || "").trim() !== targetCluster)
  .sort((a, b) => priorityValue(a) - priorityValue(b));

const fallbackExamples = allExamples
  .filter(example => String(example.topic_cluster || "").trim() === "general_soft_news")
  .sort((a, b) => priorityValue(a) - priorityValue(b));

const anyExamples = allExamples
  .sort((a, b) => priorityValue(a) - priorityValue(b));

let selected = [];

selected.push(...pickUnique(exactClusterExamples, 2, seen));

if (selected.length < 2) {
  selected.push(...pickUnique(sameTopicExamples, 2 - selected.length, seen));
}

if (selected.length < 2) {
  selected.push(...pickUnique(fallbackExamples, 2 - selected.length, seen));
}

if (selected.length < 2) {
  selected.push(...pickUnique(anyExamples, 2 - selected.length, seen));
}

const examples = selected.slice(0, 2).map((example, index) => {
  return {
    index: index + 1,
    topic_cluster: example.topic_cluster || "",
    topic_type: example.topic_type || "",
    subtype: example.subtype || "",
    example_title: example.example_title || "",
    example_intro: example.example_intro || "",
    example_h2: example.example_h2 || "",
    example_article: example.example_article || "",
    style_notes: example.style_notes || "",
    structure_notes: example.structure_notes || ""
  };
});

const selectedArticleStyleExamples = examples.map(example => {
  return [
    `Beispiel ${example.index}`,
    `Cluster: ${example.topic_cluster}`,
    example.topic_type ? `Topic Type: ${example.topic_type}` : "",
    example.subtype ? `Subtype: ${example.subtype}` : "",
    example.example_title ? `Titel: ${example.example_title}` : "",
    example.example_intro ? `Einleitung: ${example.example_intro}` : "",
    example.example_h2 ? `H2: ${example.example_h2}` : "",
    example.style_notes ? `Stilnotiz: ${example.style_notes}` : "",
    example.structure_notes ? `Strukturnotiz: ${example.structure_notes}` : "",
    example.example_article ? `Beispielartikel (vollständig):\n${String(example.example_article).trim()}` : ""
  ]
    .filter(Boolean)
    .join("\n");
}).join("\n\n---\n\n");

delete current._row_type;

return [
  {
    json: {
      ...current,

      article_style_example_cluster: targetCluster || current.article_style_example_cluster || "",

      selected_article_style_examples: selectedArticleStyleExamples,
      selected_article_style_examples_count: examples.length,

      selected_article_style_examples_debug: examples.map(example => ({
        index: example.index,
        selected_title: example.example_title,
        selected_cluster: example.topic_cluster,
        selected_topic_type: example.topic_type,
        selected_subtype: example.subtype
      })),

      selected_article_style_examples_strategy: {
        target_cluster: targetCluster,
        target_topic_type: targetTopicType,
        exact_cluster_available: exactClusterExamples.length,
        same_topic_available: sameTopicExamples.length,
        fallback_available: fallbackExamples.length,
        total_examples_available: allExamples.length,
        selection_mode: "cluster_priority_with_safe_fallback"
      }
    }
  }
];

// Prepare Article Style Rules For Prompt
// Erstellt einen kompakten dynamischen Regelblock für die Artikelgenerierung.
// Ziel: nicht die neuesten Regeln nehmen, sondern die besten passenden Regeln.
// Auswahl-Logik:
// - approved + general + article_prompt/both
// - Score nach Priorität, Konfidenz, Änderungsstärke, Regeltyp, Zielprompt
// - Recency nur kleiner Bonus, niemals Hauptkriterium
// - ähnliche Regeln / gleiche Cluster reduzieren
// - maximal 10 Regeln für den Artikelprompt

const MAX_RULES_TOTAL = 10;

const MAX_PER_CLUSTER = {
  intro_transition: 1,
  repetitions: 1,
  schalke_focus: 1,
  compact_news: 1,
  article_structure: 1,
  source_handling: 1,
  quote_handling: 1,
  transfer_logic: 1,
  context_usage: 1,
  wording_style: 1,
  general: 2,
};

function clean(value) {
  return String(value ?? '').trim();
}

function normalizeText(value) {
  return clean(value)
    .toLowerCase()
    .replace(/[„“"‚‘’'`´]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function isUsefulPromptRule(ruleText) {
  const text = normalizeText(ruleText);

  if (!text) return false;

  const uselessPatterns = [
    'keine zusätzliche regel',
    'keine regel abgeleitet',
    'keine regel ableiten',
    'kein zusätzlicher regelbedarf',
    'kein verbesserungsbedarf',
    'sollte daraus keine zusätzliche',
    'sollte dafür keine zusätzliche',
    'generated und final identisch',
    'final und generated identisch',
    'artikel bereits identisch',
    'wenn artikel bereits identisch',
    'meta generated und final',
    'generated meta und final meta',
    'wenn meta generated und final',
    'wenn titel bereits identisch',
    'titel bereits identisch',
  ];

  return !uselessPatterns.some(pattern => text.includes(pattern));
}

function priorityScore(priority) {
  const value = clean(priority).toLowerCase();

  if (value === 'high') return 40;
  if (value === 'medium') return 25;
  if (value === 'low') return 10;

  return 0;
}

function confidenceScore(confidence) {
  const value = clean(confidence).toLowerCase();

  if (value === 'high') return 12;
  if (value === 'medium') return 6;
  if (value === 'low') return 2;

  return 0;
}

function changeLevelScore(changeLevel) {
  const value = clean(changeLevel).toLowerCase();

  if (value === 'major') return 14;
  if (value === 'medium') return 9;
  if (value === 'minor') return 3;
  if (value === 'none') return 0;

  return 0;
}

function ruleKindScore(ruleKind) {
  const value = clean(ruleKind).toLowerCase();

  if (value === 'derived_rule') return 10;
  if (value === 'prompt_improvement') return 7;

  return 4;
}

function ruleTypeScore(ruleType) {
  const value = clean(ruleType).toLowerCase();

  if (value === 'sharpen_existing_rule') return 10;
  if (value === 'new_rule') return 8;
  if (value === 'compliance_reminder') return 5;
  if (value === 'prompt_improvement') return 6;

  return 3;
}

function targetPromptScore(targetPrompt) {
  const value = clean(targetPrompt).toLowerCase();

  if (value === 'article_prompt') return 12;
  if (value === 'both') return 7;

  return 0;
}

function approvedExampleScore(value) {
  const text = clean(value).toLowerCase();

  if (text === 'ja' || text === 'yes' || text === 'true') return 8;

  return 0;
}

function recencyScore(approvedAt) {
  const dateValue = clean(approvedAt);
  if (!dateValue) return 0;

  const timestamp = Date.parse(dateValue);
  if (Number.isNaN(timestamp)) return 0;

  const ageDays = (Date.now() - timestamp) / (1000 * 60 * 60 * 24);

  if (ageDays <= 7) return 3;
  if (ageDays <= 30) return 2;
  if (ageDays <= 90) return 1;

  return 0;
}

function specificityScore(ruleText) {
  const text = clean(ruleText);
  const length = text.length;

  if (length < 40) return 0;
  if (length <= 120) return 6;
  if (length <= 240) return 10;
  if (length <= 420) return 7;

  return 3;
}

function getRuleCluster(rule) {
  const area = normalizeText(rule.rule_area);
  const text = normalizeText(rule.rule_text);
  const combined = `${area} ${text}`;

  if (
    combined.includes('einleitung') ||
    combined.includes('erster absatz') ||
    combined.includes('erster hauptabsatz') ||
    combined.includes('hauptabsatz') ||
    combined.includes('übergang') ||
    combined.includes('anschlusslogik') ||
    combined.includes('teaser')
  ) {
    return 'intro_transition';
  }

  if (
    combined.includes('wiederhol') ||
    combined.includes('redundanz') ||
    combined.includes('kernnachricht') ||
    combined.includes('kerninformation') ||
    combined.includes('nur einmal') ||
    combined.includes('nicht mehrfach')
  ) {
    return 'repetitions';
  }

  if (
    combined.includes('schalke fokus') ||
    combined.includes('schalke focus') ||
    combined.includes('schalke bezug') ||
    combined.includes('schalke relevanz') ||
    combined.includes('schalke relevant') ||
    combined.includes('warum das thema für den schalke') ||
    combined.includes('für schalke relevant') ||
    combined.includes('schalke aufhänger') ||
    combined.includes('redaktionelle aufhänger') ||
    area === 'schalke focus' ||
    area === 'schalke fokus' ||
    area === 'schalke_focus'
  ) {
    return 'schalke_focus';
  }

  if (
    combined.includes('verdicht') ||
    combined.includes('kompakt') ||
    combined.includes('kurze meldung') ||
    combined.includes('knappe meldung') ||
    combined.includes('wenige harte fakten') ||
    combined.includes('informationswert')
  ) {
    return 'compact_news';
  }

  if (
    combined.includes('struktur') ||
    combined.includes('dramaturgie') ||
    combined.includes('zwischenüberschrift') ||
    combined.includes('absatz') ||
    combined.includes('jeder absatz')
  ) {
    return 'article_structure';
  }

  if (
    combined.includes('quelle') ||
    combined.includes('quellen') ||
    combined.includes('source') ||
    combined.includes('medienbericht') ||
    combined.includes('journalist')
  ) {
    return 'source_handling';
  }

  if (
    combined.includes('zitat') ||
    combined.includes('zitate') ||
    combined.includes('direkte rede') ||
    combined.includes('interview') ||
    combined.includes('statement')
  ) {
    return 'quote_handling';
  }

  if (
    combined.includes('transfer') ||
    combined.includes('wechsel') ||
    combined.includes('leihe') ||
    combined.includes('kaufoption') ||
    combined.includes('vertrags') ||
    combined.includes('ablöse') ||
    combined.includes('abgang')
  ) {
    return 'transfer_logic';
  }

  if (
    combined.includes('kontext') ||
    combined.includes('hintergrund') ||
    combined.includes('bestehenden artikeln') ||
    combined.includes('einordnung')
  ) {
    return 'context_usage';
  }

  if (
    combined.includes('sprachlich') ||
    combined.includes('stil') ||
    combined.includes('formulierung') ||
    combined.includes('flüssiger') ||
    combined.includes('aufgebläht')
  ) {
    return 'wording_style';
  }

  return area || 'general';
}

function keywordSet(text) {
  const stopwords = new Set([
    'der', 'die', 'das', 'ein', 'eine', 'einer', 'eines', 'und', 'oder', 'aber',
    'wenn', 'dann', 'soll', 'sollen', 'muss', 'müssen', 'darf', 'dürfen',
    'nicht', 'nur', 'mit', 'von', 'für', 'bei', 'im', 'in', 'am', 'an', 'auf',
    'zu', 'als', 'nach', 'durch', 'werden', 'wird', 'wurde', 'dem', 'den',
    'des', 'ist', 'sind', 'wie', 'etwa', 'auch', 'mehr', 'klar', 'konkret'
  ]);

  return new Set(
    normalizeText(text)
      .split(' ')
      .filter(word => word.length >= 5 && !stopwords.has(word))
      .map(word =>
        word
          .replace(/wiederholungen/g, 'wiederhol')
          .replace(/wiederholung/g, 'wiederhol')
          .replace(/wiederholen/g, 'wiederhol')
          .replace(/verdichten/g, 'verdicht')
          .replace(/verdichtung/g, 'verdicht')
          .replace(/kompakter/g, 'kompakt')
          .replace(/einleitungen/g, 'einleitung')
          .replace(/hauptabsätze/g, 'hauptabsatz')
      )
  );
}

function jaccardSimilarity(aText, bText) {
  const a = keywordSet(aText);
  const b = keywordSet(bText);

  if (a.size === 0 || b.size === 0) return 0;

  let intersection = 0;

  for (const word of a) {
    if (b.has(word)) intersection++;
  }

  const union = new Set([...a, ...b]).size;

  return intersection / union;
}

function areSimilarRules(a, b) {
  const aCluster = getRuleCluster(a);
  const bCluster = getRuleCluster(b);

  const sameCluster = aCluster && bCluster && aCluster === bCluster;
  const similarity = jaccardSimilarity(a.rule_text, b.rule_text);

  if (sameCluster) return true;
  if (similarity >= 0.42) return true;

  return false;
}

function calculateRuleScore(rule) {
  return (
    priorityScore(rule.rule_priority) +
    confidenceScore(rule.ai_confidence) +
    changeLevelScore(rule.article_change_level) +
    ruleKindScore(rule.rule_kind) +
    ruleTypeScore(rule.rule_type) +
    targetPromptScore(rule.target_prompt) +
    approvedExampleScore(rule.approved_example) +
    specificityScore(rule.rule_text) +
    recencyScore(rule.approved_at)
  );
}

function isApprovedArticleRule(rule) {
  const status = clean(rule.rule_status);
  const generalization = clean(rule.generalization_level || 'general');
  const target = clean(rule.target_prompt);
  const ruleText = clean(rule.rule_text);

  return (
    status === 'approved' &&
    generalization === 'general' &&
    isUsefulPromptRule(ruleText) &&
    (target === 'article_prompt' || target === 'both')
  );
}

const rules = $input.all().map(item => item.json || {});

const approvedArticleRulesRaw = rules
  .filter(isApprovedArticleRule)
  .map(rule => {
    const cluster = getRuleCluster(rule);
    const score = calculateRuleScore(rule);

    return {
      ...rule,
      _cluster: cluster,
      _score: score,
    };
  });

const sortedRules = approvedArticleRulesRaw.sort((a, b) => {
  if (b._score !== a._score) return b._score - a._score;

  const aPriority = priorityScore(a.rule_priority);
  const bPriority = priorityScore(b.rule_priority);
  if (bPriority !== aPriority) return bPriority - aPriority;

  const aDate = Date.parse(clean(a.approved_at)) || 0;
  const bDate = Date.parse(clean(b.approved_at)) || 0;
  return bDate - aDate;
});

const selectedRules = [];
const clusterCounts = {};

for (const rule of sortedRules) {
  const cluster = rule._cluster || 'general';
  const currentClusterCount = clusterCounts[cluster] || 0;
  const allowedClusterCount = MAX_PER_CLUSTER[cluster] || 1;

  if (currentClusterCount >= allowedClusterCount) {
    continue;
  }

  const similarExisting = selectedRules.some(existing => areSimilarRules(rule, existing));

  if (similarExisting) {
    continue;
  }

  selectedRules.push(rule);
  clusterCounts[cluster] = currentClusterCount + 1;

  if (selectedRules.length >= MAX_RULES_TOTAL) {
    break;
  }
}

const articleRulesText = selectedRules
  .map((rule, index) => {
    const priority = clean(rule.rule_priority || 'medium');
    const area = clean(rule.rule_area || 'general');
    const kind = clean(rule.rule_kind || 'rule');
    const text = clean(rule.rule_text);

    return `${index + 1}. [${priority} / ${area} / ${kind}] ${text}`;
  })
  .join('\n');

const appliedAt = new Date().toISOString();

return [
  {
    json: {
      dynamic_style_rules_article:
        articleRulesText || 'Keine zusätzlichen gelernten Artikelregeln vorhanden.',

      dynamic_style_rules_article_used:
        articleRulesText || '',

      dynamic_style_rules_article_count:
        selectedRules.length,

      style_rules_applied_at:
        appliedAt,

      dynamic_style_rules_article_debug: {
        input_rules: rules.length,
        approved_article_rules_before_selection: approvedArticleRulesRaw.length,
        selected_rules: selectedRules.length,
        max_rules_total: MAX_RULES_TOTAL,
        max_per_cluster: MAX_PER_CLUSTER,
        cluster_counts: clusterCounts,
        selected_rule_ids: selectedRules.map(rule => clean(rule.style_rule_id)),
        selected_rule_scores: selectedRules.map(rule => ({
          style_rule_id: clean(rule.style_rule_id),
          score: rule._score,
          cluster: rule._cluster,
          priority: clean(rule.rule_priority),
          kind: clean(rule.rule_kind),
          type: clean(rule.rule_type),
          target_prompt: clean(rule.target_prompt),
          confidence: clean(rule.ai_confidence),
          article_change_level: clean(rule.article_change_level),
          approved_example: clean(rule.approved_example),
          approved_at: clean(rule.approved_at),
        })),
      },
    },
  },
];

// Keep Valid Article Input Item
// Entfernt leere Fallback-Items vor dem Merge mit den Style Rules.
// Ziel:
// - pro Trello-/Artikelkarte genau 1 valides Item weitergeben
// - leere Apify-/Full-Text-Fallbacks blockieren
// - bei mehreren validen Items pro Karte das beste Item behalten
// - keine leeren WordPress-Drafts erzeugen

function clean(value) {
  return String(value ?? '').trim();
}

function numberValue(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
}

function getStableKey(j) {
  return (
    clean(j.workflow_item_id) ||
    clean(j.trello_card_id) ||
    clean(j.wp_trello_card_id) ||
    clean(j.trello_card_url) ||
    clean(j.wp_trello_card_url) ||
    clean(j.original_url) ||
    clean(j.wp_source_url) ||
    clean(j.url) ||
    clean(j.merge_url) ||
    clean(j.generated_title) ||
    clean(j.wp_title) ||
    clean(j.title)
  );
}

function hasArticleIdentity(j) {
  return Boolean(
    clean(j.workflow_item_id) ||
    clean(j.trello_card_id) ||
    clean(j.wp_trello_card_id) ||
    clean(j.trello_card_url) ||
    clean(j.wp_trello_card_url)
  );
}

function hasArticleTitle(j) {
  return Boolean(
    clean(j.wp_title) ||
    clean(j.generated_title) ||
    clean(j.title) ||
    clean(j.trello_card_name) ||
    clean(j.original_title)
  );
}

function hasSourceUrl(j) {
  return Boolean(
    clean(j.wp_source_url) ||
    clean(j.original_url) ||
    clean(j.source_url) ||
    clean(j.url) ||
    clean(j.merge_url)
  );
}

function isEmptyFallback(j) {
  const hasIdentity = hasArticleIdentity(j);
  const hasTitle = hasArticleTitle(j);
  const hasUrl = hasSourceUrl(j);

  if (!hasIdentity && !hasTitle && !hasUrl) {
    return true;
  }

  const fullTextMissing =
    clean(j.content_status) === 'full_text_missing' ||
    clean(j.apify_content_status) === 'full_text_missing';

  const noText =
    numberValue(j.full_text_length) === 0 &&
    numberValue(j.article_text_length) === 0 &&
    !clean(j.full_text) &&
    !clean(j.article_text);

  const noUsefulMetadata =
    !hasIdentity &&
    !hasTitle &&
    !hasUrl;

  return fullTextMissing && noText && noUsefulMetadata;
}

function scoreItem(j) {
  let score = 0;

  if (hasArticleIdentity(j)) score += 100;
  if (hasArticleTitle(j)) score += 80;
  if (hasSourceUrl(j)) score += 60;

  if (clean(j.generated_social) || clean(j.wp_social)) score += 30;
  if (clean(j.original_text)) score += 20;

  if (numberValue(j.full_text_length) > 0 || clean(j.full_text)) score += 100;
  if (numberValue(j.article_text_length) > 0 || clean(j.article_text)) score += 80;

  if (clean(j.external_context_briefing)) score += 70;
  if (j.external_context_ready === true) score += 50;
  if (j.context_available === true) score += 50;

  if (clean(j.full_fetch_status) === 'success') score += 40;
  if (clean(j.full_fetch_status) === 'failed') score -= 20;

  if (clean(j.full_fetch_error)) score -= 15;
  if (clean(j.content_status) === 'full_text_missing') score -= 10;

  if (isEmptyFallback(j)) score -= 1000;

  return score;
}

const inputItems = $input.all();

const validItems = inputItems.filter(item => {
  const j = item.json || {};
  return !isEmptyFallback(j);
});

if (!validItems.length) {
  throw new Error('No valid article input item before Merge Article Input + Style Rules.');
}

const groups = new Map();

for (const item of validItems) {
  const j = item.json || {};
  const key = getStableKey(j);

  if (!key) {
    continue;
  }

  const score = scoreItem(j);
  const existing = groups.get(key);

  if (!existing || score > existing.score) {
    groups.set(key, {
      score,
      item,
    });
  }
}

const selectedItems = Array.from(groups.values())
  .sort((a, b) => b.score - a.score)
  .map(entry => {
    const j = entry.item.json || {};

    return {
      json: {
        ...j,
        article_input_filter_status: 'valid_article_item_selected',
        article_input_filter_score: entry.score,
        article_input_filter_debug: {
          input_items: inputItems.length,
          valid_items: validItems.length,
          selected_items: groups.size,
          removed_empty_fallback_items: inputItems.length - validItems.length,
        },
      },
    };
  });

if (!selectedItems.length) {
  throw new Error('No selected article input item after grouping before Merge Article Input + Style Rules.');
}

return selectedItems;

const rows = $input.all().map(item => item.json);

const current = rows.find(row => row._row_type === "current_rewrite_article_item");

if (!current) {
  throw new Error("Kein current_rewrite_article_item gefunden. Prüfe Mark Current Rewrite Article Item und Merge Original + Rewrite Article Style Examples.");
}

const targetCluster = String(
  current.article_style_example_cluster ||
  current.style_example_cluster ||
  ""
).trim();

const targetTopicType = String(current.topic_type || "").trim();

const allExamples = rows
  .filter(row => row._row_type !== "current_rewrite_article_item")
  .filter(row => row.active !== false)
  .filter(row => row.approved_example !== false);

function priorityValue(example) {
  const value = Number(example.priority);
  return Number.isFinite(value) ? value : 999;
}

function getUniqueKey(example) {
  return (
    example.id ||
    example.example_title ||
    `${example.topic_cluster || ""}_${example.subtype || ""}_${example.priority || ""}`
  );
}

function pickUnique(examples, limit, alreadySeen) {
  const picked = [];

  for (const example of examples) {
    const key = getUniqueKey(example);
    if (!key || alreadySeen.has(key)) continue;

    alreadySeen.add(key);
    picked.push(example);

    if (picked.length >= limit) break;
  }

  return picked;
}

const seen = new Set();

const exactClusterExamples = allExamples
  .filter(example => String(example.topic_cluster || "").trim() === targetCluster)
  .sort((a, b) => priorityValue(a) - priorityValue(b));

const sameTopicExamples = allExamples
  .filter(example => String(example.topic_type || "").trim() === targetTopicType)
  .filter(example => String(example.topic_cluster || "").trim() !== targetCluster)
  .sort((a, b) => priorityValue(a) - priorityValue(b));

const fallbackExamples = allExamples
  .filter(example => String(example.topic_cluster || "").trim() === "general_soft_news")
  .sort((a, b) => priorityValue(a) - priorityValue(b));

const anyExamples = allExamples
  .sort((a, b) => priorityValue(a) - priorityValue(b));

let selected = [];

selected.push(...pickUnique(exactClusterExamples, 2, seen));

if (selected.length < 2) {
  selected.push(...pickUnique(sameTopicExamples, 2 - selected.length, seen));
}

if (selected.length < 2) {
  selected.push(...pickUnique(fallbackExamples, 2 - selected.length, seen));
}

if (selected.length < 2) {
  selected.push(...pickUnique(anyExamples, 2 - selected.length, seen));
}

const examples = selected.slice(0, 2).map((example, index) => {
  return {
    index: index + 1,
    topic_cluster: example.topic_cluster || "",
    topic_type: example.topic_type || "",
    subtype: example.subtype || "",
    example_title: example.example_title || "",
    example_intro: example.example_intro || "",
    example_h2: example.example_h2 || "",
    example_article: example.example_article || "",
    style_notes: example.style_notes || "",
    structure_notes: example.structure_notes || ""
  };
});

const selectedArticleStyleExamples = examples.map(example => {
  return [
    `Beispiel ${example.index}`,
    `Cluster: ${example.topic_cluster}`,
    example.topic_type ? `Topic Type: ${example.topic_type}` : "",
    example.subtype ? `Subtype: ${example.subtype}` : "",
    example.example_title ? `Titel: ${example.example_title}` : "",
    example.example_intro ? `Einleitung: ${example.example_intro}` : "",
    example.example_h2 ? `H2: ${example.example_h2}` : "",
    example.style_notes ? `Stilnotiz: ${example.style_notes}` : "",
    example.structure_notes ? `Strukturnotiz: ${example.structure_notes}` : "",
    example.example_article ? `Beispielartikel (vollständig):\n${String(example.example_article).trim()}` : ""
  ]
    .filter(Boolean)
    .join("\n");
}).join("\n\n---\n\n");

delete current._row_type;

return [
  {
    json: {
      ...current,

      article_style_example_cluster: targetCluster || current.article_style_example_cluster || "",

      selected_article_style_examples: selectedArticleStyleExamples,
      selected_article_style_examples_count: examples.length,

      selected_article_style_examples_debug: examples.map(example => ({
        index: example.index,
        selected_title: example.example_title,
        selected_cluster: example.topic_cluster,
        selected_topic_type: example.topic_type,
        selected_subtype: example.subtype
      })),

      selected_article_style_examples_strategy: {
        target_cluster: targetCluster,
        target_topic_type: targetTopicType,
        exact_cluster_available: exactClusterExamples.length,
        same_topic_available: sameTopicExamples.length,
        fallback_available: fallbackExamples.length,
        total_examples_available: allExamples.length,
        selection_mode: "cluster_priority_with_safe_fallback"
      }
    }
  }
];

return {
  json: {
    ...$json,
    _row_type: "current_rewrite_article_item"
  }
};

// Code-Node "WP Meta Body bauen" – vor den HTTP-Node "Update WP Meta Fields" hängen.
// Baut das Meta-Objekt sauber in JS und gibt es als $json.wp_meta_body zurück.

const j = $json;

const title = String(
  j.trello_card_name || j.wp_create_title || j.final_title ||
  j.wp_title || j.generated_title || j.title || ''
).trim();

const social = String(j.wp_social || j.generated_social || '').trim();

const match = title.match(/^(.+?)([:!?])\s+(.+)$/);

// cleverpush_title: alles vor dem ersten :, !, ? (bei : ohne Satzzeichen, sonst mit)
let cleverpushTitle = title;
if (match) {
  const firstPart = match[1].trim();
  const separator = match[2];
  cleverpushTitle = separator === ':' ? firstPart : `${firstPart}${separator}`;
}

// cleverpush_text: Teil nach dem Trenner, sonst Social-Text, plus passendes Emoji
const text = match ? match[3].trim() : social;
const emojiSource = `${title} ${social} ${text}`;

let emoji = ' 👀';
if (/hammer|mega|sensation|wahnsinn|explosion|irrsinn|rekord|knall|bombe|breaking|einigung erzielt|durchbruch|kurz vor verpflichtung|steht vor verpflichtung|millionenpaket|mega-deal|top-transfer|weltstar/i.test(emojiSource)) {
  emoji = ' 🤯';
} else if (/verletzung|verletzt|ausfall|fällt aus|faellt aus|rückschlag|rueckschlag|schock|sorge|angeschlagen|operation|op nötig|op noetig|zwangspause|verletzungspause|droht auszufallen|krank|fehlt\s+(?:verletzt|wegen|aufgrund)|nicht dabei|krise|pleite|niederlage|frust|bitter/i.test(emojiSource)) {
  emoji = ' 😩';
} else if (/zoff|streit|ärger|aerger|eskalation|kritik|attacke|wut|bricht schweigen|deutliche worte|klare ansage|überraschung|ueberraschung|plötzlich|ploetzlich|brisant|wirbel|pikant|enthüllt|enthuellt|geheimplan|wende|absage|blockade/i.test(emojiSource)) {
  emoji = ' 😳';
} else if (/verlängert|verlaengert|verlängerung|verlaengerung|comeback|zurück|zurueck|rückkehr|rueckkehr|traumtor|jubel|lob|begeistert|glänzt|glaenzt|stark|überragend|ueberragend|topform|liebling|held|perfekt|freut sich|happy|gute nachricht/i.test(emojiSource)) {
  emoji = ' 😍';
} else if (/transfer|wechsel|angebot|interesse|poker|deal|ablöse|abloese|abgang|zugang|leihe|kaufoption|verpflichtung|verhandlungen|wechselwunsch|ausstiegsklausel/i.test(emojiSource)) {
  emoji = ' 🧐';
}

const cleverpushText = `${text}${emoji}`.trim();

const wp_meta_body = {
  meta: {
    _yoast_wpseo_metadesc: j.wp_yoast_meta_description || '',
    _yoast_wpseo_focuskw: j.wp_yoast_focus_keyphrase || '',
    _yoast_wpseo_focuskeywords: j.wp_yoast_related_keyphrases_json || '[]',
    _jd_twitter: j.wp_xposter_text || '',
    _wpt_post_this: 'yes',
    _wpt_twitter_card: 'summary_large_image',
    _wpt_omit_services: ['mastodon', 'bluesky'],
    cleverpush_title: cleverpushTitle,
    cleverpush_text: cleverpushText
  }
};

return [{ json: { ...j, wp_meta_body } }];

// ============================================================
// Validate Fulltext Content
// Prüft ob der gezogene Artikeltext echter Body oder
// Boilerplate/FAQ-Gerippe ist.
// SCHWELLENWERTE — hier justieren:
// ============================================================
const MIN_CLEAN_LENGTH       = 400;   // Min. Zeichen nach Boilerplate-Abzug
const MAX_BOILERPLATE_RATIO  = 0.50;  // Max. Anteil Boilerplate am Rohtext (0–1)
const MIN_HEADLINE_KEYWORDS  = 1;     // Mindest-Anzahl Headline-Keywords im Body
const MIN_HEADLINE_WORD_LEN  = 4;     // Nur Wörter dieser Länge prüfen
// ============================================================

const BOILERPLATE_PHRASES = [
  'häufig gestellte fragen',
  'frequently asked questions',
  'diese seite beinhaltet affiliate',
  'affiliate-links',
  'werbung werbung',
  'fc hollywood',
  'der schalke wurde am',
  'schalke wurde am',
  'veltins-arena',
  'alle rechte vorbehalten',
  'copyright ©',
  '© spox',
  '© sport1',
  '© bild',
  'in unserem datenschutzhinweis',
  'für weitere informationen besuche',
  'geschwindigkeit der wiedergabe',
  'tts-player überspringen',
  'text to speech',
  'artikel weiterlesen',
];

const STOP_WORDS = new Set([
  'der','die','das','ein','eine','und','oder','aber','für','mit',
  'von','bei','im','an','auf','in','zu','ist','hat','war','wird',
  'er','sie','es','wir','den','dem','des','als','am','aus','zum',
  'zur','nach','vor','über','unter','auch','noch','nicht','so','wie',
  'beim','vom','beim','sein','wird','sind','haben','wurden','durch',
  'fc','s04','schalke','gelsenkirchen','bundesliga','saison','transfer','news',
  'beim','beim','beim',
]);

return $input.all().map(item => {
  const j = item.json;

  const rawText  = String(j.full_text || j.article_text || '');
  const rawLower = rawText.toLowerCase();

  // ── Signal 1: Boilerplate-Anteil ──────────────────────
  let boilerplateCharCount = 0;
  const boilerplateHits = [];
  for (const phrase of BOILERPLATE_PHRASES) {
    const p = phrase.toLowerCase();
    if (rawLower.includes(p)) {
      boilerplateHits.push(phrase);
      const occurrences = rawLower.split(p).length - 1;
      boilerplateCharCount += p.length * occurrences;
    }
  }
  const totalLength = rawLower.length || 1;
  const boilerplateRatio = Math.min(boilerplateCharCount / totalLength, 1);

  // ── Signal 2: FAQ am Textanfang ───────────────────────
  const textStart = rawLower.slice(0, 600);
  const faqAtStart = /häufig gestellte fragen|frequently asked questions/.test(textStart);

  // ── Signal 3: Bereinigter Text (nach FAQ-Block) ───────
  let cleanText = rawText;
  cleanText = cleanText.replace(/häufig gestellte fragen[\s\S]*$/i, '');
  cleanText = cleanText.replace(/frequently asked questions[\s\S]*$/i, '');
  cleanText = cleanText.replace(/copyright\s*©[^\n]*/gi, '');
  cleanText = cleanText.replace(/alle rechte vorbehalten[^\n]*/gi, '');
  cleanText = cleanText.replace(/diese seite beinhaltet affiliate[^\n]*/gi, '');
  cleanText = cleanText.replace(/© spox[^\n]*/gi, '');
  cleanText = cleanText.trim();
  const cleanLength = cleanText.length;

  // ── Signal 4: FAQPage im JSON-LD ──────────────────────
  let hasFaqPageJsonLd = false;
  try {
    const jsonLd = j.metadata?.jsonLd || j.jsonLd || [];
    if (Array.isArray(jsonLd)) {
      hasFaqPageJsonLd = jsonLd.some(e =>
        String(e?.['@type'] || '').toLowerCase() === 'faqpage'
      );
    }
  } catch (_) {}

  // ── Signal 5: Headline-Keywords im Body ───────────────
  const headline = String(
    j.trello_card_name || j.original_title || j.title || j.wp_title || ''
  ).toLowerCase().replace(/[^\w\säöüß]/g, ' ');

  const headlineWords = headline
    .split(/\s+/)
    .filter(w => w.length >= MIN_HEADLINE_WORD_LEN && !STOP_WORDS.has(w));

  let keywordsFound = 0;
  for (const w of headlineWords) {
    if (rawLower.includes(w)) keywordsFound++;
  }
  const keywordsOk = headlineWords.length === 0 || keywordsFound >= MIN_HEADLINE_KEYWORDS;

  // ── Fehlschlag-Entscheidung ────────────────────────────
  const failReasons = [];

  if (hasFaqPageJsonLd && boilerplateRatio > 0.15) {
    failReasons.push('faq_page_json_ld_with_boilerplate');
  }
  if (cleanLength < MIN_CLEAN_LENGTH) {
    failReasons.push('too_short_after_cleanup');
  }
  if (boilerplateRatio > MAX_BOILERPLATE_RATIO) {
    failReasons.push('high_boilerplate_ratio');
  }
  if (faqAtStart && cleanLength < MIN_CLEAN_LENGTH * 2) {
    failReasons.push('faq_at_start_insufficient_content');
  }
  if (!keywordsOk) {
    failReasons.push('headline_keywords_missing');
  }

  const fulltextOk = failReasons.length === 0;

  // JSON-LD Teaser-Fallback ablegen (kein Auto-Artikel, nur für manuellen Zugriff)
  let jsonLdFallbackDescription = '';
  try {
    const jsonLd = j.metadata?.jsonLd || j.jsonLd || [];
    if (Array.isArray(jsonLd)) {
      const news = jsonLd.find(e =>
        String(e?.['@type'] || '').toLowerCase() === 'newsarticle'
      );
      if (news) {
        jsonLdFallbackDescription = String(news.description || news.headline || '');
      }
    }
  } catch (_) {}

  return {
    json: {
      ...j,
      fulltext_ok: fulltextOk,
      fulltext_fail_reason: failReasons.join(', ') || '',
      fulltext_boilerplate_ratio: Math.round(boilerplateRatio * 100) / 100,
      fulltext_boilerplate_hits: boilerplateHits,
      fulltext_clean_length: cleanLength,
      fulltext_keywords_found: keywordsFound,
      fulltext_headline_words_checked: headlineWords,
      fulltext_has_faq_json_ld: hasFaqPageJsonLd,
      fulltext_faq_at_start: faqAtStart,
      // JSON-LD Teaser als Fallback-Rohmaterial (nicht für Auto-Artikel)
      fulltext_jsonld_fallback_description: jsonLdFallbackDescription,
      // content_status korrigieren wenn fälschlich positiv
      content_status: !fulltextOk ? 'boilerplate_only' : j.content_status,
    },
  };
});

// Bereitet den Trello-Karten-Umbenenn-Payload vor.
// Vermeidet doppelten Präfix bei erneutem Lauf.
const FAIL_PREFIX = '⚠️ Fulltext nicht abrufbar — ';

return $input.all().map(item => {
  const j = item.json;

  const originalName = String(
    j.trello_card_name || j.card_name || j.original_title || j.wp_title || j.title || ''
  ).trim();

  // Doppel-Präfix verhindern
  const newName = originalName.startsWith(FAIL_PREFIX)
    ? originalName
    : `${FAIL_PREFIX}${originalName}`;

  const cardId = String(
    j.trello_card_id || j.wp_trello_card_id || j.id || ''
  ).trim();

  return {
    json: {
      ...j,
      trello_rename_card_id: cardId,
      trello_rename_new_name: newName,
      trello_rename_original_name: originalName,
    },
  };
});
